window.__D("text/maamarei-admur-hazaken/c003",{"p":[[2100490308,"העליונים הנ\"ל אלא שבגלות הוא בהתלבשות ע' שרים כו' כנ\"ל ע\"כ אמר כי הנני בא ושכנתי כו' ע\"י המצות שעשתה כל ימי הגלות כו' וד\"ל. אך הנה להבין טעם לעלי' גדולה הזאת שאמר כי הנני בא כו' דמשמעו שבא יבא בעצמו ובכבודו דוקא כו' הנה יובן ענין הידוע בפי'<sup data-n=\"1440\">46</sup> ישכיל עבדי ירום ונשא וגבה מאד שהן ה' עליות לנוק' ומאד היא עלי' היותר עליונה מכולם והוא בבחי' פנימי' ע\"י שהוא בחי' פנימי' א\"א כו' כי מאד אותיו' אדם בהיפוך אתוון לפי שאדם היינו כשכלול דכר<sup data-n=\"1441\">47</sup> ונוק' כחדא כמ\"ש בזהר והיינו ע\"י ענין יחוד מ\"ן ומ\"ד אבל לע\"ל יהי' האור מבחי' פנימי' ע\"י כו' שהוא למעלה מעלה מבחי' היחודים דמ\"נ ומ\"ד וכמ\"ש<sup data-n=\"1442\">48</sup> במ\"א בענין המאמר באתי לגני כו' אכלתי אבל באתרי' לאו אורחא למיכל כו' כי העוה\"ב<sup data-n=\"1443\">49</sup> אין בו אכילה ושתי' כמו ביו\"כ שנק' שבת שבתון לפי שעליי' המל' אז בבחי' פנימי' הכתר שאין שם בחי' אכילה לברר בירורי' כו' וכן אין שם בחי' היחוד שנמשל לאכילה כידוע בסה\"ק<sup data-n=\"1444\">50</sup> ולהיות כי עליי' המל' תהי' בבחי' פנימי' הכתר לע\"ל, וזהו שא' ישכיל עבדי כו' שלא תקבל המל' ע\"י המדו' דז\"א כמו עכשיו אלא יהי' זו\"נ שוין בקומתן כו' ועוד תעלה יותר במעלה ומדריגה והוא כמ\"ש וגבה מאד שבחי' מאד הוא בחי' פנימי' הכתר יאיר במל' דוקא וכידוע דהארת משיח יהי' מאור פנימי' עתיק וכמ\"ש ונחה<sup data-n=\"1445\">51</sup> עליו רוח כו' והריחו ביראת ה' כו' ופי' והריחו שיהי' בו הארת בחי' חוטמא<sup data-n=\"1446\">52</sup> דפרדשקא כו' הנז' באד\"ר שהוא בחי' פנימי' ע\"י וכמ\"ש ותהילתי<sup data-n=\"1447\">53</sup> אחטם לך כו' וע\"כ יהי' מורח<sup data-n=\"1448\">54</sup> ודאין וכמ\"ש במ\"א וד\"ל. וזהו שאמר כי הנני בא ושכנתי בתוכך נאום ה' פי' נאום ה' הוא בחי' דיבור העליון שמאיר בו הוי' דז\"א כו' וזהו פי' נאום הוי' נאום של הוי' כי עכשיו מקבל המל' מז\"א בעלה כו' אבל לע\"ל דכתיב והי'<sup data-n=\"1449\">55</sup> אור הלבנה כאור החמה כו' ויהיו שוין בקומתן כמו שהייתה קודם שמיעטה הירח ע\"א שנאמר ויברא<sup data-n=\"1450\">56</sup> ה' אלקים שני המאורות הגדולים כו' אזי גם המל' מקבלת מה' אלקים שהוא מבחי' יחוד או\"א כמו ז\"א, וזהו פי' עלי' האמצעי' בכלל באומרו וירום ונשא כו' (וארז\"ל וירום<sup data-n=\"1451\">57</sup> מאברהם כו') ואח\"כ באלף הז' יהי' עוד עלי' שלישי' למל' בכלל והוא בחי' מאד הנ\"ל שבבחי' פנימי' ע\"י שיאיר במשיח כו', וזהו כי הנני בא בעצמי ובכבודי ושכנתי בנאום ה' שהוא המל' הנק' דיבור כידוע וד\"ל.",[["1440","46","<b>בפי' ישכיל עבדי ירום ונשא וגבה מאד</b>: ישעי' נב, יג. וראה מאמרי אדה\"א נביאים וכתובים ע' ר. וש\"נ."],["1441","47","<b>דכר ונוק' כחדא כמ\"ש בזוהר</b>: ראה זהר פ' ויקרא."],["1442","48","<b>וכמ\"ש במ\"א בענין המאמר באתי לגני</b>: שה\"ש ה, א. ראה זהר פינחס רמא, סע\"ב. סידור עם דא\"ח כו, ג ואילך."],["1443","49","<b>העוה\"ב אין בו אכילה ושתי'</b>: ראה ברכות יז, א."],["1444","50","<b>בסה\"ק</b>: בספרי הקבלה."],["1445","51","<b>ונחה עליו רוח כו'</b>: ישעי' יא, ב."],["1446","52","<b>חוטמא דפרדשקא כו' הנז' באד\"ר</b>: אדרא זוטא רפט, א."],["1447","53","<b>ותהילתי אחטם לך</b>: ישעי' מח, ט."],["1448","54","<b>מורח ודאין וכמ\"ש במ\"א</b>: ראה סנהדרין צג, ב. וראה תו\"א מקץ לד, א."],["1449","55","<b>והי' אור הלבנה כאור החמה</b>: ישעי' ל, כו."],["1450","56","<b>ויברא ה' אלקים את שני המאורות הגדולים</b>: בראשית א, טז."],["1451","57","<b>וארז\"ל וירום מאברהם</b>: במאמרי אדה\"א במדבר ח\"ב ע' תיג בשם הזהר. וראה תנחומא תולדות יד. יל\"ש ישעי' נב, יג (רמז תעו)."]]],[2100490309,"<b>אך</b> עדיין י\"ל איך יהי' אופן זה שיוכל בחי' הדיבור לקבל מעצמות המאציל למעלה גם מבחי' אורות דאו\"א כו', הנה זה הענין יובן בדוגמא כזאת שאנו מוצאי' שכבר הי' לעולמי' והוא בנשמת מרע\"ה<sup data-n=\"1452\">58</sup> שגם בו הי' הארת משיח כי אדם ומאד הוא אותיות אדם<sup data-n=\"1453\">59</sup> דוד ומשיח או משיח אדם דוד בהיפוך אתוון וזה תלוי בתיקון החטא דאדה\"ר שלפי החטא כך נתגשם העולם מפני שירד זוהמא של נחש כו' וקטרג עד שלא הי' יכול להיות שלימות עד משיח לע\"ל והיינו אדם דוד משיח אבל לע\"ל יתברר זוהמא של נחש כו' ויהיה בהיפוך מאד כמו שהוא למעלה בכתר כך יהי' במל' וע\"כ הוא אותיות מאד משיח אדם דוד, דוד הוא מל' ומאיר בו מבחי' פנימי' הכתר שהוא הארת משיח מבחי' חוטמא וד\"ל. והנה בחי' נשמת משה<sup data-n=\"1454\">60</sup> הי' מבחי' השמיטה הראשונה שלפני זאת השמיטה והוא משמיטת החסד וכמ\"ש מן המים משיתיהו כו' וכמ\"ש במ\"א וע\"כ הי' ביכולתו לתקן הפגם דחטא אדה\"ר, ומה שיהי' במשיח לע\"ל שהוא כמו שהי' אדה\"ר קודם החטא גם במשה הי' זאת המדריגה כו' והוא להיותו מבחי' שם מ\"ה דא\"ק וכמ\"ש מה<sup data-n=\"1455\">61</sup> שמו כו' שהוא אותיו' משה כו' וכמ\"ש במ\"א וע\"כ נאמר בו משה<sup data-n=\"1456\">62</sup> ידבר והאלקים יעננו בקול וארז\"ל בקולו<sup data-n=\"1457\">63</sup> של משה דהיינו שהי' אוא\"ס שוכן ומתלבש בקולו של משה ממש כענין שכינה<sup data-n=\"1458\">64</sup> מדברת מתוך גרונו של משה כו' והוא לפי שהי' מבחי' שם מ\"ה עד שאינו תופס מקום כלל וכלל רק הי' קולו בחי' כלי בעלמא לאור אלקי השוכן בו ומדבר בו ע\"כ הי' קול ה' ממש בדיבור של משה והוא ע\"י התלבשות בקולו של משה וכמ\"ש משה ידבר והאלקי' יעננו בקול בקולו של משה וד\"ל. ולזה הטעם א' משה בפ' והי' אם שמוע כו' ונתתי<sup data-n=\"1459\">65</sup> מטר ארצכם כו' ונתתי<sup data-n=\"1460\">66</sup> עשב בשדך כו' כאלו<sup data-n=\"1461\">67</sup> הוא הנותן ואין זה בחי' פירוד כלל כי אור א\"ס עצמו הוא שמדבר בגרונו של משה ואו' ונתתי מטר כו' כי לעוצם הבטול קולו דמשה לא הי' דבר נפרד עד שמחשב ליש ודבר נבדל חוץ מאור א\"ס וכאלו קול ה' מדבר בו בלבד כו' וד\"ל. וכדוגמא זו יובן למשכיל למעלה איך שיוכל להיות עילוי בחי' הדיבור העליון שהוא בחי' מל' עד שאור פנימי' הכתר יאיר בו ויהי' הדיבור בחי' כלי בעלמא לעצמו' אור המאציל בלתי יחשב כלל וכלל לדבר נבדל לעצמו כו' וכנ\"ל בקולו של משה. וזהו כי הנני בא ושכנתי בתוכך נאום ה' ממש ע\"ד הנ\"ל וד\"ל.",[["1452","58","<b>מרע\"ה. . הארת משיח</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קצג ואילך. שע\"ת נו, ד ובהנסמן במ\"מ לשם."],["1453","59","<b>אדם דוד ומשיח</b>: רקאנטי בראשית א, כו [ירושלים תשכ\"א ז, ג]. ספר הגלגולים פס\"ב בשם ספר הקנה. מאמרי אדה\"א דברים ח\"א ע' לד. וש\"נ. תו\"ח בראשית לב, ד. נח עו, ב. ויחי רלז, ג. רלח, ד."],["1454","60","<b>משה. . השמיטה הראשונה</b>: ראה תו\"א שמות נא, ד. תו\"ח שמות [הוצאת קה\"ת תשס\"ג] מג, ב. וש\"נ."],["1455","61","<b>מה שמו אותיות משה</b>: ראה תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] א, ג. מאמרי אדה\"א ויקרא ח\"א ע' טז."],["1456","62","<b>משה ידבר והאלקים יעננו בקול</b>: יתרו יט, יט."],["1457","63","<b>בקולו של משה</b>: ברכות מה, א."],["1458","64","<b>שכינה מדברת</b>: נסמן לעיל ע' יג."],["1459","65","<b>ונתתי מטר ארצכם</b>: ואתחנן יא, יד."],["1460","66","<b>ונתתי עשב בשדך</b>: שם טו."],["1461","67","<b>כאילו הוא הנותן</b>: ראה גם לקו\"ת בחוקותי נ, א."]]],[2100490310,"<b>ובכ\"ז</b> יובן ג\"כ שרש ענין ולציון יאמר איש<sup data-n=\"1462\">68</sup> ואיש יולד בה והוא יכוננה עליון דהנה מ\"ש כי הנני בא ושכנתי כו' הוא ע\"י אתדל\"ע שמצד עצמו שאין אתדל\"ת מגיע לשם כלל וכמ\"ש למעני למעני כו' וע\"כ היא הנותנת שיהי' האור במל' בבחי' פנימי' דע\"י כנ\"ל, וזהו שיתגלה לע\"ל במל' דכתיב ונגלה<sup data-n=\"1463\">69</sup> כבוד ה' כו' וכנ\"ל שזהו נחמת הנביא באמרו רני ושמחי בת ציון כו', אך הנה אעפ\"י שיהי' אתדל\"ע מצד עצמו מ\"מ גם מה שעשו ישראל מצות מעשיות בכל ימי הגלות לא יגרע אורם ח\"ו והגם שעכשיו הוא בהעלם אבל לע\"ל יתגלה מן ההעלם, ולהיות שזהו אשה<sup data-n=\"1464\">70</sup> מזרעת תחלה הרי יולדת זכר והוא מה שאמר ולציון יאמר איש פי' איש זכר שהוא ע\"י המצות ביחודי' עליונים והיינו מה שתהא אור<sup data-n=\"1465\">71</sup> הלבנה כאור החמה שוין בקומתן שתהי' בבחי' משפיע ג\"כ כמו ז\"א ולא בבחי' מקבל מז\"א כנ\"ל וד\"ל. אך עלי' השלישית הוא בחי' מאד הנ\"ל וזהו שיהי' בהארתו משיח כנ\"ל היינו שאמר ואיש בתוספות וא\"ו להורות על ההמשכה מבחי' איש הנק' עליון וכמ\"ש והוא יכוננה עליון והוא בחי' פנימיות אור המאצי' הנקרא עליון שיאיר במל' שנק' ציון כענין אלקים יעננו בקול בקולו של משה הנ\"ל וכמ\"ש כי הנני בא ושכנתי בתוכך כו', ושרש המשכת ואיש הזה הוא מצד עצמו באתדל\"ע שמצד עצמו וכמ\"ש כי הנני בא כו' לפי שהוא מקום גבוה מאד שאין אתדל\"ת מגיע לשם כלל עד שתקרא כנ\"י לגביו בחי' אשה כנ\"ל וכמ\"ש אם צדקת מה תתן לו כו' אלא יבא וישכון במל' הנק' דיבור ממילא ומאליו כו' והגם שעכשיו כשאיש מזריע תחלה יולדת בגלות בת דנקבה מלאה דינין כו' אבל לע\"ל דהוא יכוננה עליון גם בת ציון תקבל מעצמו' המאציל כי מעוצם רוממות מעלתו מתפשט גם בבחי' בת. וזהו שנחמו הנביא רני ושמחי גם כשתהי' בת ציון, כי לציון יאמר איש ואיש כו' מטעם שיכוננה עליון כו' וכנ\"ל וד\"ל.\n<b>ובזה</b> יובן ג\"כ שרש ענין נר<sup data-n=\"1466\">72</sup> חנוכה שמצוותה על פתח הבית מבחוץ כו' כי הנה ידוע בעיקר מצות נר חנוכה הוא על פתח החצירות דוקא משום פרסומא ניסא וכמ\"ש והדליקו<sup data-n=\"1467\">73</sup> נרות בחצרות קדשיך כו' וגם בדרז\"ל חצר שיש לה שני פתחים כו' דעיקר המצוה להדליק בפתח החצר או המבוי ורה\"ר כו' והענין הוא לפי שברה\"ר וחצר הוא בחי' החיצוני' שחוץ להיכלות הקדושה וענין נר חנוכה באור ושמן ופתילה הוא ענין יחודי' העליונים באורות וכלים ואורו' פנימי' ומקיפים וכל פרטי האורות השייכים ליחוד העליון כולם יש בהדלקת נר עם שמן ופתילה כי באור הנר יש כמה גוונין מבחי' א\"פ וא\"מ והשמן והפתילה המה הכל בחי' סיבה א' להביא בהתגלות יחוד כל האורו' יחד שהשמן ממשיך האור והפתילה למעלה בהיותה בחי' כלי להאחז בה האור כו' ועכ\"פ בנר חנוכה יש כל היחוד העליון בשלימות וע\"כ מדליקים בפתח החצר דוקא כי גם בחצר ורה\"ר שהוא מדור החיצוני' יכול היחוד",[["1462","68","<b>איש ואיש יולד בה</b>: תהלים פז, ה."],["1463","69","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["1464","70","<b>אשה מזרעת תחלה. . יולדת זכר</b>: תזריע יב, ב. נדה לד, א. וראה מאמרי אדה\"א שמות ח\"ב ע' תא."],["1465","71","<b>אור הלבנה כאור החמה</b>: ישעי' ל, כו."],["1466","72","<b>נר חנוכה שמצוותה על פתח הבית מבחוץ</b>: שבת כא, ב."],["1467","73","<b>והדליקו נרות בחצרות קדשך</b>: נוסח על הניסים."]]],[2100490311,"הזה להאיר ולאתהפכא<sup data-n=\"1468\">74</sup> חשוכא לנהורא כו' משום דיחוד זה יכוננה עליון הנ\"ל בחי' העלם העצמות דאור המאציל דקמי' כחשיכה כאורה ולילה<sup data-n=\"1469\">75</sup> כיום יאיר כו' ולכך גם בת ציון רני ושמחי כנ\"ל וד\"ל.",[["1468","74","<b>ולאתהפכא חשוכא לנהורא</b>: ראה זח\"א ד, א."],["1469","75","<b>ולילה כיום יאיר</b>: תהלים קלט, יב."]]],[2100490312,"<h3>נוסח שני: ביאור רני ושמחי בת ציון</h3><h3>להבין מאמר הזוהר סוף פרשת ויגש ויברך יעקב את פרעה</h3>\n<b>בעזה\"ש שבת פרשת ויגש</b>\n<b>להבין</b><sup data-n=\"1470\">1</sup> מאמר הזוהר סוף פרשת ויגש (דרי\"א ע\"ב): ת\"ח מה כתיב ויברך<sup data-n=\"1471\">2</sup> יעקב את פרעה כו' א\"ר יוסי פרעה אע\"ג דאוקמוה ברזא אחרא סמך דקא סמכינן בעלמא אבל ת\"ח לסוסתי<sup data-n=\"1472\">3</sup> ברכבי פרעה דמיתיך רעייתי אית רתיכין לשמאלא ברזא דסט\"א ואית רתיכין לימינא ברזא דסט' דקדושה ואלין לקבל אלין אלין דרחמי ואלין דדינא וכד עביד קוב\"ה דינא במצראי כההוא גוונא דאינון רתיכין ממש עבד ההוא סטרא קטל ואפיק נשמתין אוף קוב\"ה ויהרוג<sup data-n=\"1473\">4</sup> ה' כל בכור כו' בההוא גוונא ממש ובגין כך דמיתיך רעייתי כגוונא דילה ממש לקטלא דכתיב אני הוא אני הוא<sup data-n=\"1474\">5</sup> ולא אחר ולע\"ל כתיב מי זה בא מאדום<sup data-n=\"1475\">6</sup> כו' ת\"ח מה כתיב וישב<sup data-n=\"1476\">7</sup> ישראל ויאחזו בה ויפרו וירבו מאד ויאחזו בה אחסנת עלמין ויאחזו בה דהא להון אתחזי כמה דאוקמוה ע\"כ דברי המאמר.\n<b>והענין</b> מה שיש לדקדק במאמר זה רבות. הנה הא' מה ענין ויברך יעקב למ\"ש בפתיחת המאמר על פסוק לסוסתי ברכבי פרעה כו' דלכאורה אין ענין זה לזה כלל. הב' מה שסמך לסוף המאמר ת\"ח מאי כתיב וישב ישראל כו' ויאחזו בה כו' שממשמעות הכוונה שיש לזה שייכות וקשר למ\"ש למעלה. ולכאורה אין לזה שייכות וקשר כלל למה שהקדים למעלה ע\"פ לסוסתי כו'. והג' בעיקר גופא של המאמר דאין לו הבנה כלל ע\"ד הפשוט. דהנה אמר דבההוא גוונא ממש עבד קוב\"ה ויהרוג ה' כל בכור כו' דזה פלאי מאד איך יתכן לומר באלקים חיים שיעשה כדוגמא הקליפה להרוג בעצמו ובכבודו כו' הלא אין<sup data-n=\"1477\">8</sup> רע יורד מלמעלה דלא<sup data-n=\"1478\">*8</sup> יגורך רע",[["1470","1","<b>להבין מאמר הזוהר</b>: הנחות כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 פט, א. נמצא ג\"כ בכת\"י 68 לט, ב. בכותרת: בעזה\"י שבת פ' ויגש. נדפס ג\"כ (בשינויים) בביאוה\"ז ויגש קלד, ב.\nהנחת המהרי\"ל נדפס בביאוה\"ז להצ\"צ ח\"ב ע' תשכה [באחד הכת\"י רשום בהמפתח בגוכתי\"ק הצ\"צ: ל' דודינו הרב מהרי\"ל ז\"ל]. מאמר זה עם הגהות כ\"ק אדמו\"ר הצ\"צ נדפס בביאוה\"ז שם ע' תשכז ואילך.\nהנחת ר' משה בן אדה\"ז נדפס לקמן ע' רמ."],["1471","2","<b>ויברך יעקב</b>: ויגש מז, ז-י."],["1472","3","<b>לסוסתי ברכבי פרעה</b>: שה\"ש א, ט."],["1473","4","<b>ויהרוג ה' כל בכור</b>: בא יג, טו."],["1474","5","<b>אני הוא ולא אחר</b>: בא יב, יב הגדה של פסח פיסקא ויוציאנו."],["1475","6","<b>מי זה בא מאדום</b>: ישעי' סג, א."],["1476","7","<b>וישב ישראל</b>: ויגש מז, כז."],["1477","8","<b>אין רע יורד מלמעלה</b>: ראה ב\"ר פנ\"א, ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסו ובהנסמן לשם."],["1478","*8","<b>לא יגורך רע</b>: תהלים ה, ה."]]],[2100490313,"כתיב וע\"כ ידוע שזה הפועל הרע להרוג ולהשחית לא יתכן כ\"א לסט' דקליפה בלבד והאיך יאמר לשבח לסוסתי כו' דמיתיך רעייתי ומשמעות המאמר עפ\"י זה שהוא דורש לשבח כו'. אך הענין של כללות הכוונה במאמר הזה יובן בהקדים ענין אחר ביאור ושרש לדרוש הנאמר ע\"פ מזמור שיר חנוכת הבית בסידור<sup data-n=\"1479\">9</sup> שער החנוכה מהו שרש וענין חנוכת הבית במאה<sup data-n=\"1480\">10</sup> אלף צאן כו' ומשם יובן תוכן כוונת גופו של מאמר הזה הנדרש ע\"פ ויברך יעקב את פרעה דוקא כו'.\n<b>דהנה</b> ענין הקרבנות שהי' מקריבים בבית המקדש דבר יום ביומו שני כבשים של תמידים כמ\"ש את הכבש<sup data-n=\"1481\">11</sup> האחד תעשה בבוקר כו' כידוע ובכל שבת קרבן מוסף וכן בר\"ח קרבן מוסף אחר כו' ובמועדים ורגלים קרבנות מוספים אחרי' וכן קרבנות היחיד הכל היה בדרך כלל ענין ההעלאה מלמטה למעלה הנק' העלאת מ\"ן מה שמבררים מהיכלות דנוגה כמו העופות והכבשים והפרים והאילים דעוה\"ז השפל ששרשם מתמשך משרש הנפש החיוני' ונפש הבהמית הרוחני' שהוא בבחי' פני שור ופני נשר דנוגה דעשיה וכאשר יקריבו החלב והדם מהן ע\"ג המזבח ידוע דהמזבח הוא נעשה בדוגמא לבחי' מל' דאצי' שנק' מזבח עילאה והחלב והדם הוא עיקר פנימיות ותמצית החיות שלהם וכאשר נקטרים על גבי המזבח ה\"ז בחי' העלאה והתכללות החיות שלהן העיקרי עד שנכלל ונדבק ומתאחד במזבח העליון והוא הנק' העלאת מ\"ן מנוגה ועדיין אין הענין רק שהמזבח קבל בתוכו בחי' ההעלאה מלמטה למעלה ואחר כך הנה יורד אש שלמעלה מלמעלה למטה ע\"ג המזבח ואוכל ושורף את הקרבן כידוע וזה האש<sup data-n=\"1482\">12</sup> הוא אשר ירד בצורת אריה ע\"ג המזבח כידוע בדרז\"ל וגם בזהר אמרו דאריה<sup data-n=\"1483\">13</sup> הוא דאכיל קרבנין והוא מבחי' פני<sup data-n=\"1484\">14</sup> אריה אל הימין שבמרכבה דקדושה שהוא בחי' מי החסדים שבקו הימין הנק' בחי' מ\"ד דז\"א והוא לפי שהקרבן הנקרב ע\"ג המזבח הי' בחי' מ\"ן דנוק' דז\"א ע\"כ ממילא ירד מיד בחי' המ\"ד דז\"א והוא אש שלמעלה שירד בצורת אריה ואכיל קורבנין כו' היינו מ\"ש ביחזקאל<sup data-n=\"1485\">15</sup> והאריאל שתים עשרה אורך כו' וכן בישעיה רסי' כ\"ט הוי אריאל אריאל כו' מפני שהמזבח נקרא אריאל ע\"ש בחינת צורת האריה שבמרכבה דז\"א שירד ואכיל קורבנין כנ\"ל ולכך נק' הקרבן אשה<sup data-n=\"1486\">16</sup> ריח ניחוח להוי' פי' אשה<sup data-n=\"1487\">17</sup> הוא א\"ש ה\"א דהיינו העלאת מ\"ן מנוק' דז\"א שהוא הנק' א\"ש ה\"א ע\"ש שהוא עולה",[["1479","9","<b>בסידור שער החנוכה</b>: רעז, א. וראה לעיל ד\"ה מזמור שיר חנוכת הבית. שערי אורה ד\"ה בכ\"ה בכסלו פל\"ז. לקמן בהנחת ר' משה של מאמר זה הערה 8."],["1480","10","<b>במאה אלף צאן</b>: ראה מלכים-א ח, סג."],["1481","11","<b>את הכבש האחד תעשה בבקר</b>: תצוה כט, לט. ועוד."],["1482","12","<b>האש. . ירד בצורת אריה. . בדרז\"ל</b>: ראה יומא כא, ב."],["1483","13","<b>דאריה הוא דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ג. זח\"ב (תוספות) רעח, א. צו לב, ב. לג, רע\"א."],["1484","14","<b>פני אריה אל הימין</b>: יחזקאל א, י. ראה סידור שער האלול רלא, ד. לקו\"ת נצבים מד, רע\"ג."],["1485","15","<b>ביחזקאל והאריאל שתים עשרה אורך</b>: מג, טז."],["1486","16","<b>אשה ריח ניחוח להוי'</b>: ויקרא ט, ט. ובכ\"מ."],["1487","17","<b>אשה הוא א\"ש ה\"א</b>: ראה זהר בראשית מח, ב. ביאוה\"ז נח ז, ב."]]],[2100490314,"מלמטה למעלה בבחי' גבורות והסתלקות כמו רשפי אש שלהבת העולה מלמטה למעלה כו' וכמ\"ש ואל<sup data-n=\"1488\">18</sup> אישך תשוקתך כו' וכתיב בה נכספה<sup data-n=\"1489\">19</sup> וגם כלתה נפשי כו' בבחי' כוסף התשוקה וכלות הנפש כו' ואח\"כ נעשה מזה ריח ניחוח לה' שהוא בחי' מ\"ד דז\"א דאצי' שנק' הוי' שיורד ושוכן במזבח כו' וכנ\"ל.\n<b>ובזה</b> יובן ג\"כ ענין רני<sup data-n=\"1490\">20</sup> ושמחי כו' שהרינה הוא בחי' מ\"ן דנוק' והשמחה הוא מה דאתבסמת נוק' אח\"כ בחסדי' דמ\"ד כו' וכמ\"ש מלפני<sup data-n=\"1491\">21</sup> אדון חולי ארץ כו' וכמ\"ש במ\"א וד\"ל. אך הנה כדי שיהיה הכח למזבח להעלות מ\"ן ושירד אח\"כ בחי' המ\"ד זהו א\"א להיות מצד עצמם בלבד מפני שידוע דכל<sup data-n=\"1492\">22</sup> התחלות קשות הנה אבל לאחר שהתחיל אפילו פ\"א לא יוקשה לו עוד הדבר ההוא ויהיה לו בנקל לעשות מעצמו ועד\"מ<sup data-n=\"1493\">23</sup> התינוק בבית הספר עיקר מה שקשה לו ללמוד שם הוא לפי שענין הלימוד דבר חדוש אצלו שלא הורגל בו מעולם וכל התחלות קשות ע\"כ צריך שיוליך לתינוק אביו או אחיו הגדול שיביאנו לבית הספר והוא יחנך אותו בפעם ראשון לפתותו ללמוד וזהו אינו אלא בפעם הראשון בלבד כי אח\"כ ילך וילמוד בעצמו כידוע. והוא לפי שבפעם הראשון קשה לתינוק מפני שזהו ההתחלה וכל התחלה קשה כנ\"ל אבל מכאן ואילך לא יקשה בעיניו דבר הלימוד כלל כידוע. והנה הטעם שיחנך אותו איש גדול דוקא כמו אביו או אחיו הגדול וכיוצא הוא מובן לפי שאותו האיש צריך הוא שיחנכנו ויפתנו לדבר הלימוד וע\"כ צריך להיות איש גדול שאין אותו דבר הלימוד קשה בעיניו כלל כי כבר הורגל בה ולמד כמה פעמים ואין הדבר חדש אצלו כלל ע\"כ יהי' ביכולתו לחזק לבב התינוק ואם היה גם הוא קטן או שאינו מורגל בדבר כמו התינוק לא היה ביכולתו לחזק לבבו אך מפני שהוא גדול וכבר הורגל בה ואין הלימוד אצלו דבר גדול וענין נפלא כלל לכך יוכל לקרב לב התינוק לומר לו דברי פיתוי שאין הענין הזה נפלא ומחודש כ\"כ כו' וכיוצא ונמצא הליכות הגדול לבית הספר אינו בשביל עצמו כלל וכלל רק לחנך את התינוק ולחזק את לבבו בדבר הלימוד מפני שאצל גדול אין הלימוד ענין גדול ונפלא כלל כו'.\n<b>והנמשל</b> מכ\"ז יובן למשכיל למעלה בהיות ששרש של הקרבנות הוא ענין יחוד מ\"ן ומ\"ד דזו\"נ דאצילות כנ\"ל ולהיות כי זהו הכלל דכל התחלות קשות כנ\"ל במשל התינוק כו' ע\"כ בהכרח הוא שיבא אור ומדריגה הגבוה הרבה מגופו של ענין היחוד דזו\"נ כו' שאצלו אין ענין יחוד זה דבר גדול ונפלא כלל מפני שהוא למעלה מעלה מזה כו' והוא הנותן כח ועוז לחנך למזבח שיעלה מ\"ן ושיורד אח\"כ מ\"ד מארי' שבמרכבה כנ\"ל והנה אותו אור המחנך הוא בא מבחי' ג\"ר דע\"י להיות כי זה היחוד דמ\"ה וב\"ן דזו\"נ שמן הקרבנות הוא מבחי' בתיקון דכבר הוא בא בבחי' השתלשלות או\"כ כו' מן המאציל לנאצלים כידוע והתיקון הוא בחי' היחודי'",[["1488","18","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1489","19","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, א."],["1490","20","<b>רני ושמחי</b>: זכרי' ב, יד."],["1491","21","<b>מלפני אדון חולי ארץ</b>: תהלים קיד, ז."],["1492","22","<b>דכל התחלות קשות</b>: מכילתא יתרו יט, ה. תוד\"ה פסיעה — תענית י, ב."],["1493","23","<b>ועד\"מ התינוק בבית הספר</b>: ראה ג\"כ שערי אורה שער החנוכה. דרך מצותיך עב, ב."]]],[2100490315,"העליונים דמ\"ה וב\"ן דזו\"נ ע\"י התורה ומצות כמו בקרבנות הנעשים כך דוקא כו' ב' כבשים דתמידים וקרבן מוסף ר\"ח ושל רגל כך וכך כו' אבל בבחי' ג' ראשונות דע\"י שלמעלה מעלה לגמרי מבחי' ההשתלשות וההשפעה ממאציל כו' לפי שלא היה בהן בחי' השבירה כלל כידוע עד שיהיה צריך לבא לבחי' התיקון על ידי היחודים כו' ע\"כ האור והגילוי משם דוקא יבא לבחי' החינוך והוא הנק' חנוכת המזבח כו' ע\"ד משל הנ\"ל שיחנכו לנער ללמוד בבית הספר שיחנך אותו הגדול דוקא שאין הלימוד ענין דבר חדש כו' כי בחי' היחוד בג' ראשונות הוא במעלה ומדריגה הרבה יותר עליונה ממש ותמידי כו' כידוע. ואין ליחוד זה דזו\"נ ערך לו כלל כי עליית מ\"ן וירידת מ\"ד דיחוד זה שוה בהשוואה לפניו בערך א' ממש כו' כי מאחר שנאמר בג\"ר דע\"י המתנשא מימות עולם ופי' המתנשא מימות עולם ידוע שהוא מובדל ומרומם בערך מבחי' ימות עולם שהן בחי' ז\"ת דע\"י שמלובשים באצי' וע\"כ נק' בשם עתיק יומין שנעתק ומובדל מיומין הללו כו' וכמ\"ש במ\"א, א\"כ הרי כל מה שיש בסדר ההשתלשלו' דאצי' בי\"ע הכל בהשואה א' לפניו ממש עד שבחי' רוחניות וגשמיות שוין לפניו וכמ\"ש כחשיכה<sup data-n=\"1494\">24</sup> כאורה כו' כי שוה<sup data-n=\"1495\">25</sup> ומשוה קטן וגדול וכמ\"ש קטן<sup data-n=\"1496\">26</sup> וגדול שם כו', והוא לפי שמובדל מבחי' ההתלבשות בהשתלשלות הרי אין לפניו בחי' מעלה ומטה כלל, וזהו מ\"ש המשפילי<sup data-n=\"1497\">27</sup> לראות בשמים ובארץ ששמים וארץ שניהם שוין בחי' השפלות והירידה במה שישפיל ויראה בהן כו', משא\"כ בבחי' ז\"ת כו' וד\"ל. וע\"כ משם דוקא יהי' החינוך לנער כו' ועד\"מ הנ\"ל וד\"ל.\n(ב) <b>והנה</b> בהקדמה הזאת יובן תוכן כללות ענין המאמר הנ\"ל הנדרש ע\"פ ויברך יעקב את פרעה דוקא כו', אך הנה תחלה יש להקדים לבאר ענין גופו של המאמר הנ\"ל, דהנה באמת גופו של מאמר זה נפלא מאד בהשגה במ\"ש מה סט\"א קטיל ואפיק נשמתין אוף קוב\"ה ויהרוג הוי' כו' איך הי' נמשך משם הוי' שהוא מקור כל החיים כו' שיהא קטיל ואפיק נשמתין כמו סט\"א ח\"ו וכנ\"ל.\n<b>אך</b> הענין יובן בהקדים מדרש<sup data-n=\"1498\">28</sup> חז\"ל ע\"פ וזרעתיה לי בארץ כו' דלא גלו ישראל לבין אוה\"ע אלא כדי שיתוספו עליהם גרים כו', וענין זאת ההוספה הוא בריבוי היותר מופלג כמאמרם ז\"ל כלום אדם זורע קב אלא בשביל להוציא כמה כורין כו', וזה המאמר פלאי מאד דלפי\"ז הי' בהכרח שיצאו גרים בישראל בכפלי כפליי' לאין שיעור מישראל עצמם ואין אנו מוצאים גם שיהיו הגרים חלק אחד מריבוי מישראל בכל דור כו', אך הענין הוא כמ\"ש בס' חסד לאברהם (והוא מועתק מס' הגלגולים להאריז\"ל) שכאשר גורש האדם מג\"ע אחר החטא נפלו הרבה נשמות וניצוצות דקדושה לע' שרים דנוגה מפני סיבת השבירה כידוע, והנה ידוע בסדר",[["1494","24","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["1495","25","<b>שוה ומשוה קטן וגדול</b>: ע\"פ פיוט (לימים נוראים) האוחז ביד מדת משפט."],["1496","26","<b>קטן וגדול שם</b>: איוב ג, יח."],["1497","27","<b>המשפילי לראות בשמים ובארץ</b>: תהלים קיג, ו."],["1498","28","<b>מדרש חז\"ל ע\"פ וזרעתיה לי בארץ כו' דלא גלו</b>: הושע ב, כה. פסחים פז, ב."]]],[2100490316,"ההשתלשלות דבג\"ע הוא הארת מל' דאצי' וכתיב ומשם<sup data-n=\"1499\">29</sup> יפרד והיו לד' ראשים כו' שהן ד' נהרות הידועות בכתוב שם הא' פישון וכו' ובחי' הד' נהרות הם מיוסדים בשרשם ברוחניות עד רום המעלות דבכל עולם לפי ערכו ומעלתו כך ענין הד' נהרות שלו שנמשכים ונובעים ממקור הראשון בבחי' פירוד והתחלקות וכמ\"ש ומשם יפרד כו', עד הנהר הגשמי למטה שיוצא והולך ונובע ממקורו בבחי' פירוד והתחלקות ההמשכה בפ\"ע וד\"ל, וכך הוא עד רום המעלות ובהיות כן הרי כאשר נפלו ע\"י השבירה הרבה ניצוצי אורות עליונים דקדושה למטה בעולמות הנפרדים בי\"ע בהכרח שהי' דרך הילוכם ממל' דאצי' לד' נהרות הללו כי הרי ירד מלמעלה למטה ותחלה ירדו בבחי' מל' דאצי' המוסתרת בבי\"ע ואח\"כ משם נתפרדו ויצאו ונתלבשו בד' נהרות וכמ\"ש ומשם יפרד כו'.\n<b>והנה</b> ידוע מארז\"ל דגלו<sup data-n=\"1500\">30</sup> לאדום שכינה עמהם, והענין הוא דזהו ענין גלות השכינה בע' שרים כדי להוציא מהן אותן הנשמות והניצוצות שנפלו בהן בחטא אדה\"ר ונמשך בהן דרך ההתלבשות בד' נהרות הידועים, דהנה כל נהר כולל הרבה המשכות מניצוצות ונשמות לאין שיעור ומספר ובתחלה היו כולם כלולים ונעלמים במל' דאצי' הנק' שכינה כידוע אלא שאח\"כ ירדו בהתחלקות דרך ד' נהרות והיו לד' מחנות בד' נהרות הנ\"ל, ואין שיעור לריבוי אורות וניצוצות דקדושה שיש בכל חלק מד' חלקי נהרות הנ\"ל עד שגם בכל שר ושר מע' השרים המקבלים מד' נהרות הנ\"ל יש ריבוא רבבות ניצוצות לאין שיעור כו', והנה לזה הטעם הי' כל עיקר הכונה בענין ד' גליות<sup data-n=\"1501\">31</sup> שהן מצרים ובבל יון ואדום, שהן נגד הד' נהרות הכוללים כל הניצוצות שנפלו בשבירה כו' ובכל גליות ישראל מד' גליות הללו הרי הייתה שכינה עמהם בגלות כמארז\"ל גלו לאדום שכינה עמהם כו', ובהיותה שם בגלות בזה הגלות מתבררי' כל הניצוצות שנפלו שמה וכמ\"ש<sup data-n=\"1502\">32</sup> במ\"א בענין עת אשר שלט האדם באדם לרע לו כו' שבגלות הזה דשכינה שהוא בחי' שם ב\"ן המברר כידוע תחת אותו שר כמו שר של אדום אעפ\"י שהוא שולט ומושל על ישראל אבל הוא לרע לו שנברר ממנו עי\"ז חלקי הטוב והקדושה שנפלו בו מזמן השבירה וכמ\"ש בשר של מצרים וינצלו<sup data-n=\"1503\">33</sup> את מצרים וארז\"ל<sup data-n=\"1504\">34</sup> שעשאוהו כמצולה כו' ובהיות כן גם בכל גלות כאשר ישראל שוכנים תחת אותו השר בגלות ומולידים ופרים ורבים כל הנשמות שיולידו הן הן הנשמות שמלובשים ומשוקעים באותו השר שמקבל מאותו הנהר מד' נהרות המיוחד לחלקו שהיו בנהר מזמן השבירה בחטא אדה\"ר כנ\"ל.",[["1499","29","<b>ומשם יפרד והיו לד' ראשים</b>: בראית ב, י."],["1500","30","<b>דגלו לאדום שכינה עמהם</b>: ספרי מסעי לה, לד."],["1501","31","<b>ד' גליות. . הד' נהרות הכוללים</b>: ראה ב\"ר פט\"ז ד. ילקוט שמעוני בראשית ב, יד."],["1502","32","<b>וכמ\"ש במ\"א בענין עת אשר שלט האדם באדם</b>: קהלת ח, ט. ראה לקו\"ת להאריז\"ל לך יב, טו. מאמרי אדה\"ז פרשיות התורה ח\"ב ע' עתר ובהנסמן לשם."],["1503","33","<b>וינצלו את מצרים</b>: בא, יב, לו."],["1504","34","<b>וארז\"ל שעשאוהו כמצולה</b>: ברכות ט, ב. וראה כנפי יונה ח\"ג סנ\"ח הובא במגלה עמוקות אופן נח. ובכ\"מ."]]],[2100490317,"<b>וזהו</b> שארז\"ל ע\"פ וזרעתי' לי בארץ כו' לא גלו ישראל אלא שיתוספו עליהם גרים פי' הניצוצות דקדושה שמולידים שם בהיותם בגלות מד' גליות הנ\"ל הן הנק' גרים לפי שבאו ממקום זר ורחוק להתקרב לקדושה האלקי' במל' דאצי' הנק' שכינה שהיא עם ישראל בגלות שהרי היו משוקעים בעמקי קליפות אותו השר ובהוליד נפש מישראל נמשך מניצוץ זה שמלובש בשר ההוא בגוף יהודי לעבודת ה' בתורה בתפלה ע' שנה וא\"כ ה\"ז כמו ע\"ד הגר הפשוט הבא להתגייר ולחסות תחת צל כנפי השכינה כו' וד\"ל, ולהיות כי אין שיעור ומספר כלל לריבוי נצוצות שבכל שר ושר כנ\"ל ע\"כ יוכל להיות שיהיו נשמות ונפשות הנולדות בזמן הגלות שישראל באוה\"ע בגלות בריבוי גדול מאד עד שיהי' ריבוי רבבות פעמים מנפשות ישראל בעצמם וכמו בגלות מצרים שהי' תחילת כניסתם לשם בע' נפש בלבד ונולדו שמה כמה פעמים ס' ריבוא כידוע שמה שיצאו ס' ריבוא לא הי' רק חלק החמישים כו' וכיוצא בזה בכל ד' גליות יוון ואדום עד ימות המשיח, שכל הנולדים הן מניצוצות שבד' נהרות שמלובשים בשרים דעשי' כנ\"ל וד\"ל.\n<b>וזהו</b> שארז\"ל ע\"ד משל הזריעה דוקא כמ\"ש וזרעתי לי בארץ כו' וכמ\"ש כלום אדם זורע קב אלא להוציא כמה כורין כו' דלפי הנ\"ל יוכל להית הריבוי ע\"ד זריעת קב שיוצא כמה כורין כו' וד\"ל. ולזה הטעם כל עניני הגלות בפרט מה שיגלו ישראל לאיזה שר מן הע' שרים בשביל הנשמות שיש שם שיוציאם משם בהולד להם בנים שם אין הנשמות הללו של אותו השר אלא של ישראל הם מתחלת הבריאה שהרי כשנפלו תחלה נפלו בבחי' מל' דאצי' הנק' שכינה, שהיא הנק' כנ\"י לעילא כידוע אלא שאח\"כ ירדו להפרד בד' נהרות וא\"כ שלהם הם לוקחין כו' וד\"ל.\n<b>ובכ\"ז</b> יובן הפסוק אל<sup data-n=\"1505\">35</sup> תירא מרדה מצרימה כי לגוי גדול אשימך שם מהו שם דוקא אשימך לגוי גדול וכי לא הי' ביכולת ה' לעשות לגוי גדול בארץ כנען באשר הוא שם כו', אלא הענין הוא כנ\"ל לפי שכל ניצוצות דקדושה שנפלו ע\"י חטא אדה\"ר נשקעו בשר של מצרים ע\"י שנתלבשו בא' מד' נהרות והוא נהר נילוס כידוע והי' כל המחנה הקדושה הזאת שנשקעו בשר של מצרים תחלה בחלקו של יעקב כי שלו הם אך שנפלו בסיבת השבירה וכנ\"ל ע\"כ אמר לו אל תירא מרדה מצרימה בעמקי היכל הקליפות של שר דמצרים הגם שהי' אז בתכלית עמקות שערי הטומאה כידוע, כי מ\"מ אשימך לגוי גדול שם דוקא כי בהכרח הוא ששם דוקא אשימך לגוי גדול עצום ורב והוא בהקבץ אליך כל המחנה הקדושה הנ\"ל כשיולידו בנים ובנות שם, ולהיות כי מושקעים המה שמה ע\"כ בהכרח דוקא שתרד בע' נפש שלך ושם דוקא אשימך לגוי גדול ה' פעמים ס\"ר כנ\"ל, ולא בארץ כנען כי אין שם מקומם כי בירידות כל הניצוצות דרך ד' נהרות ירדו תחלה בנהר נילוס חלקו של מצרים דוקא מטעם הידוע לי\"ח וד\"ל.",[["1505","35","<b>אל תירא מרדה מצרימה</b>: ויגש מו, ד."]]],[2100490318,"<b>ועכ\"ז</b> יובן ג\"כ ענין סמיכת סוף המאמר הזה במ\"ש ת\"ח וישב ישראל כו' ויאחזו בה כו' ויפרו וירבו כו', דלכאורה מה שייכות וקשר לזה המאמר עם המאמר שקדם אך עם כל הנ\"ל יתורץ היטב. דהנה בכל הנ\"ל יובן הטיב גופו של מאמר הנ\"ל באמרו מה ההוא סט\"א קטיל ואפיק נשמתין אוף קוב\"ה ויהרוג הוי' כל בכור כו', דהנה עוד הקדמה אחת צריך להקדים, והוא ביאור למ\"ש דההוא סט\"א קטיל ואפיק נשמתין כו' להיות שי\"ל שרש ענין גודל השנאה שיש לסט\"א דקליפה להיות עולה ומקטרג תמיד על האדם כידוע וכל מגמתו רק להחטיא את האדם תמיד ואחר שמפתהו לחטוא אחר כל ההשתדלות והיגיעה שמייגע עד שימצא את האדם להביאו לידי חטא אז אח\"כ עולה למעלה ומקטרג פלוני עשה כך וכך ותובע דין ומשפט עליו עד שפועל הדין והעונש למיתה או כיוצא ואז פעל וגמר כל כוונתו בתחלה להסיתו לחטוא כו' שממעשה זה נראה לכאורה שהוא רק מפני עוצם השנאה הכבושה שיש בלב הסט\"א עם נפש האדם עד שיעשה ויפעול בתחבולות רבות איך להמיתו כנ\"ל, וזה אינו מובן כלל מהיכן צמחה בלבו השנאה הגדולה הזאת, ואם מפני מ\"ש ואיבה<sup data-n=\"1506\">36</sup> אשית כו' זהו בין הנחש עם האשה דוקא אבל לנפש האדם לא מצינו שישנאנו כ\"כ שנאה בלא טעם כלל ולמה הוא מסבב בתחבולות כ\"כ עד שהוא יורד ומסטין עולה ומקטרג תמיד על האדם כידוע.\n<b>אך</b> הענין הוא משום דבאמת הנה שרש יניקות החיצונים למעלה הוא רק מבחי' אור הקדושה דוקא ואם לאו לא הי' להם מציאות שפע וקיום כלל והמופת לזה ממה שאנו רואים שלע\"ל דכתיב בלע<sup data-n=\"1507\">37</sup> המות לנצח כו' ואת<sup data-n=\"1508\">38</sup> רוח הטומאה אעביר כו' דהיינו משום דאזי מתברר מן החיצונים כל חלקי הטוב והקדושה שיקבלו יניקה משם וכמ\"ש חיל<sup data-n=\"1509\">39</sup> בלע ויקיאנו וכמו ענין והוצאתי<sup data-n=\"1510\">40</sup> את בלעו מפיו כו' וכמ\"ש<sup data-n=\"1511\">41</sup> במ\"א ביאור דבר זה באריכות שהוא ענין אשר מבואר למעלה במ\"ש עת אשר שלט האדם באדם לרע לו כו' א\"כ מוכרח מזה שאין להם חיות מצד עצמם רק ממה שמקבלים מהקדושה וע\"כ בהוציא מהם חלק הקדושה ימותו ויאבדו ממילא וכמ\"ש כי הנה<sup data-n=\"1512\">42</sup> אויבי' ה' יאבדו ויתפרדו כו', ולהיות כן לזה הטעם כל עיקר תשוקת הסט\"א דקליפה לחטוא את הנה\"א שבאדם דוקא כי ע\"י החטא הזה יחטפו הנפש האלקי' בצאתה מחומר הגופני ע\"י פסק דין ועונש העליון כי אחר הקטרוג שקטרג עליו השטן למעלה כנ\"ל (שעולה ומסטין) אזי הוא עצמו עולה למעלה ומקטרג לדין אותה בעונש גמורה במיתה ובצאתה מגופה ע\"י שנטמא בחטאה יש להחיצונים אחיזה ויניקה גמורה באותו ניצוץ האלקי' ומוליכים אותו להיכלות שלהם, וה\"ז ממש כמו עד\"מ הגנב שילך בתחבולות למצוא לו מקום מוצנע לגנוב משם דבר מה מכסף וזהב או מאכלים ובגדים וזהו חיותו וקיומו ובלעדי הגניבה אין לו חיות ושפע למלא נפשו",[["1506","36","<b>ואיבה אשית</b>: בראשית ג, טו."],["1507","37","<b>בלע המות לנצח</b>: ישעי' כה, ח."],["1508","38","<b>ואת רוח הטומאה</b>: זכרי' יג, ב."],["1509","39","<b>חיל בלע ויקיאנו</b>: איוב כ, טו."],["1510","40","<b>והוצאתי את בלעו מפיו</b>: ירמי' נא, מד."],["1511","41","<b>וכמ\"ש במ\"א ביאור דבר זה באריכות</b>: ראה תו\"ח בראשית לב, א. תולדות קנז, ב. שערי אורה ד, א. שערי תשובה מח, ג. ובכ\"מ."],["1512","42","<b>כי הנה אויבי' ה' יאבדו ויתפרדו</b>: תהלים צב, י."]]],[2100490319,"בלחם ומזון וז\"ש לא<sup data-n=\"1513\">43</sup> יבוזו לגנב למלאות נפשו כי ירעב כו' לפי שירעב ואין לו כלום כי מבלתי המצא לו למזון נפשו כלום כ\"א מן הגניבה הזאת ע\"כ לא יבוזו לו ולא יכלם לעולם מזה כמו המתפרנס מאיזה פרנסה הגם שהיא בזוי' לא תבוז בעיני מי שצריך להתפרנס ממנה וכך הגניבה פרנסת הגנב היא ע\"כ לא יבוזו לגנב כו'.\n<b>והנמשל</b> מזה ממש יובן ביניקת החיצוני' שנק' גנבים כמ\"ש אם<sup data-n=\"1514\">44</sup> גנבים באו לך שודדי לילה כו' להיות כי תרעין דג\"ע אסתימו בלילה כמ\"ש בזהר ואעפ\"י שנאמר במל' דאצי' ותקם בעוד לילה ותתן טרף כו' אין לחיצוני' יניקה רק בדרך גניבה וחטיפה בהיות שמדה שלהם קצובה בצמצום גדול ממל' דאצי' רק מבחי' אחוריי' ותמצית דתמצית כו' כמ\"ש קץ<sup data-n=\"1515\">45</sup> שם לחושך כו' וע\"כ נקראו החיצוני' שודדי לילה שבאים וחוטפים וגונבים במקום והיכל מהיכלות דקדושה אשר אינם משתמר כ\"כ עד\"מ וכמו ע\"ד הנ\"ל כאשר האדם חוטא ששכינה מסתלקת הימנו אזי אין שומר לנפשו להנצל מהחיצונים ויבואו ויקטרגו לעונשו למיתה והניצוץ האלקי ששרשו בקדושה העליונה חוטפים להם והוא להם לחיות גמור ושפע רבה מאד וכמו עד\"מ הפרנסה לגנב מן הגניבה עד שלא יבוזו לו כו' ולכך כל עיקר תשוקת הסט\"א להחטיא את האדם מטעם מציאת פרנסתם ושפע חיותם ולכך יצרו של אדם מתגבר עליו בכל יום כו', וכל מי שיש בנשמתו יותר הארת הקדושה לשם תשוקתם נפלאה יותר להחטיאו בכדי שימצאו להם שפע רבה והארה גדולה מהקדושה יותר וכנ\"ל מפני שאין להם חיות מצד עצמם כלום כ\"א מסט' דקדושה בלבד וע\"כ כל<sup data-n=\"1516\">46</sup> הגדול מחבירו יצרו גדול בו עד\"מ שלא<sup data-n=\"1517\">47</sup> ילכו הגנבים לגנוב כ\"א במקום שיש מטמון טוב ולא ימסרו נפשם לריק לגנוב דברים קטנים המונחים בחורבה וכיוצא וד\"ל.\n<b>ובכ\"ז</b> מובן פי' המאמר הזה מה ההוא סט\"א קטיל ואפיק נשמתין כו' שאין הטעם מפני השנאה שיש לו אלא מפני שהמיתה והקטלה להוציא נשמות קדושות מגופים ע\"י הקטרוג שלהם כנ\"ל זהו עיקר מעמד פרנסת שפע חיותם וקיומם כנ\"ל, וזהו שא' לסוסתי ברכבי פרעה כו' אית רתיכין לשמאלא ברזא דסט\"א כו' שהן י' כתרין דנוגה בכלל ובפרט הן רבבות עולמות ולפי שהחיצוני' מקבלים מקו השמאל דדין וגבורות עליונים לכך נאמר אית רתיכין לשמאלא כו' וההוא סט\"א נטיל ואפיק נשמתין בשביל חיותם ממש כנ\"ל וכד עביד קוב\"ה במצראי בההוא גוונא דאינון רתיכין ממש עביד מה ההוא סט\"א קטיל כו' אוף קוב\"ה ויהרוג ה' כל בכור כו', פי' משום דבגלות מצרים הרי היו ישראל פרין ורבין ומולידים עד ה' פעמים ס' ריבוא ניצוצות כנ\"ל והיו כולם מושקעים תחלה בשר של מצרים ע\"י ההתלבשות בנהר נילוס וא\"כ הרי ענין זה מה שהניצוצות יצאו מהיכלות הקליפות דמצרים להיכלות",[["1513","43","<b>לא יבוזו לגנב למלאות נפשו כי ירעב</b>: משלי ו, ל."],["1514","44","<b>אם גנבים באו לך</b>: עובדי' א, ה."],["1515","45","<b>קץ שם לחושך</b>: איוב כח, ג."],["1516","46","<b>כל הגדול מחבירו יצרו גדול</b>: סוכה נב, סע\"א."],["1517","47","<b>שלא ילכו הגנבים לגנוב כ\"א במקום שיש מטמון טוב</b>: ראה ג\"כ מאמרי אדה\"ז על מארז\"ל ע' פה. שערי תשובה נ, ג. סה\"מ תרכ\"ז ע' לט. תרל\"ב ח\"א ע' קנז. ובכ\"מ."]]],[2100490320,"הקדושה בהולד לישראל בנים ובנות שם ממש הוא כדוגמת ההריגה והקטלה שסט\"א עושין לניצוץ האלקי להוציאו מן הקדושה לקליפה שהרי הוציאו מהיכלות הקליפות כ\"כ ריבוי ניצוצות בעל כרחם וכמ\"ש וינצלו את מצרים כו' ויציאה זו דניצוצות הקדושה מהם הוא ממש כמו שחוטפים מהם את נפשם כו' אחר שנשקעו בהם להיות להם למזון וטרף להחיותם תמיד כו' וא\"כ בדוגמא שלהם שהם עושים עשו להם להוציא מהם חיות נפשם שהוא בדרך הריגה וקטלא ממש מטעם הנ\"ל מפני שאין להם חיות רק הקדושה כו' וזהו שאמר מה ההוא סט\"א קטיל ואפיק נשמתין לצורך חיותם כך קוב\"ה ויהרוג כל בכור כו', ומה שא' לדוגמא דוקא ממכת בכורות זהו לפי שנאמר בה ויהרוג הוי' דשם הוי' ממש הרג כו' לפי שנתלבשה השכינה תחלה בשר של מצרים ונשקעה עם כמה פעמים ס\"ר ניצוצות כו' וכאשר אח\"כ עולה משם בבחי' הבירור וכמ\"ש אשר<sup data-n=\"1518\">48</sup> שלט האדם באדם לרע לו דהיינו שמתהפך הדבר אח\"כ מן הקצה לקצה עד שהחושך יהפך לאור והרע נהפך לטוב כו' והוא ע\"י שיוציאו מהם כל חלקי הטוב ואז גם מה שנשאר בהם מחלקם וגורלם העצמי עפ\"י המדה המצומצמת שנמדד להם גם אותו לקחו מהם וישארו בלי חיות כלל וזהו ענין מכת בכורות של מצרים שהרג הוי' גם ממה שהי' מחלקם העצמי והוא בחי' חכ' דקליפה שנתברר גם מחכ' דקליפה לחכ' דקדושה להיות מזה יתרון לאור החכ' דקדושה וכמ\"ש כיתרון החכ' מן הסכלות כו' וזהו קדש לי כל בכור כו' וזהו ויהרוג הוי' כו' ששם הוי' בעצמו הרג ע\"י שכ\"כ נתגבר אור הקדושה כבר ממה שקדמו להנצל את מצרים בכמה פעמים ס\"ר ניצוצות כו' ולכך הי' דוקא ענין מכת בכורות לסימן והוראה גמורה על תכלית התגברות הניצחון דמה ששלט באדם לרע לו הי' אחר ששם הוי' בעצמו הרג כו' שזהו ע\"ד הדוגמא בהיפך כגוונא דסט\"א קטיל כו' שזהו להוסיף להם אור וחיות מן הקדושה וגם בההוא גוונא ממש עבד קוב\"ה במצראי מפני שניתוסף האור בקדושה ע\"י שנתהפך גם החושך לאור כו', וזהו שבכאן לא תפס לעיקר הענין בכוונת המאמר רק מ\"ש ויהרוג ה' כל בכור כו' וזהו לסוסתי ברכבי פרעה דמיתיך רעייתי, דמיתיך ממש כנ\"ל.\n<b>ועכ\"ז</b> יובן ענין הטעם למה שצריך<sup data-n=\"1519\">49</sup> לקדש א\"ע בשעת תשמיש כו' כי כדי להוציא הנפש האלקי' מסט\"א שבאותו השר צריך להוציא בטהרה וקדושה, כדי שלא ישאר ביציאה זו שום שמץ יניקה לחיצוני' אחרי יציאתה משם ואם לא תצא בטהרה ישאר עדיין להם ממנה איזה שייכות וקשר אחיזה גם בהיותה בגופה כו' וד\"ל. ואחר שנתבאר גופו של מאמר מובן ממילא ענין הסמיכות שסמך ענין לו ת\"ח וישב ישראל כו' ויפרו וירבו מאד דמשום דבההוא גוונא דסט\"א עביד קוב\"ה בחשק נפלא להוציא ניצוצות הרבה מסט\"א ע\"כ ממילא הי' ענין זה דוישב ישראל כו' ויפרו וירבו עד שהי' עד ערך ה' פעמים ס\"ר כו'. וזהו שמסיים במאמר דהא להון אתחזי כמו דאוקמוהו דנשמו' וניצוצות הללו שלהם הם דבחלקו של יעקב היו וכשגלו לשם והולידו אותם שלהם לקחו כנ\"ל וד\"ל.",[["1518","48","<b>אשר שלט האדם באדם</b>: קהלת ח, ט."],["1519","49","<b>שצריך לקדש א\"ע</b>: ספרי פ' ראה יד, כא. יבמות כ, א. תניא פכ\"ז וספ\"ל."]]],[2100490321,"<b>ועתה</b> י\"ל ענין סמיכת המאמר ע\"פ ויברך יעקב את פרעה דוקא דלכאורה אין להם שייכות וקשר כלל זע\"ז כו', אך הענין יובן בהקדים תחלה ענין הברכה הזאת עצמה שבירך יעקב לפרעה מה הוא וגם למה בירך את פרעה מאחר שהי' בחי' קליפה דמצרים כידוע. ויש להקדים לזה מה שמצינו ענין ברכה כיוצא בזו במה שבירך יצחק לעשו דגם שם יפלא למה ברכו ואיך ברכו ובפרט בברכות קדושות הללו דויתן<sup data-n=\"1520\">50</sup> לך אלקים מטל השמים כו' אחר שהי' עשו בחי' קליפה והוא הי' סבור דלעשו בירך כידוע. אך הענין הוא דמתחלה הי' סבור שיוכלו הברכת הללו להגיע לעשו מבלתי אמצעות יעקב והי' היכולת בהם שיעלו לניצוצו' קדושים שנפלו בעשו ע\"י חטא דאדה\"ר כידוע אך אח\"כ כשבא יעקב במרמה ולקח הברכות הללו דמטל השמים כו' אמר יצחק לעשו בא<sup data-n=\"1521\">51</sup> אחיך במרמה כו' גם<sup data-n=\"1522\">52</sup> ברוך יהי', ואעפ\"כ בירך לעשו וא\"ל הנה משמני<sup data-n=\"1523\">53</sup> הארץ יהי' מושבך ומטל השמים מעל כו' ואת אחיך תעבוד<sup data-n=\"1524\">54</sup> כו', ביאור הענין הזה שאמר יצחק לעשו כי הנה הברכות הללו דמטל השמים ומשמני הארץ הן בחי' אורות עליונים מאד וכידוע בזהר<sup data-n=\"1525\">55</sup> בפי' מטל השמים שהוא בחי' טלא דנטיף מעתיקא כו' ובמדרש אמרו<sup data-n=\"1526\">56</sup> דרוב דגן ותירוש הוא משנה והלכות ואגדות והכל ענין א' הוא שהוא הכל ענין בחי' גילוי אור א\"ס כמו שהוא בעצמו לפני סדרי ההשתלשלו' דאבי\"ע כו' וכמ\"ש במ\"א.\n<b>והנה</b> תחלה הי' סבור יצחק להמשיך בחי' גילוי אלקות דמטל השמים כו' בעשו כדי להעלות בזה כנ\"ל, אך אח\"כ נשלמה כוונת רבקה שיקח עשו הברכות וההמשכות הללו ע\"י אמצעות יעקב דוקא, כי רבקה ידעה שא\"א שיהי' בחי' העלאות לעשו כ\"א ע\"י יעקב דוקא ובזאת הי' מחלקותה עם יצחק בכוונת הברכה לעשו כו' וכמ\"ש במ\"א, וגם יצחק חזר בעצמו אחר שנודע לו שיעקב הי' אמר בפירוש גם ברוך יהי' כלומר א\"א לך לקבל ברכה בעצמך כי הברכות הללו שייכים דוקא ליעקב וע\"כ גם ברוך יהי', אך כדי שתקבל אתה מאותן הברכות ג\"כ א\"א כ\"א ע\"י אמצעות יעקב דוקא כי גביר שמתיו לך כו' וגם זאת בתנאי דוקא והוא ואת אחיך תעבוד כו' שאם את אחיך תעבוד אז יבואו לך הברכות ג\"כ ע\"י עבודה זו ואם לאו לא יבואו לך כו'.\n<b>וביאור</b> ענין הזה דדוקא ע\"י שאחיך תעבוד יבואו גם אליך הברכות כו' ומשמעות הענין שעכ\"פ ע\"י העבודה שיעבוד יוכל לבא בו אור הברכה ושפעה ממש, וזה פלאי לכאורה דמ\"מ האיך יקבל עשו דקליפה אור שפע הקדושה האלקי' כו'. אך הענין יובן עד\"מ האדם שהוא בעל שכל וכשאוכל איזה מאכל הנה אנו רואים בחוש ששכלו מתחזק הרבה ע\"י המאכל שאכל דוקא כי הרי בתענית להיות שמונע המאכל",[["1520","50","<b>דויתן לך. . מטל השמים</b>: תולדות כז, כח."],["1521","51","<b>בא אחיך במרמה</b>: שם לה, וראה תו\"ח ס\"פ תולדות."],["1522","52","<b>גם ברוך יהי'</b>: שם לג."],["1523","53","<b>משמני הארץ יהי' מושבך</b>: שם לט."],["1524","54","<b>ואת אחיך תעבוד</b>: תולדות כז, מ."],["1525","55","<b>בזהר. . טלא דנטיף מעתיקא</b>: ראה זהר נשא קכח, ב."],["1526","56","<b>ובמדרש אמרו דרוב דגן ותירוש הוא משנה והלכות</b>: ב\"ר פס\"ו, ג."]]],[2100490322,"שכלו חלש ואינו מבין כראוי שום שכל וסברא כו' וכמאמר ר\"נ עד<sup data-n=\"1527\">57</sup> דלא אכילנא בישרא דתורא כו' וכיוצא, ולא עוד אלא שלפי אופן טוב טעם המאכל הרוחני אם הוא בדקות והזדככות יהי' חיזוק שכלו בדקות יותר שהרי מי שמורגל במאכלים דקים שכלו דק יותר כאוכלי שולחן המלך עם בני הכפרים שרחוקים בערך מזג דקות השכל כידוע וכמ\"ש במ\"א, וגם הנה ידוע דבחי' זו נק' ברורים דנוגה והמברר הוא שם מ\"ה דאדם האוכל המאכל כו' כי הרוחניות שבמאכל נעשה בחי' השגת שכל כנ\"ל ומייחד יחודים עליונים הרי שנתעלה מאד ממש מגשמיות לרוחניות העליון ביותר עד שבהיות אור האלקי שוכן בנשמת האדם בעבודה<sup data-n=\"1528\">58</sup> שבלב זו תפילה גם המאכל יקבל אותה ההארה האלקית ממש כו' רק שתקבל ע\"י אמצעות הנשמות האלוקית בהיות שהנשמה תייחד יחודים עליונים ונגלה בה כבוד ה' כ\"כ וממילא יקבל האור גם הכחות הכלולים בה והוא גם כח המאכל הגשמי שכולל בה וגרם בה התחזקות כנ\"ל אבל המאכל מצד עצמו כמו שהוא גשמי לא הי' בערך הקבלה מעולם כו' וד\"ל.\n<b>והדוגמא</b> מזה ממש יובן בדרך כלל ג\"כ והוא דלע\"ל הנה כתיב ועמדו<sup data-n=\"1529\">59</sup> זרים ורעו צאנכם כו' שהאומות יעבדו האדמה וירעו הצאן כו' הרי הם גורמים בחי' התחזקות בקדושה האלקית שבנפש הישראל בתפילתו ותורתו וכמ\"ש והחזיקו<sup data-n=\"1530\">60</sup> בכנף איש יהודי כו' כי נעשו כמו בחי' חומר וצורה, וכדוגמא זו הי' כבר בימי משה כשאמר כלב סר<sup data-n=\"1531\">61</sup> צילם מעליהם לחמינו הם כו' והוא ממש עד\"מ מן המאכל הנ\"ל. ואמנם הנה יהי' עלי' גדולה לאוה\"ע בזאת העבודה והשירות שיעשו לבנ\"י כי הרי גם בהם יהי' שוכן גילוי אור א\"ס ממש ע\"י אמצעות ישראל מאחר שיהיו כולם כלולים בהתכללות בישראל מפני עבודה זו, ועד\"מ המאכל הנ\"ל שעולה לשכל ומתכלל שם וגם מחזקו כנ\"ל, וא\"כ בהיות הגילוי המשכה והברכה על בנ\"י ממילא יתברכו גם הם בכל אותן הברכות, אך זהו דוקא לפי שהמה עובדים לישראל ונעשים כמו בחי' חומר וצורה כו' שהוא כמו המאכל עד\"מ וכמ\"ש כי לחמינו הם כו' וד\"ל.\n<b>ובכ\"ז</b> מובן ג\"כ ענין הברכה לעשו שיוכל לקבל ע\"י אמצעות יעקב דוקא והוא שאת אחיך תעבוד, ועד\"מ הנ\"ל במאכל, ואם לאו אין לעשו העלא' כלל כי הרי נשאר למטה בגסו' שלו כו' וד\"ל. ועד\"ז ג\"כ ענין הברכה שבירך יעקב את פרעה כו' דהנה יעקב רצה להמשיך בחי' גילוי אלקות בפרעה דוקא וזהו שר' יוסי הקדים לתרץ באמרו פרעה אע\"ג דאוקמוהו ברזא אוחרא סמך דקא סמכינן בעלמא, פי' דלא יקשה דהא פרעה הוא בבחי' הקדושה והוא בחי' מל' דאצי' דאתפריעו בה כל נהורי' להיותה בחי' ההתגלות וכמ\"ש זה בפ' מקץ דזהו רק סמך דסמכינן בעלמא כלומר סמך בעלמא הוא ואין מקרא יוצא מידי פשוטו דאת פרעה ממש בירך, ואל",[["1527","57","<b>עד דלא אכילנא בישרא דתורא</b>: ראה ב\"ק עב, רע\"א."],["1528","58","<b>בעבודה שבלב זו תפלה</b>: תענית ב, א."],["1529","59","<b>ועמדו זרים ורעו צאנכם</b>: ישעי' סא, ה."],["1530","60","<b>והחזיקו בכנף איש יהודי</b>: זכרי' ח, כג."],["1531","61","<b>סר צילם מעליהם</b>: שלח יד, ט."]]],[2100490323,"יקשה לך האיך יקבל פרעה דקליפה ברכות הקדושות דיעקב כו' לזה הקדים ואמר ת\"ח לסוסתי ברכבי פרעה כו' עד סוף המאמר ומבואר למעלה תוכן כוונת המאמר שהי' אור השכינה מסתתרת במצרים בלבוש שק ולשלוט בה האדם כו' בכדי להוציא מהם כל הניצוצות דקדושה אח\"כ כו' וכמ\"ש אנכי<sup data-n=\"1532\">62</sup> ארד עמך מצרימה ואנכי אעלך כו' והוא כמ\"ש למעלה בענין אשר שלט האדם באדם לרע לו כו' ואמנם הנה כדי שיהי' לשכינה כח ועוז להעלות המ\"נ מקליפת מצרים ולהוציא מהן הניצוצות ולכוללם בקדושה העליונה שהוא עד\"מ בחי' בירורי' דע\"י שאדם אוכל כו' שאם אינו אוכל לש\"ש מתגשם ונופל כו' לזה הי' צריך בתחלה המשכת ברכה והוא ענין הברכה שבירך יעקב לפרעה, והוא ע\"ד הנ\"ל בענין חנוכת הבית שצריך שיבא בהתחלה הגדול לחנך את הקטן כי כל התחלות קשות כו' וכך יעקב להיותו למעלה מעלה דהיינו בחי' הארת יסוד אבא וכמ\"ש רז\"ל יעקב<sup data-n=\"1533\">63</sup> אבינו לא מת פי' לא הי' בבחי' השבירה שנק' מיתה וכמ\"ש וימלוך<sup data-n=\"1534\">64</sup> וימת כו' כי בבחי' ג\"ר לא הי' בחי' השבירה כלל כנ\"ל וע\"כ משם דוקא באה בחי' הברכה ליתן כח ועוז להעלות מ\"נ מהיכלות קליפות נוגה תמיד, כי מי שהוא למעלה מבחי' המלחמה הזאת בידו ליתן כח ועוז לנצחון המלחמה להיות אשר שלט האדם לרע לו כו' וד\"ל.\n<b>ולזאת</b> הכונה בירך יעקב לפרעה דקליפה דוקא כדי שיוכלו כנ\"י להוציא ממנו הנשמות בגלותם שם. אך הברכה היתה מ\"מ ע\"ד פשוט לפרעה ג\"כ והוא ע\"ד הנ\"ל בברכת יצחק לעשו שבתנאי דוקא ואת אחיך תעבוד כו' וגם כאן ע\"י שיוכלל ניצוצות דקדושה שהי' בפרעה ועמו בכנ\"י ממילא יבא האור והשפע גם לפרעה ועמו עד\"מ המאכל הנ\"ל, וזהו ויברך יעקב את פרעה ממש ולא כמו סמך בעלמא כו', ולכך הקדים לזה ת\"ח לסוסתי כו' שמכוונת המאמר יובן דאת פרעה ממש בירך מטעם שיוכלו הנשמות ממנו ויוכללו בכנ\"י ובאמצעות זה יקבל גם פרעה, אך שצריך הכונה ממקום גבוה לזה לכך היתה תלוי ביעקב דוקא ברכה זו מטעם שיעקב לא מת וכנ\"ל וד\"ל. ועם זה יובן מ\"ש בסוף המאמר אני הוא ולא אחר כו' פי' בחי' ג\"ר דע\"י נק' אני הוא כו' ושם אין מקום ושרש ליניקות החיצונים הנק' אחר וכמ\"ש וכבודי<sup data-n=\"1535\">65</sup> לאחר לא אתן כי אין מקבלים רק ע\"י סיבת השבירה שהוא מבחי' ז\"ת בלבד וע\"כ אומר אני הוא [טעם דלפי שג\"ר] אין את זלעו\"ז כלל לכך משם יוכל להיות הכח הזה לנצח המלחמה להוציא הנשמות וכו' ולע\"ל ג\"כ מי זה בא מאדום כו' שהוא בחי' עצמו' דז\"א כמ\"ש ה'<sup data-n=\"1536\">66</sup> איש מלחמה ובכאן מיירי רק בנצח דנוק' דז\"א וכמ\"ש דמיתיך<sup data-n=\"1537\">67</sup> רעייתי וד\"ל.",[["1532","62","<b>אנכי ארד עמך מצרימה</b>: ויגש מו, ד."],["1533","63","<b>יעקב אבינו לא מת</b>: תענית ה, ב. ראה גם סידור שער התפלה רב, ג. שער בהמ\"ז קד, סע\"ג."],["1534","64","<b>וימלוך וימת</b>: וישלח לו, לד ואילך."],["1535","65","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח."],["1536","66","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["1537","67","<b>דמיתיך רעייתי</b>: שה\"ש א, ט."]]],[2100490324,"<h3>נוסח שני: בזהר פ' ויגש ויברך יעקב את פרעה</h3>\n<b></b><b>בעזה\"י שבת קודש פ' ויגש, באור מאמר הזהר הזה</b>\n<b>בזהר</b><sup data-n=\"1538\">1</sup> פ' ויגש דף רי\"א ע\"ב, ויברך<sup data-n=\"1539\">2</sup> יעקב את פרעה אר\"י פרעה אע\"ג דאוקמוה ברזא אוחרא סמך הוא דקסמכינן בעלמא אבל ת\"ח לסוסתי<sup data-n=\"1540\">3</sup> ברכבי פרעה דמיתיך רעיתי, ת\"ח אית רתיכין לשמאלא ברזא דסט\"א ואית רתיכין לימינא ברזא דלעילא דקדושה כו', וכד קב\"ה עביד דינא במצרים כל דינא דעביד כגוונא דאינון רתיכין ממש וכגוונא דילי' דההוא סטרא ממש מה ההוא סט' קטיל ואפיק נשמתין אוף קב\"ה עביד בההוא גוונא ממש, דכתיב ויהרוג<sup data-n=\"1541\">4</sup> הוי' כל בכור וגו' דכתיב אני<sup data-n=\"1542\">5</sup> הוי' אני הוא ולא אחר ולזמנא דאתי כתיב מי<sup data-n=\"1543\">6</sup> זה בא מאדום חמוץ בגדים וגו' ת\"ח מה כתיב וישב ישראל<sup data-n=\"1544\">7</sup> וגו' ויפרו וירבו מאד וגו' ויאחזו בה אחסנת עלמין כו' ע\"ש.\n<b>הנה</b> מאמר הזהר הזה הוא כולו פלאי מתחלה ועד סוף, שמתחיל בפסוק ויברך יעקב כו' ואח\"כ מפרש הפ' לסוסתי ברכבי פרעה ומסיים בפסוק וישב ישראל מה ענין זה לזה גם כל המשך המאמר צריך ביאור באמרו כד קב\"ה עביד דינא כו' בההוא גוונא ממש כדכתיב ויהרוג הוי' כל בכור וכו' שזהו הפלא ופלא שיכתוב על הוי' ויהרוג כגוונא דסא' הוא מלאך המות דקטיל ואפיק נשמתין.\n<b>ויובן</b> כ\"ז בהקדים לבאר היטב הכתוב מזמור שיר חנוכת הבית וגו', כמשנ\"ת במ\"א<sup data-n=\"1545\">8</sup> שענין חנוכת הבית הוא כענין שנאמר חנוך<sup data-n=\"1546\">9</sup> לנער ע\"פ דרכו וגו' שהחנוך של הנער כשמצטרך לחנכו<sup data-n=\"1547\">10</sup> לתורה שילך לבית הספר שכל התחלות קשות<sup data-n=\"1548\">11</sup> שצריך האב להראות לו חיבה יתירה שיוליכנו האב בעצמו לבית הספר כך ממש עד\"ז בחנוכת הבית וחנוכת<sup data-n=\"1549\">12</sup> המזבח שהקריבו הנשיאים קרבנות מלבד עולת התמיד כו', בשביל לחנך המזבח שיומשך השראת השפע עליונה עליו שכל התחלות קשות שהוא באמת ירידה גדולה לגבי' ב\"ה לכך מצטרך להמשיך תוס' אורות עליונים ע\"י הקרבנות הנשיאים בחנוכת המזבח וקרבנות של שלמה המלך ע\"ה צאן<sup data-n=\"1550\">13</sup> מאה ועשרים אלף כו', בשביל חנוכת הבית כו'.",[["1538","1","<b>בזהר פ' ויגש דף ריא ע\"ב</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 2140 קיד, א.\nהנחת כ\"ק אדמו\"ר האמצעי נדפס לעיל ע' רכח [בביאוה\"ז קלד, ב].\nהנחת המהרי\"ל נדפס בביאוה\"ז להצ\"צ ח\"ב ע' תשכה, ובע' תשכז עם הגהות מהצ\"צ."],["1539","2","<b>ויברך יעקב את פרעה</b>: ויגש מז, ז-י."],["1540","3","<b>לסוסתי ברכבי פרעה</b>: שה\"ש א, ט."],["1541","4","<b>ויהרוג הוי' כל בכור</b>: בא יג, טו."],["1542","5","<b>אני הוי' אני הוא ולא אחר</b>: בא יב, יב. הגדה של פסח פיסקא ויוציאנו."],["1543","6","<b>מי זה בא מאדום</b>: ישעי' סג, א."],["1544","7","<b>וישב ישראל</b>: ויגש מז, כז."],["1545","8","<b>במ\"א שענין חנוכת הבית</b>: ראה לעיל ד\"ה מזמור שיר חנוכת הבית ע' קפ, קפא, קעח. תו\"א וישב כט, ד. לקו\"ת נשא כט, ב. ברכה צו, ב ואילך. סידור שער החנוכה רעז, א. שערי אורה ד\"ה בכ\"ה בכסלו פל\"ז. וראה לקמן (כרך ב) ד\"ה בהעלתך את הנרות."],["1546","9","<b>חנוך לנער ע\"פ דרכו</b>: משלי כב, ו."],["1547","10","<b>לחנכו לתורה שילך לבית הספר</b>: ראה ג\"כ שערי אורה שער החנוכה, שם. דרך מצותיך עב, ב."],["1548","11","<b>שכל התחלות קשות</b>: מכילתא יתרו יט, ה. תוד\"ה פסיעה — תענית י, ב."],["1549","12","<b>וחנוכת המזבח שהקריבו הנשיאים</b>: נשא ז, י ואילך."],["1550","13","<b>צאן מאה ועשרים אלף</b>: מלכים-א ח, סג."]]],[2100490325,"<b>וביאור</b> הענין דהנה ידוע סוד הקרבנות של תמידין כסדרן ומוספין כהלכתן שהיו מקריבין על המזבח במועדים ובזמנים המפורשות בתורה שהיא בחי' העלאת מ\"ן מא\"ח של המתבררין דרפ\"ח נצוצין דתוהו שנפלו דרך שבירה לנוגה דבי\"ע הם כל הבהמות הטהורים שמתבררין ונעשה מהן בחי' העלאת מ\"ן בא\"ח מלמטה למעלה בבחי' רצוא והסתלקות בגבורות רשפי אש ושלהבת עזה העולה מלמטה בצמאון גדול בבחי' השתוקקות נפלאה בבחי' רננה כו' ליכלל במקורם ב\"ה וזהו ענין הקרבת הקרבנות על המזבח שמצוה<sup data-n=\"1551\">14</sup> להביא אש מההדיוט ואח\"כ יורד עליו אש שלמעלה כדמות<sup data-n=\"1552\">15</sup> ארי' ואכיל כל קרבנין וכמ\"ש ביחזקאל והאריא\"ל<sup data-n=\"1553\">16</sup> שתים עשרה אורך וגו' שזהו בחי' הארי' שהיו יורד מלמעלה ואכיל כל קרבנין שהוא בחי' המ\"ד הנמשך מבחי' חסדים עליונים שהוא פני ארי' אל הימין שבמרכבה לשרות על המ\"ן של המתבררין והוא נמשך מבחי' ש' מ\"ה התיקון דאצי' עיקר המברר כי בחכמה<sup data-n=\"1554\">17</sup> דייקא אתברירו שהוא המברר את המ\"ן דב\"ן כנודע וזהו בחי' שמחה שאחר הרננה שהוא בחי' מ\"ד דמ\"ה שיורד כדמות ארי' שעל הימין דוקא ואכיל כל קרבנין כנ\"ל וכ\"ז הי' סוד הקרבנות שבמשכן ומקדש שהיו מקריבין תמידין כסדרן ומוספין כהלכתן ועולת החדש ומנחתה כו', שהוא בחי' הברורים דרפ\"ח ניצוצין דתוהו שנפלו בשבירה לבי\"ע שנעשה מהם תחלה בחי' העלאת מ\"ן בבחי' רננה מלמטה למעלה ואח\"כ יורד מ\"ד דמ\"ה ושורה עליהם שאז עיקר ההתבררו' שלהם ליכלל במ\"ה דתיקון דאצי'.\n<b>והנה</b> כ\"ז לאחר החנוך של המזבח או המקדש שכבר נתחנכו ושרתה השכינה בהם אז היה מתנהג בסדר נכון בהקרבת הקרבנות תמידין כסדרן ומוספין כהלכתן דבר יום ביומו בבחי' העלאת מ\"ן והמשכת מ\"ד דמ\"ה כנ\"ל, אך בתחלה כשמצטרך להמשיך הדבר מעיקרו שיושפל השפע עליונה של אור א\"ס ב\"ה לשרות על המ\"ן וא\"ח של המתבררין של הקרבנות בכדי לברר אותם ולתקן בתיקון דאצי' כי כל התחלות קשות שהוא באמת ירידה גדולה לגביו שיושפל השפע דמ\"ד דמ\"ה למטה לברר המ\"ן דב\"ן בכדי שיתברר מהניצוצין דתוהו שנפלו בשבירה לבחי' התיקון דאצי', אי לזאת מצטרך להיות בחי' חנוכת המזבח ובמקדש חנוכת הבית בהקרבנות של הנשיאים וקרבנות של שלמה בזמן החנוך שאינם שוים לשאר הקרבנות שהיו מקריבים אח\"כ תמידין כסדרן כו', והיינו בהיות ידוע שהשבירה דתהו הי' רק בז\"ת בלבד ולא בג\"ר שלא הי' בהם שבירה זולת פגם וביטול בעלמא כו', והוא מצד מעלתן הנפלאה שהם הגבה למעלה כנודע ולכך כשנצטרכו להמשיך בתחלה המ\"ד דמ\"ה שישרה על המ\"ן דב\"ן שהם הקרבנות שבמזבח ומקדש הוצרכו לחנכו בהמשכתן מג\"ר דתה\"ו שלמעלה מתהו ותיקון שלא היו מעולם בבחי' שבירה שהם הגבה למעלה מאד נעלה עד אשר כחשיכה דשבירה של ז\"ת דתהו וכאורה",[["1551","14","<b>שמצוה להביא אש מההדיוט</b>: ראה עירובין סג, א."],["1552","15","<b>כדמות ארי' ואכיל כל קרבנין</b>: ראה זהר בהקדמה ו, ב."],["1553","16","<b>והאריא\"ל שתים עשרה אורך</b>: יחזקאל מג, טז."],["1554","17","<b>בחכמה דייקא אתברירו</b>: ראה זהר פקודי רנד, סע\"ב."]]],[2100490326,"דתיקון דאצי' שוים כמ\"ש המשפילי<sup data-n=\"1555\">18</sup> לראות בשמים ובארץ בשוה השוה ומשוה קטן וגדול כנודע שאז עי\"ז ממשיכים שיתחנך המזבח והמקדש בהשראת המ\"ד דמ\"ה דתיקון לברר הבירורין דמ\"ן בתמידות לעולם והיינו כענין החנוך של הנער להוליכו לבית הספר שמצד שכל התחלות קשות והוא מצטרך להרגילו בדבר הלימוד שילך לבית הספר לזאת מוליכו אביו בעצמו הגדול מפני שאביו הוא גדול שכבר למד בבית הספר ואינו צריך ללימוד זה כלל שאינו תופס מקום נגדו כלל לכך יכול הוא להוליך הילד לבית הספר אבל הנער נער והוא התחלתו בהלימוד שאינו יכול לילך בעצמו ולקבל העול עד שיוליכנו אביו וירגילנו בזה כו', כך ממש עד\"מ למעלה בחנוכת המזבח והמקדש שיומשך השרא' המ\"ד דמ\"ה בתמידיות בו לברר המ\"ן דב\"ן בהקרבת תמידין כסדרן ומוספין כהלכתן אח\"כ שמצטרך לחנכו בזה מפני שכל התחלות קשות והיינו ע\"י המשכתן מבחי' ג\"ר דתה\"ו שלא היו בשבירה מעולם אשר שם כחשיכה כאורה שוים מצד שהגבה למעלה מאד נעלה משניהם אי לזאת משפיל\"י לראות בשמים ובארץ בשוה ולכך משם יוכלו לחנך את המ\"ד דמ\"ה שירד לשרות על המ\"ן דב\"ן מא\"ח של המתבררין דרפ\"ח ניצוצין שנפלו בשבירה מז\"ת דתה\"ו והיינו כמשל האב הגדול דוקא שכבר למד ואינו בערך הלימוד בבית הספר שמחנך את בנו הנער קטן להוליכו לבית הספר ולהרגילו בזה ואח\"כ יולך הנער מעצמו רק בתחלה בלבד צריך חנוך בה מצד שכל התחלות קשות וכו'.\n<b>וזהו</b> ענין הקרבנות של הנשיאים ושל שלמה המלך ע\"ה בחנוכת המזבח והבית שהמשיכו בקרבנות אלו מג\"ר דתה\"ו שלא היו בשבירה מעולם לצורך חנוכת המזבח וחנוכת הבית כו' ואח\"כ הי' אש כדמות ארי' שאל הימין הוא המ\"ד דמ\"ה מעצמו בכל זמן שהיו מקריבין תמידין כסדרן ומוספין כהלכתן ואכיל כל קרבנין כו', וזהו מזמור<sup data-n=\"1556\">19</sup> שיר חנוכת הבית וגו' וכמשנ\"ת במ\"א ע\"ש.\n<b>ובזה</b> יובן היטב הכתוב ויברך יעקב את פרעה, אך תחלה נבאר היטב פשט המשך מאמר הזהר הנ\"ל א\"ר יוסי פרעה אע\"ג דאוקמוה ברזא אוחרא דהיינו שנת\"ל בפ' זו בזוהר שפרעה הוא בחי' עלמא דאתגליי' דאתפריעו כל נהורין שהוא לשון פריעה והתגלות שזהו בחי' פרעה דקדושה ע\"ז מפרש שזה סמך הוא דקסמכינן בעלמא שזהו עפ\"י דרש אבל אין מקרא יוצא מדי פשוטו שהפרעה שלמטה הי' בחי' קליפה שהוא בחי' עורף ואחוריים שהם החצונים וסט\"א כו' כנודע וזהו שמביא ראי' לדבריו מפסוק לסוסתי ברכבי פרעה וגו'. ת\"ח אית רתיכין לשמאלא כו' וכד קב\"ה עביד דינא כו' בההוא גוונא דאינון רתיכין ממש כו' דכתיב ויהרוג הוי' כל בכור וגו' מה ההוא סט' קטיל ואפיק נשמתין אוף קב\"ה עביד הכי כו'.\n<b>והענין</b> הוא דהנה בסוד הגלגולים של האריז\"ל ובספר חסד לאברהם מפרש יותר בהרחבת הבאור סוד הארבע גליות בד' מלכיות בכדי לברר מהם הנשמות",[["1555","18","<b>המשפילי לראות בשמים ובארץ</b>: תהלים קיג, ו."],["1556","19","<b>מזמור שיר חנוכת הבית</b>: תהלים ל, א."]]],[2100490327,"שנפלו בהם דרך שבירה בחטא אדה\"ר והיינו כמ\"ש ונהר<sup data-n=\"1557\">20</sup> יוצא מעדן להשקות את הגן ומשם יפרד והיה לארבע ראשים שם האחד פישון וגו' ונז' ע\"ז במדרש שהד'<sup data-n=\"1558\">21</sup> נהרות הם ארבע מלכיות של הארבע גליות והיינו שכשנפלו הנשמות בחטא אדה\"ר אזי נתחלקו ונתפשטו בבחי' התחלקות פרטית בד' נהרות אלו הם ד' מלכיות השרים עליונים שחלק אחד מהם במספר הניצוצין נתפשטו במלכות מצרים<sup data-n=\"1559\">22</sup> היינו בשר של מצרים שלמעלה כו', וחלק א' מהם במספר הניצוצין נתפשטו במלכות בבל כו' כנודע ולזאת גלו ישראל בכדי לברר הניצוצין הנשמות דקדושה שנתפשטו בד' מלכיות השרים עליונים ההם, וענין הבירור שלהם הוא בהיות ישראל כשגלו לאדום שכינה עמהם גלו לבבל שכינה עמהם כו' פי' שהשכינה היא מדת מל' דאצי' מתלבשת בהשר ההוא שגלו ישראל אליו ולכך בהיותם בגולה בחלק הארץ שתחת ממשלת השר ההוא אזי כשפרים ורבים שם הילודים שם הם הנשמות דקדושה שהיו מובלעים בהשר דרך שבירה שמתבררים ממנו ויורדים לישראל שלמטה ולכך צריכים לקדש א\"ע בשעת תשמיש כמ\"ש והתקדשתם<sup data-n=\"1560\">23</sup> כו', קדש<sup data-n=\"1561\">24</sup> עצמך במותר לך בכדי לברר הטוב מן הרע להוציא ולברר הנשמות שמובלעים בקליפות בהשר ההוא לקדושה. אך הכח והיכולת הזה שיש בישראל לבררם הוא מצד התלבשות השכינה בהשר ההוא כמארז\"ל גלו לאדום שכינה עמהם כו', שהיא עיקר המברר הנשמות ממנו להשפיע לישראל שלמטה בחלק הארץ של השר ההוא (וכדכתיב עת<sup data-n=\"1562\">25</sup> אשר שלט האדם באדם לרע לו פי' לברר הטוב ממנו שאז יהי' לרע לו ממש כמשי\"ת לקמן).\n<b>וזשארז\"ל</b> לא<sup data-n=\"1563\">26</sup> גלו ישראל אלא כדי להוסיף עליהם גרים דכתיב וזרעתיה<sup data-n=\"1564\">27</sup> לי בארץ וגו' כלום אדם זורע כור אלא כדי שיעשה מאה כורין, דלכאורה הוא פלאי דלפ\"ז היה מצטרך שיתגיירו הגרים עד שיהי' מרובים מישראל להוסיף גרים מאה פעמים מישראל וזה אינו כן שהגרים הם מתי מעט. אך הענין הוא כנ\"ל שכונתם שיתוספו הגרים הם הנשמות הרוחניות של הילודים בגולה אצל בני ישראל עצמן שכל הילודים שבגולה נקראו בחי' גרים מצד התבררות נשמותיהן מהשר ההוא שהיו בבחי' נפילה ושבירה שם שעתה נתבררו להיותם יוצאין ונמשכים ממנו להתלבש בגופות הישראלים שהברור שלהם הוא ע\"י התלבשות השכינה בשר ההוא שגלו בו ישראל כנ\"ל, וזהו עיקר הטעם של סוד ארבע הגליות בכדי לברר הנשמות שנתפזרו בד' מלכיות ע\"י הפרי' ורבי' של ישראל שם דייקא בחלק הארץ של השרים ההם ששם דוקא נשפע להילודים שנולדים שם הנשמות שנבלעו בהשר ההוא משא\"כ כשהיו ישראל שרויים על אדמתם בארץ אשר הי' ד' דורש ולא תחת ממשלת",[["1557","20","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["1558","21","<b>שהד' נהרות הם ארבע מלכיות</b>: ראה ב\"ר פט\"ז, ד. ילקוט שמעוני בראשית ב, יד (רמז כב)."],["1559","22","<b>במלכות מצרים</b>: ראה לקו\"ש חט\"ז ע' 91."],["1560","23","<b>והתקדשתם</b>: שמיני יא, מד."],["1561","24","<b>קדש עצמך במותר לך</b>: ספרי פ' ראה יד, כא. יבמות כ, א. ראה תניא פכ\"ז וספ\"ל."],["1562","25","<b>עת אשר שלט האדם</b>: קהלת ח, ט."],["1563","26","<b>לא גלו ישראל אלא כדי להוסיף עליהם גרים</b>: פסחים פז, ב."],["1564","27","<b>וזרעתיה לי בארץ</b>: הושע ב, כה."]]],[2100490328,"השרים לא היה באפשר להם לברר הנשמות ההם שנבלעו בהשרים כו' וד\"ל. וז\"ש הקב\"ה ליעקב אל<sup data-n=\"1565\">28</sup> תירא מרדה מצרימה כי לגוי גדול אשימך שם כו' שם דייקא אשימך לגוי גדול דלכאורה היא פליאה דעת מה שאמר לו שלא יהי' ירא מרדה מצרימה ותולה הטעם בגוי גדול שישימנו שם, וכי לא יהי' יכול לקיים זאת בארץ כנען שישימנו שם לגוי גדול וכי מפני זה צריך לירד מצרים.\n<b>אך</b> הענין בהיות יוסף נמכר לעבד למצרים בכדי שישתלשל הדבר של הגלות מצרים (כמארז\"ל דאל\"כ היו<sup data-n=\"1566\">29</sup> מוליכים אותו בשלשלאות של ברזל כו'), ולזאת שלח יוסף אחר אביו עגלות להנהיגו לגלות מצרים בהם וכמשנ\"ת במ\"א שרמז יוסף לאביו סוד הגלות בשלוח עשר<sup data-n=\"1567\">30</sup> אתונות נושאים בר כו' ע\"ש) ולזאת היה יעקב ירא מהגלות לירד למצרים ע\"ז אמר לו הקב\"ה אל תירא מרדה מצרימה כי לגוי גדול אשימך שם דייקא שהודיעו לו טעם וסבת הגלות שהוא בכדי שיפרו וירבו בארץ מצרים שימשיכו שם הנשמות מהשר של מצרים שנפלו בו דרך שבירה שע\"י הגלות שלהם שיהי' שכינה עמהם יבררו הנשמות ההם מן השר שיתלבשו בגופות הישראלים הילודים שם דייקא משא\"כ כשיהי' בארץ כנען לא ימשיכו לעולם הנשמות ההם, מפני שהם במצרים מובלעים בהשר של מצרים ולכך לגוי גדול אשימך שם דוקא מה שא\"א להיות השמת הגוי הגדול הזה בהיותך בארץ כנען כו' כנ\"ל וד\"ל.\n<b>וזהו</b> כוונת הזוהר לסוסתי ברכבי פרעה דמיתיך רעיתי מה ההוא סט' קטיל ואפיק נשמתין אוף קב\"ה כו', פי' כי עיקר החיות של החיצונים וס\"א הוא מהקדושה דוקא היינו מבחי' הניצוצין דקדושה שנפלו לתוכם דרך שבירה שמזה הוא עיקר חיותם וקיומם כי לע\"ל כשמטו<sup data-n=\"1568\">31</sup> רגלין ברגלין שיהי' תכלית הבירורין שיבררו מהם הטוב לגמרי ויעשו אותם כמצולה<sup data-n=\"1569\">32</sup> שאין בה דגים אז לא יהי' להם עוד חיות וקיום כלל ולכך כתיב לע\"ל ואת<sup data-n=\"1570\">33</sup> רוח הטומאה אעביר מן הארץ בלע<sup data-n=\"1571\">34</sup> המות לנצח כו' שמאחר שמתברר הטוב לגמרי מהם וישארו בחי' רע גמור בנקי' בלי תערובת טוב כלל שאז אין לו קיום עוד כלל וממילא יתבער מן הארץ כנודע שעיקר החיות של הרע הוא התערובת הטוב שבו דוקא, וז\"ש עת אשר שלט האדם באדם לרע לו דוקא שיתברר הטוב מן הרע לגמרי שאז יהי' לרע לו שלא יהי' לו עוד קיום כלל כנ\"ל ולכך כל מגמתן של החיצונים להחטיא האדם בכדי להמשיך חיים עליהם מסט' דקדושה כמארז\"ל במלאך<sup data-n=\"1572\">35</sup> המות הוא יצה\"ר יורד ומסטין עולה ומקטרג ואח\"כ יורד ונוטל נשמה כו' דלכאורה אינו מובן מה תאותו בזה להסיתנו לדבר עבירה",[["1565","28","<b>אל תירא מרדה מצרימה</b>: ויגש מו, ג."],["1566","29","<b>היו מוליכים אותו בשלשלאות של ברזל</b>: שבת פט, ב."],["1567","30","<b>עשר אתונות נושאים בר</b>: ויגש מה, כג. וראה ג\"כ תו\"ח ויחי רלט, ב."],["1568","31","<b>כשמטו רגלין ברגלין</b>: ראה זח\"ב רנח, ב. ובמק\"מ שם."],["1569","32","<b>כמצולה שאין בה דגים</b>: ברכות ט, ב."],["1570","33","<b>ואת רוח הטומאה אעביר מן הארץ</b>: זכרי' יג, ב."],["1571","34","<b>בלע המות לנצח</b>: ישעי' כה, ח."],["1572","35","<b>במלאך המות הוא יצה\"ר</b>: ב\"ב טז, א."]]],[2100490329,"בכדי שאח\"כ יקטרג עליו ויבא ויטול נשמתו ומה הנאה לו בזה, אך באמת הנה כתיב לא<sup data-n=\"1573\">36</sup> יבוזו לגנב כי למלאות נפשו כי ירעב דכמו הגנב אין לו פרנסה אחרת זולתי הגניבה שבא במחתרת ולגנוב שמזה ממלא כריסו כי ירעב וזוהי פרנסתו וחיותו ממש כך החצונים עיקר פרנסתן וחיותן ממש הוא להיות קטיל ואפיק נשמתין דקדושה אליהם כמארז\"ל במה\"מ שיורד ומסית את הבריות לעבירה כו' ואח\"כ עולה ומקטרג ואח\"כ קטיל לון שעי\"ז מתפרנסים מסט' דקדושה וממשיכים תוספת חיים עליהם כי זוהי פרנסתן למלאות נפשם כי ירעבו כו'.\n<b>וזהו</b> לסוסתי ברכבי פרעה דמיתיך רעיתי מה ההוא סט' קטיל ואפיק נשמתין אוף קב\"ה עביד הכי דכתיב ויהרוג הוי' כל בכור במצרים כו' פי' שהמאציל ב\"ה אומר אל השכינה מדת מל' דאצי' לסוסתי ברכבי פרעה דמיתי\"ך רעיתי דכמו ההוא סט\"א קטיל ואפיק נשמתין בכדי להמשיך אליהם תוספת חיים ושפע דקדושה שזהו פרנסתן מהניצוצין דקדושה שנבלעים בהם כנ\"ל כך דמיתיך רעיתי שבזמן הגלות כשגלו ישראל למצרים שכינה עמהם להתלבש בהשר ההוא בכדי לברר וללקט ממנו הנשמות דקדושה שנפלו בו דרך שבירה ולהשפיע לגופות הישראלים הילודים במצרים דוקא כמ\"ש כי לגוי גדול אשימך שם דוקא כנ\"ל שעי\"ז קטיל להון שמבררים מהם הטוב שהוא עיקר החיות שלהם כנ\"ל וכיון שמתבררים מהם הנשמות והניצוצין דקדושה וישארו בחי' רע גמור בנקי' בלי תערובת טוב כלל יגרום להם קטלא וכליי' שלא יהי' להם עוד קיום כלל כמו שיהי' לע\"ל שיבולע המות לנצח מצד שיהי' תכלית הבירורים דמטו רגלין ברגלין כו' כנ\"ל וכמ\"ש עת אשר שלט האדם באדם לרע לו כו'. וזהו כונת בעל המאמר וכד קב\"ה עביד דינא במצרים כגוונא דאינון רתיכין ממש כו' מה ההוא סט' קטיל ואפיק נשמתין אוף קב\"ה עביד בההוא גוונא ממש דכתיב ויהרוג הוי' כל בכור כו' ובג\"כ דמיתיך רעיתי לקטל\"א כו' שהוא נדמה וישוה ממש לסוסתי ברכבי פרעה מה סט\"א קטיל ואפיק נשמתין כך רעיתי בזמן הגלות קטיל ואפיק נשמתין דקדושה מהם כו' כנ\"ל וד\"ל.\n<b>וזהו</b> ויברך יעקב את פרעה בהיות נת\"ל בחנוכת הבית וחנוכת המזבח שכל התחלות קשות ומאחר שהוא באמת ירידה גדולה לגבי' קוב\"ה שירד המ\"ד דמ\"ה דתיקון דאצי' לשרות על המזבח בתמידיו' על המ\"ן דב\"ן שהם הקרבנות שהיו מקריבין אח\"כ תמידין כסדרן ומוספין כהלכתן שהוא בחי' א\"ח של המתבררין כנ\"ל לכך הוצרך בתחלה דוקא לחנך המזבח והבית בקרבנות הנשיאים בחנוכת המזבח וקרבנות של שלמה בחנוכת הבית להמשיך עי\"ז ממקום גבוה מאד נעלה מהשבירה והתיקון היינו מבחי' ג\"ר דתהו אשר לא היו בשבירה מעולם דכחשיכה כאורה שוים כו' וכמשל האב שמחנך הנער שמוליכו בעצמו לבית הספר כו' כנ\"ל. כך בגלות מצרים שלא גלו ישראל אלא כדי להוסיף עליהם גרים הם הנשמות המתבררין מהשר להתלבש בהילודים במצרים, וכ\"ז הכח המברר הוא מבחי' ירידת והשפלת השכינה בסוד גלות להתלבש בהשר כנ\"ל. אך כל התחלות קשות שנמשך ותרד בחי'",[["1573","36","<b>לא יבוזו לגנב</b>: משלי ו, ל."]]],[2100490330,"השכינה בירידה גדולה להתלבש בהשר של מצרים בכדי לברר הנשמות לקיים מ\"ש כי<sup data-n=\"1574\">37</sup> לגוי גדול אשימך שם כו', לכך בתחלת ביאתו של יעקב לגלות מצרים דוקא ברך את פרעה הוא השר דקליפה של מצרים כנודע שענין הברכה הוא המשכת תוספת אור ושפע העליונה (שברוך הוא<sup data-n=\"1575\">38</sup> לשון בריכה וכענין מארז\"ל המבריך<sup data-n=\"1576\">39</sup> את הגפן כו') דהיינו שהמשיך יעקב תוספת אור ממקום גבוה מאד נעלה מהשבירה דתה\"ו והתיקון דאצי' אל פרעה השר של מצרים בכדי לחנך את בחי' השכינה ב\"ה שתרד להתלבש בו לברר ממנו הנשמות ולהשפיע להילודים אח\"כ במצרים ומצד שכל התחלות קשות לכך הוצרך לחנוך זה כנ\"ל.\n<b>ובאור</b> הענין הוא דהנה ארז\"ל יעקב<sup data-n=\"1577\">40</sup> אבינו לא מת פי' שלא הי' בבחי' מיתה ושבירה מעולם ששרשו הגבה למעלה מאד נעלה שהוא בחי' ש' מ\"ה התיקון דאצי' שהוא עיקר המברר כל הברורים ולא הי' בבחי' מיתה ושבירה מעולם לכך ויברך<sup data-n=\"1578\">41</sup> יעקב את פרעה להמשיך משרש שרשו מג\"ר דתה\"ו שלא הי' בשבירה מעולם אשר שם כחשיכה דשבירה וכאורה דתיקון שוה המשפילי לראות בשמים ובארץ בשוה לחנך את בחי' השכינה ב\"ה שתרד ותשפיל להתלבש בפרעה השר דקליפה דמצרים לברר הנשמות כו' וכענין חנוך לנער להוליכו לבית הספר להתחלת הלימוד שמוליכו אביו דוקא הגדול שכבר למד ואין תופס מקום לפניו הלימוד ההוא כנ\"ל שעי\"ז הברכה של יעקב אשר לא מת לפרעה בתוספת אור מג\"ר דתה\"ו נתחנך בחי' השכינה ב\"ה להתלבש אח\"כ ולשרות בתמידיות בו לברר הנשמות כל משך הגלות מצרים כנ\"ל.\n<b>וזהו</b> כענין הברכה של יצחק שרצה לברכו לעשו בנו שאמר הנה<sup data-n=\"1579\">42</sup> נא זקנתי לא ידעתי יום מותי (כמ\"ש במ\"א שנתעלה הגבה למעלה מבחי' השבירה ומיתה דז' מלכים דתה\"ו למקום אשר לא ידעתי יום מותי שאין מגיע לשם בחי' מיתה כלל ע\"ש). ועתה<sup data-n=\"1580\">43</sup> שא נא תליך וקשתיך כו' למען תברכך נפשי כו', שכונתו של יצחק הי' בכדי לברר את הטוב שבו מן הקליפות והרע והוא ע\"י הברכה שיברכו להמשיך לו תוספת אורות עליונים ממקום גבוה מאד נעלה משרש השבטים דהיינו כמ\"ש ויתן<sup data-n=\"1581\">44</sup> לך האלקים מטל השמים ומשמני הארץ כדרשת רז\"ל מטל<sup data-n=\"1582\">45</sup> השמים זו מקרא ומשמני הארץ זו משנה כו' שעי\"ז יתברר הטוב דעשו ויתכלל בקדושה כביטול הנר בפני האבוקה כו', אך רבקה הבינה שאין זה מערכו של עשו בעצמו לקבל השפע והברכה זו של אורות עליונים לתוכו מצד שהוא מאד במורד למטה בקליפה כו' לכך",[["1574","37","<b>כי לגוי גדול אשימך</b>: ויגש מו, ג. וראה ביאוה\"ז ויגש קלו, יב. אוה\"ת ויגש כרך ו' ע' תתשיא."],["1575","38","<b>שברוך הוא לשון בריכה</b>: ראה לקו\"ת בחוקותי מח, ב. ראה כט, א."],["1576","39","<b>המבריך את הגפן</b>: ראה כלאים רפ\"ז."],["1577","40","<b>יעקב אבינו לא מת</b>: תענית ה, ב. ראה גם סידור שער התפלה רב, ג. שער בהמ\"ז קד, סע\"ג."],["1578","41","<b>ויברך יעקב את פרעה</b>: ויגש מו, ז. וראה זהר ויגש ריא, ב. ביאוה\"ז שם קלו, א ואילך."],["1579","42","<b>הנה נא זקנתי</b>: תולדות כז, ב."],["1580","43","<b>ועתה שא נא תליך וקשתיך</b>: תולדות כז, ג."],["1581","44","<b>ויתן לך האלקים מטל השמים</b>: תולדות כז, כח."],["1582","45","<b>מטל השמים זו מקרא</b>: ב\"ר פס\"ו, ג."]]],[2100490331,"צותה ליעקב בנה שיבא במרמה ויקח ברכתו, אך אעפ\"כ יתקיים מחשבתו של יצחק שיתברר הטוב דעשו ויגיע לו הברכות ממש אך לא אליו בעצמו שלא יוכל לקבלם כלל כ\"א ע\"י יעקב יגיע אליו ג\"כ שעיקר הברכות יקח יעקב וממנו יגיע אליו, וכן הוה כשבא עשו ליצחק והבין יצחק שזה הי' יעקב אמר לו בא<sup data-n=\"1583\">46</sup> אחיך במרמה ויקח את ברכתך גם ברוך יהי'<sup data-n=\"1584\">47</sup> ואותו ברך ואת<sup data-n=\"1585\">48</sup> אחיך תעבוד כו' פי' שהסכים יצחק על הברכות שיהי' נשפעים ליעקב רק מחשבתו יתקיים עי\"ז שיהי' עשו עובד ליעקב שיגיעו מיעקב אליו ג\"כ כו', וזה יהי' לע\"ל דכתיב ועמדו<sup data-n=\"1586\">49</sup> זרים ורעו צאנכם וגו' והיו מלכים אומניך<sup data-n=\"1587\">50</sup> וגו' שעי\"ז כשיתגלו לע\"ל האורות עליונים לישראל והם יהיו עבדים לישראל יהיו נזונים הם ג\"כ מהאורות עליונים ההם כו' וכמו עד\"מ האדם העובד אדמה ומתייגע בכל כחו ושכלו בעבודה רבה זו עד שתוצא הארץ תבואתה ויעשה ממנה לחם ואח\"כ כשיאכלנו חבירו אזי יתכלל שכלו וכחו אשר שם ביגיעה רבה ההיא בשכל חבירו האוכל הלחם ומתהפך לבב הנפש ומחזק שכלו כו' כך האומות יהיו רועה צאנם ועבדיהם של ישראל ובישראל יתגלה אז כבוד ה' ית' לכך יתבררו הם ג\"כ עי\"ז להתכלל בשכלם והשגתם של ישראל שמאחר שיהי' עבדיהם ויתייגעו בכל כחם לעבודתם כו' כנ\"ל ועי\"ז תתקיים מחשבתו של יצחק אע\"ה בכונתו לברך לעשו ועי\"ז אמר לו ואת אחיך תעבוד שעי\"ז יגיעו אליך הברכות דוקא וד\"ל, וכך ממש ברך יעקב לפרעה להמשיך אליו תוס' אור מג\"ר דתה\"ו בכדי לחנך את השכינה ב\"ה שתרד להתלבש בו לברר ברורי הנשמות ממנו שעי\"ז מתברר הטוב ממנו ונכלל בקדושה ולהרע שבו יגרום קטלא וכליי' ע\"י דאפיק נשמתין ממנו כו' כנ\"ל וד\"ל.\n<b>וזהו</b> דקדוק לשון הזהר שאומר דכתיב אני הוי' אני הוא ולא אחר וסמיך ליה קמסיים במקרא וישב ישראל במצרים ויפרו וירבו גו' פי' שיעקב לא מ\"ת והמשיך בברכתו לפרעה תוס' אור מג\"ר דתה\"ו אשר לא הי' בשבירה מעולם לצורך חנוך השכינה ב\"ה מה שלא סגי בלא\"ה כנ\"ל וזהו שמפרש מ\"ש ויהרוג הוי' כל בכור דקטיל ואפיק נשמתין דקדושה לברר מהשר הוא ע\"י ההמשכה של יעקב שהמשיך בברכתו מבחי' אני הוי' ולא אחר שזהו בחי' ג\"ר דתהו שלא הי' בשבירה ולשם אין מגיעים האחרים והחיצוני' כלל לינק שעיקר יניקתם הוא מז\"ת דתה\"ו ששם הי' השבירה כנ\"ל וזהו אני הוי' ולא אחר שלשם אין מגיעים החצונים כלל ולזאת קמסיים במקרא דויפרו וירבו במאד שזהו בחי' הברורים של הנשמות ישראל הילודים במצרים שנתבררים ע\"י השכינה שנתלבשה בהשר אך החנוך שלה הי' ע\"י הברכה של יעקב לפרעה כנ\"ל וד\"ל.",[["1583","46","<b>בא אחיך במרמה</b>: תולדות כז, לה."],["1584","47","<b>גם ברוך יהיה</b>: שם כז, לג."],["1585","48","<b>ואת אחיך תעבוד</b>: שם כז, מ."],["1586","49","<b>ועמדו זרים</b>: ישעי' סא, ה."],["1587","50","<b>והיו מלכים אומניך</b>: ישעי' מט, כג."]]],[2100490332,"<h3>יהודה אתה יודוך אחיך</h3>\n<b>שבת פ' ויחי</b>\n<b>יהודה</b><sup data-n=\"1588\">1</sup> אתה<sup data-n=\"1589\">2</sup> יודוך אחיך ידך בעורף אויביך ישתחוו לך בני אביך, הנה כשילדה לאה את יהודה אמרה הפעם אודה את ה' כו' דמשמע עתה הפעם דוקא אחר שכבר ילדה לראובן ושמעון ולוי כו', והוא מפני שאמר יודוך אחיך כלומר אחיך ראובן ושמעון ולוי הוא שעשאוך להיות נק' יהודה. וביאור הדברים הנה פי' יהודה הוא לשון הודאה כמ\"ש הפעם אודה כו'. אך יש במשמעותו ב' עניני', א' ענין הווה שתמיד יודה בהודאה והוא מ\"ש<sup data-n=\"1590\">3</sup> בד\"ה תיבת יהודה בחול\"ם על הוי\"ו וסגול תחת הדלית, והב' ענין עבר שכבר הודה והוא מ\"ש בתורה יהודה הוי\"ו במלאופ\"ם ובקמ\"ץ תחת הדלי\"ת כו'. וביאור הדבר נודע מפני שיש ב' מדרגות בהשתל' והוא דרך כלל למעלה מן בחי' הזמן ובבחי' זמן, והיינו שא' יהודה לשון הווה הוא למעלה מן הזמן, דההודאה שם תמידית שלא שייך שם לומר שכבר הודה או עתיד להודות אחר שעבר ועתיד הוא בבחי' הזמן ושם הוא למעלה מבחי' הזמן, וזהו מ\"ש למען<sup data-n=\"1591\">4</sup> יזמרך כבוד ולא ידום כו' כי ההודאה שם בבחי' הוה כמו ככה<sup data-n=\"1592\">5</sup> יעשה איוב כו', וכך פי' יהודה בחול\"ם שתמיד יודה כו', אבל מה שהוא בבחי' הזמן נק' יהודה לשון עבר שכבר הודה או שעתיד להודות, וכמ\"ש הפעם אודה כו' כלומר הפעם הזה דוקא אתן תודה, שהוא מפני היותה תחת הזמן כו' וד\"ל.\n<b>אמנם</b> הנה יש להבין מה שאמרה הפעם דוקא אודה כו' שהוא מטעם שכבר ילדה לראובן ושמעון ולוי לפי שהם שעשאו וגרמו תחלה להיות נק' יהודה כמ\"ש יודוך אחיך כו' וכנ\"ל. והנה תחלה י\"ל פי' וענין ראובן ושמעון ולוי מה הם בשרשם ואח\"כ יתבאר בחי' יהודה שהוא מפני שיודוך אחיך כו', להיות ידוע בפי' ראובן<sup data-n=\"1593\">6</sup>",[["1588","1","<b>יהודה אתה יודוך אחיך</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 צב, א. נמצא ג\"כ בכת\"י 34 בתחלתו. 107 ע' קטו (ושם חסר הסיום). 655 ע' קלח. 872 ע' ו והמשכו בע' ה (ומתחיל מאמצע המאמר) בכותרת: שבת פרשת ויחי תקעזיי\"ן לפ\"ק.\nמאמר זה וביאור מיוסדים על ד\"ה זה וביאורו בתורה אור ריש פרשתנו, והגהות וכו' — באור התורה ויחי כרך ה' ע' תתקצז ואילך. ע' תתרה ואילך. כרך ו ע' 2276 ואילך [השוה כרך ה שם ע' 2994 בתוס' הגהות].\nהנחת ר' משה בן אדה\"ז נדפס לקמן ע' רעח.\nמאמר זה נדפס ג\"כ (עם כמה שינויים) במאמרי אדמו\"ר האמצעי ויחי ע' תצז, בכותרת: שבת פרשת ויחי תקעזיי\"ן לפ\"ק. וראה שם בתוס' ביאור ע' תקל."],["1589","2","<b>יהודה אתה יודוך אחיך. . הפעם אודה את ה'</b>: ויחי מט, ח. ויצא כט, לה."],["1590","3","<b>מ\"ש בד\"ה תיבת יהודה בחול\"ם</b>: בתורה אור כאן ובשערי אורה ע' 40 וע' 186 מציין לנחמי' יא, יז. — אבל כ\"ה גם בביאורי הזהר ויגש כז, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצח. שם ע' א'מו [נדפס גם במאמרי אדה\"א במדבר ח\"א ע' קטז]. תקס\"ח ח\"ב ע' תשיח. אור התורה ויחי כרך ו ע' 2276."],["1591","4","<b>למען יזמרך כבוד ולא ידום</b>: תהלים ל, יג."],["1592","5","<b>ככה יעשה איוב</b>: איוב א, ה. ראה שער היחוד והאמונה פ\"ד (עט, רע\"א). מאמרי אדה\"א דברים ח\"ג ע' תשצ."],["1593","6","<b>ראובן. . רא\"ו ב\"ן</b>: ראה בראשית רבא פע\"א, ג."]]],[2100490333,"שהוא פי' רא\"ו ב\"ן והוא בחי' ראי'<sup data-n=\"1594\">7</sup> אותיות ארי' כידוע, והיינו מפני שדגל מחנה ראובן הי' לצד דרום<sup data-n=\"1595\">8</sup><sup data-n=\"1596\">9</sup> דהיינו מסט' דחסד כידוע שהוא בחי' פני<sup data-n=\"1597\">10</sup> ארי' להימין<sup data-n=\"1598\">11</sup> שבמרכבה העליונה וארי' אותי' ראי' ע\"כ נאמר דגל<sup data-n=\"1599\">12</sup> מחנה ראובן תימנה כו', וכמבואר<sup data-n=\"1600\">13</sup> בזוהר בהיכלות דפ' פקודי דהדגלי' היו בדוגמא ממש לד' מחנות שכינה שבמרכבה העליונה הנושאות את הכסא כו' ע\"ש. אך הנה הטעם שנק' ראובן שהוא מפני בחי' ראי' כנ\"ל. ביאור הדבר יובן זה בעבודת ה' דהנה בחי' ראי' הוא בחי' ההתקרבות דע\"י הראי' והבטה אנו רואים בחוש שבזה מתקרב האדם לחבירו ומתדבק בו באהבה, דמי שהוא מובדל מבנ\"א ישנאו אותו ומי שיתראה תמיד יתקרב לאהוב אותו, כי האהבה שמושכת לב האדם אינה אלא ע\"י הראי' דוקא וכמ\"ש כביכורה<sup data-n=\"1601\">14</sup> בתאנה בראשיתה ראיתי את אבותיכם, וראי' זו ענין קירוב של אהבה הוא מלמעלמ\"ט, ועד\"ז יש קירוב אהבה ע\"י בחי' ראי' והבטה מלמטלמ\"ע, והוא ענין המבואר תמיד בזוהר לאסתכלא<sup data-n=\"1602\">15</sup> ביקרא דמלכא כו' שהסתכלות הזאת הוא בחי' ראי' מקרוב עד שעי\"ז מתקרב ומתדבק ונמשך לבו כמים כו' מלמטלמ\"ע ורוח<sup data-n=\"1603\">16</sup> אייתי רוח כו' ונמשך מאתעדל\"ת אתעדל\"ע ג\"כ בבחי' זאת להיות נמשך גילוי אור אלקי מלמעלמ\"ט בבחי' ראי' מקרוב וכמ\"ש ראיתי את אבותיכם כו'. וזהו פי' ראובן רא\"ו ב\"ן בחי' ראי' שהוא אותי' בחי' ארי' להימין כנ\"ל וע\"כ דגל מחנה ראובן תימנה לסט' דחסד שהוא בחי' האהבה והדביקות ע\"י בחי' ראי' מקרוב כנ\"ל וד\"ל.\n<b>וכ\"ז</b> הוא מב\"ש ועד ואהבת שבק\"ש, כי הנה פי' ענין ברוך שאמר והי' העולם ידוע שעיקר הענין של ברוך<sup data-n=\"1604\">17</sup> היינו לשון המשכה בבחי' הגילוי אור והוא שיהא מתגלה כח האלקי מבחי' ההעלם עד שיראו כל בשר איכות התהוות יש מאין וכמ\"ש ונגלה<sup data-n=\"1605\">18</sup> כבוד הוי' וראו כל בשר כו', משא\"כ עכשיו דאעפ\"י שהכל יודעי' שיש מחי' כל העולם מאין כו' אבל אין זה אצלם רק בבחי' ידיעה מרחוק והוא בבחי' ההעלם, וכמו ע\"ד דוגמא הנה גם גנבא<sup data-n=\"1606\">19</sup> אפום מחתרתא רחמנא קרי וידוע לו בודאי באותה",[["1594","7","<b>ראי' אותיו' ארי'</b>: ראה תקוני זהר ת\"ע קכב, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ל."],["1595","8","<b>שדגל מחנה ראובן. . דרום</b>: נסמן בסמוך."],["1596","9","<b>דרום. . דחסד</b>: ראה ספר המאמרים תר\"ן ע' שפט. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תצח. מאמרי אדה\"ז פרשיות התורה ח\"ב ע' תרטז."],["1597","10","<b>שדגל מחנה ראובן. . פני ארי'</b>: ראה בסמוך הערה ד\"ה: וכמבואר."],["1598","11","<b>פני ארי' להימין</b>: ע\"פ יחזקאל א, י."],["1599","12","<b>דגל מחנה ראובן תימנה</b>: במדבר ב, י."],["1600","13","<b>וכמבואר בזוהר בהיכלות דפ' פקודי</b>: ראה שער האמונה ספנ\"ד. תורת חיים חיי שרה קכט, ג. מאמרי אדה\"א ויקרא ח\"א ע' רכג. במדבר ח\"א ע' כה וע' סז. וראה זוהר במדבר קיח, ב."],["1601","14","<b>כביכורה בתאנה בראשיתה ראיתי את אבותיכם</b>: הושע ט, י [בהוספת תיבת ”את\"]."],["1602","15","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["1603","16","<b>ורוח אייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב. וירא צ, ריש ע\"ב. סידור ערב שבת קסג, ד. אמרי בינה שער התפילין פל\"א. אור התורה חנוכה כרך ב ע' רפו."],["1604","17","<b>ברוך. . לשון המשכה</b>: ראה לקוטי תורה בחוקותי מח, ב. ראה כט, א. מאמרי אדה\"א דברים ח\"א ס\"ע קכג ואילך."],["1605","18","<b>ונגלה כבוד הוי' וראו כל בשר</b>: ישעי' מ, ה."],["1606","19","<b>גנבא אפום מחתרתא</b>: גי' העין יעקב — ברכות סג, א. ראה הנסמן במאמרי אדה\"ז פרשיות התורה ח\"א לע' ט."]]],[2100490334,"שעה שה' צוה והזהיר על הגניבה ואעפ\"כ אינו שב מחטאו ולא עוד אלא שמבקש שיצליח רשעתו וכו' א\"כ אין זה אלא לפי דמה שקורא לרחמנא הוא רק מן השפה ולחוץ ואין זה אצלו בבחי' גילוי אור בשכל ומדות כו', וע\"כ ארז\"ל איזהו<sup data-n=\"1607\">20</sup> חכם הרואה את הנולד, פי' הנולד מאין ליש כו' שיהא אצלו בבחי' ראי' שכלי' ואז יהי' ממילא באוי\"ר תמידי' כו', וזהו פי' ברוך אומר ועושה שמתבונן בבחי' ראי' שכלי' איך שאומר ועושה מאין ליש באמירה זו כמ\"ש בדבר<sup data-n=\"1608\">21</sup> ה' שמי' נעשו כו' וכמ\"ש ויאמר אלקים יהי אור כו' וד\"ל. ופי' ברוך עושה בראשית הענין הוא על בחי' ששת ימי בראשית הראשונים מפני שכל שבת הוא בחי' שבת בראשית כי ו' ימים שלפני השבת מחודשים הן מתחלת הבריאה ממש ע\"ד ששת<sup data-n=\"1609\">22</sup> ימי בראשית הראשוני' מאחר שאמר מחדש<sup data-n=\"1610\">23</sup> בכל יום מעשה בראשית כו' לפי שבכל יום התהוות הנבראי' כולן מאין ליש באה בבחי' התחדשות ממש כמו שהי' לפני ההשתל' ממש וזהו ג\"כ פי' עושה בראשית לשון עושה הוא ענין הווה שבתמידות הוא מהווה מאין כו', והיינו ג\"כ פי' עושה בראשית לפי שבכל יום מחדש מע\"ב וע\"כ עושה בראשית כו' וד\"ל.\n<b>והנה</b> בברוך שאמר אנו אומרים יחיד חי העולמים מלך כו' ובק\"ש אנו אומרים אחד, וההפרש<sup data-n=\"1611\">24</sup> בין יחיד לאחד ידוע להיות כי פי' אחד הוא ענין אחדות ויחוד וחיבור שאין זה שייך אלא בדבר שצריך יחוד וחיבור והוא בב' דברים שהן נפרדים כו', וכך המשל למעלה להיות כי השמים והארץ וכל צבא העליונים והתחתונים כולם נמשכו מקור החיים בבחי' יש מאין שהוא בבחי' הפירוד להיות יש ודבר בפ\"ע כידוע ע\"כ כשממשיכים אור האלקי עליהם שיהיו מיוחדים ומחוברים באור אלקי ולא יפרידו היינו ענין אחד שהוא ליחדם ולחברם באור אלקי שלא ימצאו מציאות ונפרד כו', וזהו אחד<sup data-n=\"1612\">25</sup> א\"ח דלי\"ת פי' הח'<sup data-n=\"1613\">26</sup> הוא ז' רקיעים וארץ והד' הן ד' סטרי עלמא כו' וכמארז\"ל תמליכהו<sup data-n=\"1614\">27</sup> בשמים ובארץ ובד' רוחות העולם כו', וכמ\"ש במ\"א שזהו פי' לך<sup data-n=\"1615\">28</sup> הוי' הגדולה והגבורה כו' שהן בחי' ו\"ק העליונים שהם בחי' מקור ושרש לבחי' ו\"ק התחתונים מעלה ומטה כו', וכ\"ז אינו אלא בחי' היחוד האלקי",[["1607","20","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א. תניא פמ\"ג."],["1608","21","<b>בדבר ה' שמי' נעשו. . ויאמר אלקים יהי אור</b>: תהלים לג, ו. בראשית א, ג."],["1609","22","<b>ששת ימי בראשית. . מחודשי'</b>: ראה מאמרי אדה\"א דברים ח\"א ע' א'רסו ואילך."],["1610","23","<b>מחדש בכל יום מעשה בראשית</b>: ע\"פ ברכת יוצר."],["1611","24","<b>וההפרש בין יחיד לאחד</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קלה (ומקבילו בתורה אור וארא נה, ב) וע' רמט. פרשיות התורה ח\"ב ע' תשיד. לקוטי תורה בלק ע, א. ואתחנן יא, ג. דרך מצותיך ע' קכד. אמרי בינה שער הק\"ש פ\"ח."],["1612","25","<b>אחד א\"ח דלי\"ת</b>: ראה פרי עץ חיים שער (ח) הק\"ש פי\"ב."],["1613","26","<b>הח' ז' רקיעי'. . ד' סטרי</b>: ראה שולחן ערוך אדה\"ז הל' ק\"ש סס\"א ס\"ו."],["1614","27","<b>תמליכהו בשמי' ובארץ</b>: כ\"ה בכ\"מ בדא\"ח — ראה ברכות יג, ב. מאמרי אדה\"א דברים ח\"א ע' רלג. וש\"נ. ח\"ב ע' תסג. וש\"נ. ח\"ד ע' א'תקה. במדבר ח\"ג ע' תתפה וע' א'קפא. בראשית ע' שפד ע' תכט."],["1615","28","<b>לך הוי' הגדולה והגבורה</b>: דברי הימים-א כט, יא. ראה הנסמן לעיל בהערה ד\"ה: וההפרש."]]],[2100490335,"שיתייחד בנבראים, אבל בחי' מהו\"ע של אור האלקי הוא למעלה מגדר היחוד והחיבור הנ\"ל לפי שלמעלה הוא מבחי' השתל' השפע עדיין מאין ליש כו' ואיך שייך בו ענין יחוד דבר נפרד כו' מאחר שאין עוד מלבדו כו', והוא הנק' בחי' סוכ\"ע כידוע שאין שם בחי' מעלה ומטה וכו', ונק' מטעם זה יחיד ולא בלשון אחד שלשון יחיד משמעו ענין ההבדלה שהוא יחיד ומובדל ואין שני לו כלל שיתאחד כו', וכידוע בפי' יחיד שהוא כאשר האדם לבדו בלתי יש עוד אתו שיאמרו עליו שיתאחד עמו כו'. וז\"ש בב\"ש יחיד חי העולמים, פי' בתחלה הוא יחיד דהיינו בבחי' סוכ\"ע הנ\"ל למעלה מבחי' השתל' עדיין וע\"כ אין עוד מלבדו כלל ונק' יחיד כנ\"ל, ואח\"כ מתפשטת ההארה מאתו להיות בבחי' ממכ\"ע שהוא בחי' התפשטות להחיות רוח שפלים מאין ליש כנ\"ל בפי' עושה בראשית ואומר ועושה כו', וזהו פי' חי העולמי' מלך כו' מפני שכל חי העולמים כולם הוא רק מבחי' מלך וכמ\"ש ומלכותו<sup data-n=\"1616\">29</sup> בכל משלה וכן מלכותך מלכות כ\"ע<sup data-n=\"1617\">30</sup> כו', ולהיות כי ב\"ש הוא ענין הכנה לק\"ש כידוע ע\"כ מתחילים שם מבחי' יחיד ואיך שמתפשט ההארה מאתו להיות בבחי' אחד.\n<b>וכ\"ז</b> הוא כללות הענין גם בברכת יוצר כשאנו<sup data-n=\"1618\">31</sup> אומרי' וכולם ממליכים את שם המלך כו', פי' רק מבחי' שם ומלכות מקבלי' כל המלאכים כי בחי' מהו\"ע אינם יכולים לקבל מטעם הנ\"ל. ואח\"כ או' קדושת יוצר איך שאומרים המלאכים ג\"פ קדוש כו', והענין הוא שאו' קדוש עד שמשיגים בחי' הכח האלקי שמהווה מאין ליש שהוא הנק' הוי' צבאות כו', וג\"פ קדוש כי פי' קדוש הוא ענין בחי' הבדלה הנ\"ל<sup data-n=\"1619\">32</sup> ויש בבחי' יראה ואימה ופחד וכמ\"ש וכולם<sup data-n=\"1620\">33</sup> מקבלי' עליהם עומ\"ש באימה כו' וכיוצא, הכל הוא מפני שיש בהם רבוא רבבות מיני' וכמ\"ש אלף<sup data-n=\"1621\">34</sup> אלפי' ישמשוני כו', ודרך כלל הן ד' מחנות מיכאל תימנה ומחנה גבריאל כו' כמבואר בזהר<sup data-n=\"1622\">35</sup> בפרטי ההיכלות בפ' פקודי ע\"ש וד\"ל.\n<b>והנה</b> כתי' שמאלו<sup data-n=\"1623\">36</sup> תחת לראשי וימינו תחבקני, פי' שמאלו וימינו הוא בחי' שמאל וימין העליון דבחי' סוכ\"ע הנ\"ל וכמא' ימינא<sup data-n=\"1624\">37</sup> ושמאלא ובניהו כלה",[["1616","29","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["1617","30","<b>מלכותך מלכות כ\"ע</b>: תהלים קמה, יג."],["1618","31","<b>כשאנו אומרי' וכולם ממליכים את שם המלך</b>: בברכת יוצר [בדילוגים]."],["1619","32","<b>הנ\"ל</b>: במאמרי אדה\"א שם נוסף: שהוא בחי' סוכ\"ע וג\"פ הוא קדוש ומובדל עד שנעשה בחי' הוי' צבאות להוות מאין ליש כו' וכמ\"ש הטעם<sup data-n=\"e38\">*</sup> לג\"פ דוקא במ\"א, ומה שנזכר בברכת יוצר אור מענין המלאכים שיש מתפעלי' באהבה."],["1620","33","<b>וכולם מקבלים עליהם עומ\"ש באימה</b>: ראה ברכת יוצר."],["1621","34","<b>אלף אלפי' ישמשוני</b>: דניאל ז, י."],["1622","35","<b>בזהר. . פקודי</b>: ראה שער האמונה ספנ\"ד. תורת חיים חיי שרה קכט, ג. מאמרי אדה\"א ויקרא ח\"א ע' רכג. במדבר ח\"א ע' כה וע' סז. ראה זהר במדבר קיח, ב."],["1623","36","<b>שמאלו תחת לראשי</b>: שיר השירים ב, ו."],["1624","37","<b>ימינא ושמאלא ובניהו כלה</b>: פיוט אזמר בשבחין (זמירות ליל שבת)."],["e38","*","<b>הטעם לג\"פ</b>: ראה תורה אור מקץ לו, ב. ומקבילו בספר המאמרים תקס\"ה ח\"א ע' קכד. תו\"א תשא פו, א. מאמרי אדה\"א דברים ח\"ג ע' תתקב."]]],[2100490336,"כו', וזהו בחי' אתעדל\"ע<sup data-n=\"1625\">38</sup> בשמאל העליון וימין העליון כמ\"ש שמאל[ו] תחת לראשי כו' ע\"י אתעדל\"ת דוקא, כידוע שאין אתעדל\"ע אלא ע\"י אתעדל\"ת תחלה וכמא' רוח אייתי רוח ואמשיך רוח כו' וכתי' אם ישים אליו לבו רוחו ונשמתו אליו יאסוף וכמ\"ש במ\"א, וגם כאן מה שנמשך ימין ושמאל העליון לחבק לכלה שהיא כנ\"י למעלה זהו ע\"י בחי' אתעדל\"ת מכנ\"י למטה תחלה ג\"כ באותו האופן דוקא, והוא בבחי' ימין ושמאל, בחי' ימין הוא בפסוק ואהבת כו' שהוא כללות פ' ראשונה דק\"ש, כמו שאוהב אדם לחבירו שנמשך לבו אחריו כך יש אהבה מכנ\"י כלפי מעלה שנמשך הלב כמים, והוא ענין אהבת בכל לבבך כו', והוא ע\"י בחי' ראי' מקרוב דוקא כנ\"ל שאין האהבה באה אלא מצד הקירוב כו', ואח\"כ באה הדביקות וההתקשרות ממש ע\"י הקירוב הזה, והוא באומרו ובכל נפשך, פי' בכל נפשך לקשר בחי' הנפשיות מחשבה דבור כו', מח' במח' בגדולת ה' ואור תורה ודבורו בדבור שבתו', וזהו אליך<sup data-n=\"1626\">39</sup> הוי' נפשי אשא, וזוהי שלימות האהבה והקירוב, וכמשל<sup data-n=\"1627\">40</sup> המתקרב אל המלך באהבה ואח\"כ מדבר המלך ע\"י ומשתמש בו כו' וד\"ל.\n<b>וזהו</b> בחי' ראובן רא\"ו ב\"ן והוא בחי' פ' ראשונה דק\"ש שהיא בבחי' ימין דהיינו סט' דחסד שהוא דגל מחנה יהודה תימנה כנ\"ל ובאתדל\"ת אמשיך רוח להיות ג\"כ אור האהבה העליוני' נמשך מלמעלה למטה כמים<sup data-n=\"1628\">41</sup> שיורדים מגבוה לנמוך כו' וכמ\"ש אהבת<sup data-n=\"1629\">42</sup> עולם אהבתיך ע\"כ משכתיך חסד והוא מ\"ש וימינו תחבקני וד\"ל. וזהו שאמרה לאה בלידת ראובן כי ראה<sup data-n=\"1630\">43</sup> ה' בעניי כי עתה יאהבני אישי כו' פי' כי עתה דוקא ע\"י בחי' ראי' מקרוב לאסתכלא ביקרא דמלכא שהוא בחי' ראי' מלמטה למעלה עי\"ז נמשך אהבה מקרוב מלמעלה למטה ג\"כ בבחי' ראי' וכמ\"ש ראיתי<sup data-n=\"1631\">44</sup> את אבותיכם והוא בחי' רא\"ו ב\"ן כנ\"ל וזהו כי עתה יאהבני אישי בחי' סוכ\"ע שנק' אישי, כמ\"ש ביום<sup data-n=\"1632\">45</sup> ההוא תקראי לי אישי כו' וכמ\"ש ואל<sup data-n=\"1633\">46</sup> אישך תשוקתך כו', יאהבני בבחי' אהבה מקרוב שהוא בחי' ראי' כנ\"ל וד\"ל.",[["1625","38","<b>אתעדל\"ע. . אתעדל\"ת</b>: ראה זהר לך פח, א. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. ח\"ב ע' תנה. ח\"ד ע' א'שכ."],["1626","39","<b>אליך הוי' נפשי אשא</b>: תהלים כה, א."],["1627","40","<b>וכמשל המתקרב אל המלך</b>: ראה גם מאמרי אדה\"א בראשית ע' תקמא."],["1628","41","<b>כמים שיורדים מגבוה לנמוך</b>: ראה תענית ז, א."],["1629","42","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — אבל כ\"ה בכ\"מ, ומהם: מאמרי אדה\"א בראשית ע' שדמ. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקפב. נביאים ע' ריא. מאמרי אדה\"א ויקרא ח\"א ע' ח. וש\"נ. ח\"ב ע' תשנח. במדבר ח\"א ע' טו. ח\"ב ע' תתנח. וע' תתסב. ח\"ג ע' תתקסב. דברים ח\"ג ע' תתקעב. וש\"נ. דברים ח\"ד ע' א'שלג]."],["1630","43","<b>כי ראה ה' בעניי</b>: ויצא כט, לב."],["1631","44","<b>ראיתי את אבותיכם</b>: נסמן לעיל בפיסקא ד\"ה: אמנם."],["1632","45","<b>ביום ההוא תקראי לי אישי</b>: הושע ב, יח [בדילוג תיבות ”נאום ה'\" ובהוספת תיבת ”לי\" — וכ\"ה גם בתורה אור כאן מח, ב. מאמרי אדה\"א דברים ח\"ב ע' תקכב. וש\"נ. במדבר ח\"ג ע' א'רס וע' א'ער]."],["1633","46","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."]]],[2100490337,"<b>ומהשאמרה</b> עוד כי ראה ה' בעניי כו', כי הנה פי' בכל לבבך<sup data-n=\"1634\">47</sup> ידוע שהוא בשני יצריך כמארז\"ל, והענין הוא דהיינו בחי' גבו' שבחסד דמפני אהבה יבא לבחי' מרירות וצער על היפוכו ממה שמרוחק עדיין ולא נתדבק כראוי כו' והוא בחי' פנימי' האהבה, ונק' חולת<sup data-n=\"1635\">48</sup> אהבה כידוע בפי' רשפי'<sup data-n=\"1636\">49</sup> רשפי אש כו' דמוקדין<sup data-n=\"1637\">50</sup> לי' בשלהובא דרחימותא והיינו בגלותא דוקא מפני עוצם הריחוק שיבא מזה תגבורת התשוקה באהבה כו', והיינו ג\"כ בחי' בע\"ת שגדולי' מצ\"ג משום דמשכין<sup data-n=\"1638\">51</sup> לי' בחילא יתיר כו' כמ\"ש בזוהר, וזהו מ\"ש ויצעקו<sup data-n=\"1639\">52</sup> אל ה' בצר להם כו' פי' מן המיצר והצמצום שהוא בחי' התגשמות זה העולם מכל צד בבחי' זמן ומקום, וגם מי שאין לו חטא ועון יכול להיות בע\"ת לצאת מחשך והסתר זה העולם הגשמי וגם מעולמות<sup data-n=\"1640\">53</sup> העליוני' ממנו שגם הם בבחי' גבול ותכלית ת\"ק שנה כו', שכ\"ז בחי' העלם והסתר לאור אלקים חיים שהוא בחי' א\"ס אין לו תחלה ואין לו תכלה כו', ע\"כ באה הנפש לידי מרירות וצער מהסתר הזה, והוא מ\"ש ויצעקו אל הוי' בחי' סוכ\"ע בצר להם מבחי' הצמצום וההסתר כו' וכמ\"ש מן<sup data-n=\"1641\">54</sup> המיצר קראתי י\"ה כו'. וזהו ג\"כ פי' כי ראה ה' בעניי פי' בבחי' העוני והמיצר שלי כי מפני בחי' התשוקה באהבה מקרוב הנ\"ל כשימנע ממנו ההתקרבות והראי' זהו בחי' עוני ביותר, והיינו כי ראה ה' ג\"כ בבחי' אהבה מקרוב בעוני בצעקתם מצר להם ע\"כ יאהבני אישי באתעדל\"ע ג\"כ בבחי' פנימי' אהבה ע\"ד העלאה זו כי רוח אייתי רוח ואמשיך רוח כו' וד\"ל.\n<b>וכ\"ז</b> בחי' פ' ראשונה דק\"ש שהוא בחי' ראובן כנ\"ל, אבל פ' שניה והי' א\"ש תשמעו כו' הוא בחי' שמעון. דהנה בלידת שמעון אמרה כי<sup data-n=\"1642\">55</sup> שמ\"ע ה' כי שנואה אנכי ויתן לי גם את זה כו', להיות ידוע דהראי' מקרוב והשמיעה מרחוק דוקא וכמ\"ש ה'<sup data-n=\"1643\">56</sup> שמעתי שמעך יראתי כו', והטעם הוא דהנה כתי' והחיות<sup data-n=\"1644\">57</sup> רו\"ש, פי' בחי' הרצוא מבואר למעלה שהוא בחי' האהבה מקרוב להתקרב ולהתדבק בתשוקה מורגשת וכמ\"ש ואל אישך תשוקתך, והוא ע\"י בחי' ראי' לאסתכלא כו' שהוא בחי' ראובן כנ\"ל. והנה אחר בחי' הרצוא הנ\"ל יש בחי' שוב שהוא היפוך בחי' הרצוא ממש וכמא' הס\"י אם<sup data-n=\"1645\">58</sup> רץ לבך שוב, והענין של בחי' השוב הזה הוא בחי'",[["1634","47","<b>בכל לבבך. . בשני יצריך</b>: ואתחנן ו, ה. ובספרי שם. ברכות נד, א (במשנה). ראה מאמרי אדה\"א דברים ח\"ד ע' א'קעח. וש\"נ. במדבר ח\"ג ע' א'רמז."],["1635","48","<b>חולת אהבה. . בגלותא</b>: שיר השירים ב, ה. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקס. וש\"נ. דברים ח\"ב ע' עתר. וש\"נ."],["1636","49","<b>רשפי' רשפי אש</b>: שיר השירים ח, ו. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקיב. וש\"נ. ח\"ד ע' א'תסב. וש\"נ."],["1637","50","<b>דמוקדין לי' בשלהובא דרחימותא</b>: ראה זהר קדושים פד, א."],["1638","51","<b>דמשכין לי' בחילא יתיר</b>: ראה זהר חיי שרה קכט, ב. אגרת התשובה פ\"ח. מאמרי אדה\"א דברים ח\"ב ע' תקעז. ח\"ג ע' א'קכח."],["1639","52","<b>ויצעקו אל ה'</b>: תהלים קז, ו. כח."],["1640","53","<b>מעולמות העליוני'. . ת\"ק שנה</b>: ראה חגיגה יג, א."],["1641","54","<b>מן המיצר קראתי י\"ה</b>: תהלים קיח, ה."],["1642","55","<b>כי שמ\"ע ה' כי שנואה אנכי</b>: ויצא כט, לג."],["1643","56","<b>ה' שמעתי שמעך יראתי</b>: חבקוק ג, ב."],["1644","57","<b>והחיות רו\"ש</b>: יחזקאל א, יד."],["1645","58","<b>אם רץ לבך שוב</b>: ספר יצירה פ\"א מ\"ח."]]],[2100490338,"הריחוק שמתרחק ומשפיל א\"ע מאד, והוא בחי' שמאל<sup data-n=\"1646\">59</sup> דוחה דהיינו שמדחה א\"ע ומשפיל א\"ע ביותר להיות עומד בריחוק מקום דוקא, משא\"כ בחי' ימין של אהב' בבחי' ראי' הנ\"ל שהוא מקרוב דוקא כי ימין<sup data-n=\"1647\">60</sup> מקרבת ושמאל דוחה כו', ובחי' הדחיי' הזאת היא באה מחמת השפלות שבאה בנפשו אחרי שהוא רואה ומתבונן בגדולת ה' איך שהוא רם ומתנשא על כל ההשתל' בעלוי אחר עלוי עד רום המעלות א\"כ תקטן נפשו מאד בעיניו ויעמוד מרחוק מפני היראה מעוצם הרוממות וההתנשאות ויהי' נבזה בעיניו נמאס בתכלית הקטנות, וכל שיותר הוא מכיר בגדולת ה' יותר תקטן נפשו בעיניו וכמ\"ש דוד ונקלותי<sup data-n=\"1648\">61</sup> עוד מזאת והייתי שפל בעיני כו' מפני שכל מה שתגדל בעיניו ביותר גדלות הבורא יכיר יותר שפלות ערכו ואיך שאיננו ראוי כלל לקירוב ודביקות כו', וכענין וינועו<sup data-n=\"1649\">62</sup> ויעמדו מרחוק וכמו שאמרו בפירוש דבר אתה עמנו כו' והרי זה הי' בהם מפני עוצם הרוממות שנתרומם ונתגדל אצלם אא\"ס בהגלות נגלות עליהם בהר בקולות וברקים כו'. וכיוצא בזה יובן מה שאמר חבקוק שמעתי שמעך יראתי כו' מפני שהיראה<sup data-n=\"1650\">63</sup> לעמוד מרחוק כנ\"ל היא באה מסיבת השפלות והשפלות אינה אלא לאחר הכרת עוצם הרוממות כנ\"ל, והכרה זו היא בחי' שמיעה שהיא מרחוק דוקא, שהשמיעה הוא ענין הבנה והשגה וכמ\"ש דבר<sup data-n=\"1651\">64</sup> נא כי שומע עבדך כלומר מבין וההבנה אינה אלא מרחוק דוקא כי בבואו בקרוב יראנו בעין וא\"צ לזה השגה, ולכך אינו<sup data-n=\"1652\">65</sup> דומה שמיעה לראי' כי הראי' מקרוב והשמיעה מרחוק, וע\"ד דוגמ' הנה כשהאדם עומד מרחוק מהיכל המלך אינו אלא שומע באזניו מזולתו מעניני רוממות גדולתו משא\"כ העומד בהיכל המלך פנימה כו'. וכך יובן ג\"כ בענין בחי' השוב הנ\"ל שהוא בחי' עמידה מרחוק שאז הוא בבחי' שמיעה בלבד, כי אם הי' בבחי' הראי' מקרוב לא הי' נופל בו היראה אלא אדרבה האהבה והקירוב כנ\"ל אלא מוכרח שאינו אלא בבחי' שמיעה שהוא מרחוק ע\"כ יהי' נסוג אחור מפני היראה והוא בחי' שוב הנ\"ל, וזהו שמעתי שמעך יראתי שהיראה עם השמיעה ענין א' אך לפני היראה קדמה השמיעה כו' והוא בחי' שמאל דוחה הנ\"ל (דקו<sup data-n=\"1653\">66</sup> השמאל הוא בינ\"ה גבור\"ה וכו' והשמיעה<sup data-n=\"1654\">67</sup> בבחי' בינה והראי' בבחי' חכ' כו' כידוע וד\"ל.",[["1646","59","<b>שמאל דוחה</b>: ראה הערה הבאה."],["1647","60","<b>ימין מקרבת ושמאל דוחה</b>: ראה סוטה מז, א."],["1648","61","<b>ונקלותי עוד מזאת</b>: שמואל-ב ו, כב."],["1649","62","<b>וינועו ויעמדו מרחוק. . דבר אתה עמנו</b>: יתרו כ, טו. שם טז."],["1650","63","<b>שהיראה לעמוד מרחוק</b>: ראה מאמרי אדה\"א דברים ח\"א ע' קעו-ז ובהנסמן שם."],["1651","64","<b>דבר נא כי שומע עבדך</b>: שמואל-א ג, י [בהוספת תיבת ”נא\" — ראה ספר המאמרים תקס\"ה ח\"ב ס\"ע תשה]. ראה הערה במאמרי אדה\"א ויקרא ח\"ב ע' תשמא. בהנסמן לפנ\"ז."],["1652","65","<b>אינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לקח טוב שלח יג, יח. מאמרי אדה\"א ויקרא ח\"א ע' שי ואילך. דברים ח\"א ע' קמז ואילך."],["1653","66","<b>דקו השמאל. . בינ\"ה גבור\"ה וכו'</b>: ראה זהר (רעיא מהימנא) בהעלותך קנג, ב. פרדס שער (ו) סדר עמידתן פ\"א. עץ חיים שער (א) דרוש עיגולים ויושר ענף ב. מאמרי אדה\"א דברים ח\"ב ריש ע' תרעח. וש\"נ. במדבר ח\"ג ע' א'קלג."],["1654","67","<b>והשמיעה. . בינה</b>: ראה זהר (אדרא רבא) נשא קלח, ב. מאמרי אדה\"א פרשיות התורה ח\"ב ע' תקלז ואילך ובהנסמן לשם."]]],[2100490339,"<b>וזהו</b> שאמרה כי שמע ה' כי שנואה אנכי, פי' כי שנואה אנכי להשפיל א\"ע בבחי' שמאל דוחה הנ\"ל עד שיהי' נבזה בעיניו נמאס בבחי' שנואה לבעלה כו' מצד עוצם השפלות כנ\"ל, ומחמת אתעדל\"ת הזאת בבחי' שמאל דוחה מעורר ג\"כ למעלה בחי' אתעדל\"ע ע\"ד הזה כי רוח אייתי רוח כו' וכנ\"ל והיינו שמעורר למעלה בחי' שמאל העליון להיות שמאלו תחת לראשי כו' וה\"ז בחי' קירוב שמגביה ראש דכנ\"י בשמאלו והוא מפני ששמאל התחתון דוחה א\"ע בשפלות כו', והיינו שאמרה כי שמע ה' כי שנואה אנכי בבחי' שמיעה מרחוק ג\"כ שכפי אתעדל\"ת כך הוא אתעדל\"ע אך הי' שמיעה זו מרחוק לבא אלי לקרבני להיות שמאלו תחת לראשי כו'. וזהו ענין פ' שני' והי' א\"ש תשמעו שהוא בחי' שמיעה מרחוק והוא בבחי' קו השמאל הדוחה כו', וע\"כ נאמר בפ' זו בחי' גבורות ודינים השמרו<sup data-n=\"1655\">68</sup> לכם פן יפתה לבבכם כו' וחרה אף ה' כו' וכיוצא, וזהו בחי' שמעון, אבל פ' ראשונה היא בחי' ראובן כנ\"ל, ובכלל הן בחי' ימין ושמאל רו\"ש ומעוררים למעלה שיהי' שמאלו תחת לראשי וימינו תחבקני כו' וד\"ל.\n<b>אך</b> הנה כ\"ז ההתעוררות בימין ושמאל באתעדל\"ע אחר אתעדל\"ת עדיין הוא רק בחי' הכנה לפני היחוד האמיתי, אבל בחי' לוי הוא מה שאמרה עתה<sup data-n=\"1656\">69</sup> הפעם ילוה אישי אלי פי' ילוה הוא ענין היחוד ממש כידוע. ולהבין ביאור ענין זה היחוד דלטעם זה נק' לוי בבחי' מדרגה שלישית מלבד בחי' ראובן ושמעון הנ\"ל, הנה זהו ענין המא' הנ\"ל דימינא ושמאלא ובנייהו כלה כו', וזהו ג\"כ בחי' וענין ט\"ו ווי\"ן שבאמת ויציב שהוא אחר ב' פרשיות דק\"ש שמע וא\"ש כו'. והענין הוא להיות ידוע כי התורה נמשלה למים כמ\"ש הוי<sup data-n=\"1657\">70</sup> כל צמא לכו למים כו', ועד\"מ הנפש הצמאה בצמאון כששותה מים תסלק ממנה הצמאון ויהי' לה מנוח כו' כך התו' הוא בחי' מים העליוני' (הנק' מ\"ד), וע\"י שהאדם לומד ההלכה בדבור בפה בחי' המים העליוני' הללו משיבי' את ניצוץ האלקי שהי' צמא בבחי' רו\"ש הנ\"ל דהיינו אחר אתעדל\"ת הנ\"ל באהבה מקרוב ובשמאל דוחה כו' שנעשה עי\"ז שמאלו תחת לראשי וימינו תחבקני כנ\"ל אזי נעשה גוף היחוד והוא בחי' אתדבקות<sup data-n=\"1658\">71</sup> רוחא ברוחא ממש, והוא בחי' התקשרות הדבור בדבר<sup data-n=\"1659\">72</sup> ה' זו הלכה וכמ\"ש ודברי<sup data-n=\"1660\">73</sup> אשר שמתי בפיך כו' דברי ממש הוא שמתקבל ושופע בדבורו של אדם, וזהו בחי' יחוד ממש כמשל יחוד משפיע ומקבל גשמיי' כו', וכן ע\"י המצות<sup data-n=\"1661\">74</sup> שנק' רמ\"ח אברים דמלכא כידוע בענין אשר<sup data-n=\"1662\">75</sup> קדשנו במצותיו כו' נעשה ג\"כ בחי' יחוד ממש והוא בחי' חיבור ויחוד גופא דמלכא ברמ\"ח אברים דילי' בכנ\"י כו', ונמצא ע\"י התומ\"צ נעשה יחוד עליון דקוב\"ה",[["1655","68","<b>השמרו לכם. . וחרה אף ה'</b>: עקב יא, טז. יז."],["1656","69","<b>עתה הפעם ילוה אישי אלי</b>: ויצא כט, לד."],["1657","70","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["1658","71","<b>אתדבקות רוחא ברוחא</b>: ראה זהר משפטים קכד, ב."],["1659","72","<b>בדבר ה' זו הלכה</b>: שבת קלח, ב."],["1660","73","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["1661","74","<b>המצות. . רמ\"ח אברים</b>: ראה תקו\"ז ת\"ל (עד, סע\"א). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' ק. דברים ח\"ד ע' קצא."],["1662","75","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."]]],[2100490340,"ושכינתי' (בחי' יחוד מ\"נ ומ\"ד כשמתחברים יחד כו' וד\"ל), וזהו ענין ימינא ושמאלא ובנייהו כלה בבחי' יחוד ממש. והיינו ג\"כ ענין ט\"ו<sup data-n=\"1663\">76</sup> ווי\"ן שבאמת ויציב, דהנה אנו אומרים אמת ויציב כו' עד ונחמד ונעים הדבר הזה כו', הענין הוא דהדבר הזה הוא מ\"ש בק\"ש שמע ישראל כו' עד והיו הדברי' האלה אשר אנכי מצוך כו' ועל אותו הדבר הוא שאומר שהוא אמת ויציב ונכון כו' ונחמד ונעים בט\"ו ווי\"ן כלומר כמו אות<sup data-n=\"1664\">77</sup> הוי\"ו הגשמי מורה בצורתו בחי' ההמשכה מלמעלמ\"ט כידוע כן הדבר הזה שהוא התו' והמצו' שנק' מים עליונים המה נמשכים בט\"ו ווין הנ\"ל מלמעלמ\"ט בכנ\"י באמרינו ויציב ונכון עד ומקובל כו' הכל בווי\"ן, ופי' ונחמד ונעים הוא בחי' התקשרות השפע במקבל להיות בבחי' נעימות כו' (ואזי אתבסמת<sup data-n=\"1665\">78</sup> נוק' ונמתקו הגבו' שלה וכמ\"ש קול<sup data-n=\"1666\">79</sup> ה' יחולל אילות דקאי בקול דאוריית' דוקא מטעם הנ\"ל וכמ\"ש במ\"א). וזהו בחי' לוי שאחר ימינא ושמאלא דראובן ושמעון הנ\"ל, וכמו שאמרה עתה הפעם ילוה אישי אלי בבחי' יחוד ממש מפני שאתעדל\"ע ג\"כ יהי' בבחי' מים שיורדים מגבוה לנמוך כנ\"ל, וילוה אישי פי' היינו אמיתית הדביקות שהוא ע\"י החסדי' דבחי' מ\"ד דוקא, והוא למעלה הרבה מבחי' ראובן שאמרה עתה יאהבני אישי שאינו אלא ימינו תחבקני כנ\"ל, וזהו ע\"י תורה וגמ\"ח שנק' מים כנ\"ל וד\"ל.\n<b>וזהו</b> יהודה אתה יודוך אחיך כו', פי' אחיך שהן בחי' ראובן שמעון ולוי הנ\"ל הם אשר יודוך כלומר עשאוך להיות נק' יהודה, וזהו יהודה אתה מה שבחי' יהודה בא לבחי' גילוי באתה שהוא בחי' ההתגלות כנודע הוא מפני שיודוך אחיך דוקא כנ\"ל. ולהבין זה תחלה יש להבין שרש ענין יהודה מהו. דהנה אחר אמת ויציב אעפ\"י שהוא בחי' היחוד כמ\"ש ילוה אישי אלי עכ\"ז עדיין אין עיקר היחוד אלא בש\"ע בתפלה שבלחש דוקא והתפלה שבלחש הוא שנק' בחי' יהודה וכמ\"ש הפעם אודה את ה' כו', וענין ההודאה הזאת הוא למעלה הרבה מבחי' אהבה ודביקות כו', כי הנה האהבה הוא בדבר המושג שתכסוף נפשו אליו כו', אבל בדבר שאינו מושג כלל לא יוכל להגיע אליו בשום צד קירוב ודיבוק אלא הן רק בבחי' הודאה וביטול בלבד, כמו בעמדו לפני המלך ממש שלא יוכל לימשך אליו באהבה וקירוב מפני הבדלת רוממות ערכו כו' אבל רק בהודאה שהוא בחי' ביטול במציאות יוכל לעמוד לפניו, והוא ענין הכריעות וההשתחוואו' שבש\"ע מפני שהוא לבחי' סוכ\"ע שנק' סדכ\"ס<sup data-n=\"1667\">80</sup> ולית מח' תפיסא בי' אפי' מח' דא\"ק כו', והענין הוא שהוא למעלה לגמרי מכל בחי' ההשתל' דאבי\"ע וע\"כ קמי' כחשיכה<sup data-n=\"1668\">81</sup> כאורה כו' רוחני' וגשמי' שוין ממש מאחר שאינו נתפס בתוך עלמין כלל בבחי' ממכ\"ע כו', וא\"כ אין מגיעים לו בתפלה שבלחש רק בבחי' הביטול וההשתחוואה שהוא העדר",[["1663","76","<b>ט\"ו ווי\"ן שבאמת ויציב</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תנא. וש\"נ. ח\"ג ע' תתקעא."],["1664","77","<b>אות הוי\"ו. . ההמשכה</b>: ראה אגרת התשובה פ\"ד."],["1665","78","<b>אתבסמת נוק'</b>: לשון הזהר לך צד, א."],["1666","79","<b>קול ה' יחולל אילות</b>: תהלים כט, ט. ראה מאמרי אדה\"ז הקצרים ע' רז ואילך."],["1667","80","<b>סדכ\"ס ולית מח' תפיסא בי'</b>: זהר יתרו פט, א. תרומה קמו, ב. תקוני זהר בהקדמה יז, א."],["1668","81","<b>כחשיכה כאורה</b>: תהלים קלט, יב."]]],[2100490341,"הכלי כו'. וזהו פי' ענין יהודה הפעם אודה את ה' בבחי' הודאה לשם הוי' בחי' סוכ\"ע כו' שאינו מושג כלל כו' אך ע\"י הודאה זו באה עכ\"פ הארה מבחי' סוכ\"ע בכנ\"י, וכידוע דע\"י אתעדל\"ת אתעדל\"ע כו', וזהו פי' יהודה אתה שבחי' יהודה לסוכ\"ע הנ\"ל בא לבחי' גילוי מן ההעלם בבחי' אתה שהוא בחי' ממכ\"ע והוא עיקר היחוד, וזהו למעלה מבחי' לוי הנ\"ל, דמה שילוה אישי אינו אלא ממה שיוכל אור אלקי לבא בבחי' השתל' בדרך משפיע ומקבל כו' אבל בחי' יהודה הוא בחי' האור העצמי של א\"ס ב\"ה דלית מח' תפיסא בי' כנ\"ל. וזהו ענין שמ\"ע שאחר ב' פרשיות דק\"ש ואמת ויציב דוקא, כי גם אם לא שהקדימו בפסד\"ז וברכות ק\"ש כו' לא היו יכולים להתחיל בש\"ע בלבד כי בחי' סוכ\"ע לא יכולים לקבל כ\"א ע\"י הכנה בתחלה מלמטה למעלה שהוא בג' מדרגות הנ\"ל ראובן שמעון ולוי והן ב' פרשיות ואמת ויציב אז יכולי' לעמוד בש\"ע (ובמנחה ששייך לבקר דאברהם וכבר הקדימו בשחרית א\"צ להאריך בפסד\"ז ובק\"ש לפני ש\"ע ויכולי' להתחיל בש\"ע בלבד מיד, אבל בערבית ששייך ליום שלאחריו צריך להתחיל בק\"ש לפני ש\"ע כו'). וז\"ש יהודה אתה יודוך אחיך, פי' מה שאתה יהודה בבחי' הגילוי מבחי' סוכ\"ע בש\"ע בלחש ובחשאי שהוא בחי' ביטול כנ\"ל היינו ע\"י אחיך בחי' ראובן שמעון ולוי שקדמו תחלה שהרי הם עשאוך באתעדל\"ע שיהי' למעלה ימינא ושמאלא ובינייהו כלה בבחי' היחוד תחלה כנ\"ל, ואח\"כ יודוך אחיך הנ\"ל להיות נק' בשם יהודה בשמ\"ע שלמעלה גם מיחוד זה כו' וד\"ל. ובזה מובן בפי' יהודא בלשון הוה שלמעלה מן הזמן שהוא בבחי' ש\"ע<sup data-n=\"1669\">82</sup> בצלותא דבלחש שאז הארת סוכ\"ע ועכ\"ז נקרא יהודה בקמץ תחת הדלי\"ת לפי שע\"י אחיו הנ\"ל נעשה יהודה כנ\"ל. וזהו שאמרה הפעם אודה את ה' כו' הפעם דוקא אחר שקדמו ראובן ושמעון ולוי שהם ב\"פ דק\"ש ואמת ויציב וד\"ל.\n<b>ידך</b> בעורף אויביך. הנה בחי' עורף הוא בחי' חצוני', עד\"מ עורף באדם שהוא למול פני הראש ואחוריו להיות כי בפנים של אדם מאיר מבחי' פנימי' החיות של הנפש כידוע ובאחורי העורף אין מאיר שם רק מבחי' חצוני' הנפש, כך צריך שיהא האדם בעניני עוה\"ז בבחי' חצוני' בלבד והוא בבחי' עורף דהיינו בבחי' הקרירות ולא בבחי' פנימי' כו' שהוא מקרב<sup data-n=\"1670\">83</sup> לב עמוק כו' כידוע, אך עכ\"פ בבחי' קרירות בהכרח הוא שיהי' באדם מפני צורך פרנסתו כו', וא\"כ בהיות עובד ה' אח\"כ בתפלה שבלב הרי עולה לה' כל מה שעשה בעניני פרנסתו, מן המאכל שאכל יתחזק כח שכלו ומדותיו בהתבוננו' אחדות הוי' ומדות אוי\"ר בק\"ש וממעות שקיבץ יעשה צדקה להחיות רוח שפלי' וכיוצא עד שנמצא בזה מתעלים גם כל כחות חצוניו' שנפשו נמשך בעניני פרנסתו לה' אחד. וזהו ידך בעורף אויביך, פי' אויביך הן כל עניני עוה\"ז שנמשכו מהיכלות החצוני' דע' שרים<sup data-n=\"1671\">84</sup> שיניקתם מאחוריים דקדושה כידוע",[["1669","82","<b>ש\"ע בצלותא דבלחש</b>: ראה תיקונים בזהר חדש קא, ג. זהר ויקהל רב, א. שולחן ערוך אדה\"ז הל' תפלה סק\"א ס\"ב-ד. ניצוצי אורות לזוהר ויגש רי, א. אור התורה נח כרך ג ע' 1204."],["1670","83","<b>מקרב לב עמוק</b>: ע\"פ תהלים סד, ז."],["1671","84","<b>דע' שרים שיניקתם מאחוריים דקדושה</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'שצח. וש\"נ."]]],[2100490342,"והנה\"ב<sup data-n=\"1672\">85</sup> שבאדם משם ג\"כ נמשכה כידוע, ומלבד שבחי' פנימי' שבנפש הזאת נתבררה כבר להיות שלא נמשך כלל בעניני גשמיו' דנוגה דעשי' כנ\"ל עוד זאת שגם בחי' חצוני' שבה שנק' עורף אויביך גם הוא מתהפך לקדושה האלקי', וע\"ד שיהי' לע\"ל דכתי' ואת<sup data-n=\"1673\">86</sup> רוח הטומאה אעביר כו'. אך מהיכן יש כח הזה להפוך גם בחי' החצוני' דקליפה לקדושה היינו שאמר ידך בעורף אויביך, פי' ידך הוא בחי' יד הגדולה כמ\"ש וירא<sup data-n=\"1674\">87</sup> ישראל את היד הגדולה כו', ועל בחי' יד הגדולה הזאת אמר וימינך פשוטה לקבל שבים פי' לפי שיד הזאת נק' גדולה כי לעוצם רוממות מדריגתה למעלה מעלה ע\"כ יכולה היא להתפשט מטה מטה מאד, עד\"מ יד הגדולה באדם שתתפשט למטה למטה בעומק ג\"כ להשיג גם מי שנפל בתחתית כו', וזהו פי' וימינך<sup data-n=\"1675\">88</sup> פשוטה לפי שמתפשטת עד אין שיעור למטה כו' וע\"כ מקבלת גם השבים שאינם ראויים שיתקבלו דהיינו לאהפכא חשוכא לנהורא גם מבחי' חצוני' דקליפה שנק' שאול תחתית כו' וד\"ל, ועיקר הטעם הוא לפי שבחי' ימין זה שפשוטה לקבל שבים הוא נמשך מבחי' סוכ\"ע הנ\"ל דקמי' כחשיכה כאורה כו' וגם חשך לא יחשיך<sup data-n=\"1676\">89</sup> כו' לפי שהוא מבחי' עצמו' המאציל שלפני ההשתל' עדיין ושם שוה<sup data-n=\"1677\">90</sup> ומשוה קטן וגדול כמ\"ש קטן<sup data-n=\"1678\">91</sup> וגדול שם הוא כו' עד שבחי' רוחניות נק' גשמיו', וכמו החכ' שנק' ראשית<sup data-n=\"1679\">92</sup> בסדר ההשתל' ולגבי עצמות המאציל נק' בשם בחי' עשי' גשמי' וכמ\"ש כולם<sup data-n=\"1680\">93</sup> בחכ' עשית כידוע, וכן בהיפוך שהגשמיות כרוחניות חשוב וכמ\"ש בפי' כחשיכה כאורה שהחושך כאור<sup data-n=\"1681\">94</sup> ממש, והוא מטעם שלמעלה הוא לגמרי מבחי' וערך השתל' וכמ\"ש לך<sup data-n=\"1682\">95</sup> הוי' הגדולה והגבורה כו' ולהיות כן יכול להיות שההארה משם יהפוך גם החשך של חצוני' הקליפות לאור הקדושה וכמ\"ש אם<sup data-n=\"1683\">96</sup> אסק שמים שם אתה אציע שאול הנך שגם בשאול תחתית החשך לא יחשיך מפני דקמי' כחשיכה כאורה כו', ולכך גם שם ימינו פשוטה לקבל שבים. וזהו יד\"ך דוקא וא\"ת<sup data-n=\"1684\">97</sup> ידך אלא יוד\"ך בחי' יו\"ד, והוא בחי' יו\"ד דיהוד\"ה שהוא בחי' יו\"ד דשם הוי' בחי' סוכ\"ע הנ\"ל",[["1672","85","<b>והנה\"ב. . משם ג\"כ נמשכה</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תצד. וש\"נ."],["1673","86","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["1674","87","<b>וירא ישראל את היד הגדולה</b>: בשלח יד, לא. ראה מאמרי אדה\"א דברים ח\"ד ע' א'שלח. וש\"נ."],["1675","88","<b>וימינך פשוטה לקבל שבים</b>: תפלת נעילה. ראה מאמרי אדה\"ז מארז\"ל ע' רפז וע' תכז. אמרי בינה שער הק\"ש עג, ג. מאמרי אדה\"א דברים ח\"ד ע' א'שצג."],["1676","89","<b>כחשיכה כאורה. . וגם חשך לא יחשיך</b>: תהלים קלט, יב [ושם: גם. אבל כ\"ה בכ\"מ — ראה מאמרי אדה\"א דברים ח\"ג ע' תתצב. וש\"נ]."],["1677","90","<b>שוה ומשוה קטן וגדול</b>: ע\"פ פיוט (לימים נוראים) ”האוחז ביד משפט\"."],["1678","91","<b>קטן וגדול שם הוא</b>: איוב ג, יט."],["1679","92","<b>החכ' שנק' ראשית</b>: תהלים קיא, י. ראה זהר בראשית לט, ריש ע\"ב. מאמרי אדה\"א דברים ח\"א ע' רלד. וש\"נ. וראה גם פלח הרמון ר\"פ בראשית."],["1680","93","<b>כולם בחכ' עשית</b>: תהלים קד, כד. ראה מאמרי אדה\"א ח\"ד ע' א'רפה. וש\"נ."],["1681","94","<b>כחשיכה כאורה שהחושך כאור</b>: ראה לקוטי תורה צו יב, א, ומקבילו בסידור סדר הגדה רצז, רע\"ג."],["1682","95","<b>לך ה' הגדולה והגבורה</b>: דברי הימים-א כט, יא."],["1683","96","<b>אם אסק שמים. . אציע שאול הנך</b>: תהלים קלט, ח [ושם: ואציעה]."],["1684","97","<b>וא\"ת ידך אלא יוד\"ך</b>: ראה תקוני זהר בהקדמה ז, ב."]]],[2100490343,"לפי שיודוך אחיך עד שהוא למעלה גם מבחי' היחוד בחי' לוי כנ\"ל ואזי יו\"ד דיהוד\"ה יכול להתפשט עד אין שיעור למטה עד שיהפוך גם בחי' עורף לקדושה מטעם הנ\"ל וד\"ל.\n<b>ישתחוו</b> לך בני אביך. הנה כתי' שמע<sup data-n=\"1685\">98</sup> בני מוסר אביך ואל תטש תורת אמך, וידוע בדרז\"ל דמוסר אביך נק' תושב\"כ ותורת אמך נק' תושבע\"פ, וי\"ל הטעם לזה למה תושב\"כ בשם אב ותושבע\"פ בשם אם. אך הענין הוא פשוט עד\"מ<sup data-n=\"1686\">99</sup> אב ואם גשמיי' [שהטפה] הנמשכת מן האב אעפ\"י שהוא כח המוליד הולד עכ\"ז אין הולד נוצר ממנו אלא מן טפת האודם שבאם שמצייר הולד בצורת אברים בהגדלה רבה ראש ויד ורגל והולך ומתגדל בבטן האם בט\"ח עד שנעשה ברי' גדולה, ובטיפת האב לא הי' הולד הזה רק בבחי' כח היולי כו' כידוע. והנמשל מזה יובן ג\"כ בהפרש שבין תושב\"כ ותושבע\"פ שאעפ\"י שעיקר ההשפעה מאא\"ס ב\"ה הוא בתושב\"כ כידוע דאורייתא<sup data-n=\"1687\">100</sup> מח\"ע נפקת והתלבשות<sup data-n=\"1688\">101</sup> אא\"ס אינו אלא בחכ', מ\"מ אין גודל אור ההשפעה לאורך ורוחב כמו בציור ולד וכיוצא אלא דוקא בתושבע\"פ לפי שהיא מפרשת באר היטיב כל דין ודין איך הוא ומה הוא ומתגדל באורך ורוחב, וכמו שיש מסכת<sup data-n=\"1689\">102</sup> שלימה בדיני סוכה ע\"פ א' בסוכות תשבו ז' ימים וכיוצא, וז\"ש ששים<sup data-n=\"1690\">103</sup> המה מלכות ושמונים פלגשים כו' ס' מלכות הן ס' מסכתות ופ'<sup data-n=\"1691\">104</sup> פלגשים הן ברייתות כו' כידוע, וכ\"ז בתושבע\"פ, וזהו שנק' תורת אמך עד\"מ האם שמגדלת הולד בבטנה כו' כנ\"ל וד\"ל.\n<b>וזהו</b> ישתחוו לך בני אביך, פי' אביך הוא בחי' תושב\"כ שהוא בחי' אור אבא עד\"מ הנ\"ל, ונק' אבינו<sup data-n=\"1692\">105</sup> אב הרחמן כו' מפני שמקור כל החסדי' מן האב דוקא לפי שהחכ' הוא מקור כל החסדים ומקור כל הרחמים כידוע, וע\"כ בחי' בני אביך דוקא הוא שממשיכים את ההשפעה למטה והוא תורה וגמ\"ח כנ\"ל בפי' יודוך אחיך ולוי הוא העיקר כו', ומשום שה'<sup data-n=\"1693\">106</sup> בחכ' יסד ארץ דהיינו ענין אבא<sup data-n=\"1694\">107</sup> יסד",[["1685","98","<b>שמע בני מוסר אביך. . תושבע\"פ</b>: משלי א, ח. מאמרי אדה\"א ח\"ד ע' א' תנ בשם הזוהר. וש\"נ."],["1686","99","<b>עד\"מ אב ואם גשמיי'</b>: ראה מאמרי אדה\"א מקץ ע' שה. ובהנסמן שם."],["1687","100","<b>דאורייתא מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. (רעיא מהימנא) משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["1688","101","<b>והתלבשות אא\"ס. . בחכ'</b>: ראה תניא פי\"ח. פל\"ה בהג\"ה. סידור ערב שבת קסה, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרכא."],["1689","102","<b>מסכת שלימה. . בסוכות תשבו</b>: אמור כג, מב. מאמרי אדה\"א דברים ח\"ד ע' א'תכז."],["1690","103","<b>ששים המה מלכות. . ס' מסכתות</b>: שיר השירים ו, ח. ראה זהר פינחס רטז, א. מאמרי אדה\"ז פרשיות התורה ח\"א ע' שעח ובהנסמן לשם. מאמרי אדה\"א דברים ח\"ב ע' תד. וש\"נ."],["1691","104","<b>ופ' פלגשים הן ברייתות</b>: ראה מאמרי אדה\"א דברים ח\"ד שם. וש\"נ."],["1692","105","<b>אבינו אב הרחמן</b>: ברכת אהבת עולם. ראה ביאורי הזהר במדבר קמה, ב. מאמרי אדה\"א דברים ח\"א ס\"ע רלז. וש\"נ."],["1693","106","<b>שה' בחכ' יסד ארץ</b>: משלי ג, יט. ראה מאמרי אדה\"ז פרשיות התורה ח\"א ע' לג."],["1694","107","<b>אבא יסד ברתא</b>: ראה זהר (רעיא מהימנא) פינחס רנו, ב. רמח, א. רנח, א. ראה מאמרי אדהא דברים ח\"ב ע' שפז. וש\"נ. ח\"ג ע' תתקנח. במדבר ח\"ג ע' תתקעח וע' א'קסח. ספר המאמרים תקס\"ה ח\"ב ע' תקצג."]]],[2100490344,"ברתא דוקא כמ\"ש במ\"א ע\"כ ישתחוו לך פי' שבני אביך ממשיכים בשבילך דוקא, כי יהודה<sup data-n=\"1695\">108</sup> הוא בחי' המל'<sup data-n=\"1696\">109</sup> שהוא עולם הדבור ומקבלת מאחיך בתחלה ואח\"כ הוא שמתעלה המל' מהם כנ\"ל. וזהו פי' ישתחוו לשון זה הוא ענין ההשפעה מלמעלמ\"ט דוקא, והוא מפני שב' מיני השתחוואו' יש, הא' השתחוואה מלמטלמ\"ע שהמשתחווה למטה בארץ בפישוט ידים ורגלים לפני מי שמשתחווה אליו כו', והב' השתחוואה מלמעלמ\"ט כאדם שמרכין ראשו שכופף קומתו לגבי מי שמתחנן לו דבר כו' ובהרכנה זו ממשיך לו השפע והברכה, והוא ענין הודאה מלמעלמ\"ט (וז\"ש ששם<sup data-n=\"1697\">110</sup> עלו שבטים כו' להודות לשם הוי' כו'), וזהו פי' יודוך אחיך מלמעלמ\"ט להמשיך לך הברכה והשפע, והיינו ג\"כ ענין ישתחוו לך בני אביך בחי' השתחוואה מלמעלה דרך כריעה, וזהו ענין הכורע<sup data-n=\"1698\">111</sup> כורע בברוך כו', והוא ענין הכריעות והשתחוואות שבש\"ע שהוא בחי' ח\"י המשכות עליונות משמות דהוי' דג' מדרגות הנ\"ל בכלל בג\"ר וג' אחרונות כו' (וממילא יש ג\"כ בחי' השתחוואה מלמטה למעלה מבני אביך לפי שהמל' עולה עד הכתר למעלה מבחי' אחיך הנ\"ל ע\"כ הם משתחווים לפני בחי' יהודה כי יהודה עולה בבחי' כתר מל' כנ\"ל וד\"ל). ופי' בני אביך הן ראובן ולוי בלבד, כי שמעון הוא בחי' שמאלו תחת לראשי בלבד אבל ראובן ולוי הן בחי' החסדים שיורדי' מגבוה לנמוך לבחי' מל' כמ\"ש כל<sup data-n=\"1699\">112</sup> הנחלים הולכים אל הים כו' ושרשם של לוי וראובן הוא בחי' אבינו אב הרחמן דהיינו אא\"ס שמלובש בחכ' שבתו' שבכתב כמ\"ש שמע בני מוסר אביך כנ\"ל הטעם וד\"ל.\n<b>והמשך</b> דברי הפסוק ידך בעורף אויביך ישתחוו לך בני אביך הוא ענין קשר דברים ששייך ענינם זל\"ז, דהיינו שנותן טעם למה שידך בעורף אויביך שהוא לפי שישתחוו לך בני אביך כו', לפי שההשתחוואה זו באה מבחי' אא\"ס שבחכ' דקמי' כחשיכה כאורה כו' ויכול להיות ג\"כ מחמת זה שיהפוך האויב ערפו לנוס כפשט הכתוב דידך בעורף אויביך והוא ענין מה שאנו רואי' שלפרקי' יהי' האדם סומ\"ר מחמת שהרע אין לו מקום אחיזה אצלו כלל והוא מושלל ומרוחק ממנו הרבה וכ\"ז מפני שהאויב יהפוך ערפו לנוס מסט' דקדושה וכמ\"ש אחד<sup data-n=\"1700\">113</sup> ירדוף אלף כו', וכמ\"כ למעלה ברוחני' כתי' יפול<sup data-n=\"1701\">114</sup> מצדך אלף ורבבה מימינך כו' וד\"ל, והוא מפני",[["1695","108","<b>יהודה הוא בחי' המל'</b>: ראה זהר ויחי רלז, א. (סבא) משפטים קג, ב. קד, א. ובאור החמה ומקדש מלך שם. מאורי אור מערכת יהודה ס\"ו."],["1696","109","<b>המל'. . שהוא עולם הדיבור</b>: ראה זהר לך פו, ב. ובאור החמה ורמ\"ז שם. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["1697","110","<b>ששם עלו שבטים. . להודות</b>: תהלים קכב, ד."],["1698","111","<b>הכורע כורע כברוך</b>: ראה ברכות יב, ע\"א."],["1699","112","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז. ראה פרדס שער (כג) ערכי הכינויים מערכת ים. מאמרי אדה\"א ויקרא ח\"א ע' שצז. וש\"נ."],["1700","113","<b>אחד ירדוף אלף</b>: יהושע כג, י [ושם: אחד מכם]."],["1701","114","<b>יפול מצדך אלף</b>: תהלים צב, ז."]]],[2100490345,"שהיו\"ד שבחכ' למעלה מבחי' שבירה וכמ\"ש ימותו<sup data-n=\"1702\">115</sup> ולא בחכ' כו' ע\"כ אין להם מקום שם כלל, וזהו ידך בעורף כו' יודך כו', והוא ענין א' עם ישתחוו לך בני אביך כנ\"ל וד\"ל.",[["1702","115","<b>ימותו ולא בחכ'</b>: איוב ד, כא. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רצט."]]],[2100490346,"<h3>להבין שרש הדברים הנ\"ל</h3>\n<b>ביאור על תורה הנ\"ל</b>\n<b>להבין</b><sup data-n=\"1703\">1</sup> שרש הדברים הנ\"ל, הנה להבין שרש ענין ראובן ושמעון ולוי הנ\"ל שהוא ענין ב' פ' דק\"ש ואמוי\"צ כנ\"ל, הנה תחלה י\"ל שרש ענין השבטים מה הן. כתי' ששם<sup data-n=\"1704\">2</sup> עלו שבטים שבטי י\"ה עדות לישראל להודות לשם הוי' כו', פי' שבטי י\"ה הן בחי' השבטים העליוני' שבבחי' האצי' ונק' שבטי י\"ה לפי ששרשם מבחי' מוחין דאו\"א שמלובשים בז\"א שנק' י\"ה והוא י\"ה שבשם הוי' דז\"א כו' כידוע, ואותם השבטים העליוני' [הם] מבחי' עלמא דדכורא דהיינו שמשפיעי' מלמעלמ\"ט, וזהו להודות לשם הוי' פי' לעשות שם הוי' בבחי' הודאה שיהי' נק' בחי' יהודא, והוא ענין הנ\"ל בפי' יודוך אחיך מלמעלמ\"ט בבחי' אתעדל\"ע כו'. ויש עוד שבטים שהן בבחי' עלמא דנוק' דהיינו בבחי' מל' דאצי', והוא שרש בחי' המרכבה דפני ארי' כו', ונק' בשם י\"ב<sup data-n=\"1705\">3</sup> ג\"א בפרד\"ס בל' הגאוני' ובזוהר<sup data-n=\"1706\">4</sup> פ' פקודי נק' בשם ד' מחנות שכינה העליוני' והן ד' דגלי' דגל מחנה ראובן לסט' דדרום כו', והשבטים הללו המה בבחי' מקבלי' והן עולין למעלה לקבל והוא בבחי' העלאת מ\"נ הנק' אתעדל\"ת כנ\"ל, ובאתעדל\"ת שלהם נעשה אתעדל\"ע למעלה בבחי' מ\"ד בבחי' שבטים העליוני' שבבחי' האצי' שמסתעפים מז\"א, והוא מ\"ש ששם עלו שבטים שבטי י\"ה להודות לשם הוי' להשפיע מלמעלמ\"ט בשבטים בתחתוני' שבעלמ' דנוק' כו' וד\"ל.\n<b>וביאור</b> הדברים הללו למעלה הוא עפ\"י הנ\"ל בעבודת ה' בענין ראובן ושמעון ולוי כנ\"ל, אך צריך לבארם יותר בתוס' ביאור. דהנה בחי' שבט ראובן שבעלמא דנוק' למעלה יובן ע\"ד דוגמא מבחי' ראובן למטה בעבודת ה', כמו שיש אתעדל\"ת באדם להתקרב לה' בדביקה וחשיקה בבחי' ראי' לאסתכלא<sup data-n=\"1707\">5</sup> ביקרא",[["1703","1","<b>להבין שרש הדברים</b>: ביאור זה מיוסד על הביאור בתורה אור ר\"פ ויחי מה, ד. ובשינויים קלים באור התורה ויחי כרך ו ע' 2280."],["1704","2","<b>ששם עלו שבטי'</b>: תהלים קכב, ד. ראה זהר פקודי רכט, ב. רל, א. ביאורי הזהר במדבר פה, ריש ע\"ד. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תמ. במדבר ח\"ג ע' תתקנד."],["1705","3","<b>י\"ב ג\"א בפרד\"ס בל' הגאוני'</b>: [ספר יצירה פ\"ה מ\"א. ספר הבהיר סמ\"ב [צה]. ונמנו בפרדס] שער (כא) פרטי השמות פ\"ו-ח."],["1706","4","<b>ובזהר פ' פקודי</b>: נסמן לעיל בהמאמר."],["1707","5","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."]]],[2100490347,"דמלכא כו', כך יש למעלה בעולמות העליוני' בחי' העלאת מ\"נ כזה ברבוא רבבות מלאכים ונשמות עליוני' דלסט' דדרום בד' מחנות שכינה ונק' דגל מחנה ראובן כו' שכולם עולים למעלה בבחי' התדבקות והתקרבות בבחי' ראי' מקרוב כנ\"ל, וה\"ז נמשל לשבט כמו שהשבט ענף האילן וענפיו הרי עולין מלמטלמ\"ע, כך הדוגמא בשבט ראובן וכל ההוא סט' דדרום שהן עולין כשבט. וזהו ששם עלו שבטים דהיינו שבטים שבבחי' עלמא דנוק' שעולין בהעלאת מ\"נ כו', ואח\"כ ממשיכים בזה המשכת מ\"ד מבחי' שבטים שבעלמא דדכורא והוא הנק' אתעדל\"ע כנ\"ל והם נק' שבטי י\"ה שמשפיעי' מלמעלמ\"ט. והנה כמו שמבואר למעלה בעבודת ה' דרוח<sup data-n=\"1708\">6</sup> אייתי רוח ואמשיך רוח וכמ\"ש אם ישים אליו לבו כו', כך למעלה נמשך עי\"ז אתעדל\"ע ג\"כ מבחי' שבט ראובן שבעלמא דדכורא, ובחי' שבט ראובן שבאצי' היינו ג\"כ בחי' ראי' מקרוב בדביקות וחשיקה אך שהוא ענין הראי' וההבטה מלמעלמ\"ט להיותם בחי' משפיעים וממשיכים מלמעלמ\"ט, והוא מ\"ש כבכורה<sup data-n=\"1709\">7</sup> בתאנה כו' ראיתי את אבותיכם כו' כלומר חשקתי בהם ע\"י ראי' והסתכלו' שבאה מצד האהבה מקרוב דוקא כנ\"ל. והוא מ\"ש בראובן כי<sup data-n=\"1710\">8</sup> עתה יאהבני אישי שהוא בחי' ז\"א דאצי' שנק' אישי וע\"י שמסתעף ממנו ראובן העליון שהוא בחי' ראי' מקרוב וכמ\"ש ראיתי את אבותיכם כו'. וזהו מ\"ש וימינו תחבקני וד\"ל.\n<b>ומה</b> שאמרה עוד כי ראה<sup data-n=\"1711\">9</sup> ה' בעניי כו' הוא מפני שענין התשובה הוא ענין הברורי' כידוע שהברורי' הוא מרפ\"ח ניצוצי' שנפלו למטה ועולי' למעלה כו', והוא ענין התשובה למטה בנפש האדם שישוב ויקבץ ממה שנתפזרו ניצוצי נפשו בק\"נ כו', ולמעלה נק' תשוב<sup data-n=\"1712\">10</sup> ה' תתאה דהיינו בחי' המל'<sup data-n=\"1713\">11</sup> הנק' ה\"א תתאה שירדה בהיכלות דנוגה וכאשר שם ב\"נ זה הוא העולה משם למעלה בבחי' אצי', ולהיות כי הוא בא ממקום רחוק שנתרחק נק' רא\"ו ב\"ן כי מפני שנתקרב מן הריחוק הרי תגדל האהבה והשמחה להיותו תחלה בבחי' קירוב ונתרחק ע\"כ יוכפל אור האהבה כשחוזר ומתקרב אחר שהי' תחלה במקום גבוה וירד כשחוזר ועולה למקור חוצבו בתחלה תגדל האהבה, וע\"כ בע\"ת גדולי' גם מצ\"ג כנודע וד\"ל. וזהו שאמרה כי ראה ה' בעניי כשירדה המל' למטה ע\"כ כשחוזרת ועולה להתדבק בבחי' ראי' ונק' ראובן תגדל האהבה עד שאמרה עתה יאהבני אישי דוקא בכפלי כפליים מבראשונה כנ\"ל וד\"ל (והוא הנק' בחי' חולת<sup data-n=\"1714\">12</sup> אהבה בגלותא כמ\"ש בזוהר ע\"פ רשפי' רשפי אש כו' בגלותא דוקא דמוקדי' לי' בשלהובא דרחימותא, והוא מטעם הנ\"ל שהקירוב בא אחר הריחוק כו' וכמ\"ש במ\"א וד\"ל).",[["1708","6","<b>דרוח אייתי רוח. . אם ישים אליו לבו</b>: נסמן לעיל בהמאמר."],["1709","7","<b>כבכורה בתאנה</b>: נסמן לעיל בהמאמר."],["1710","8","<b>כי עתה יאהבני אישי. . וימינו תחבקני</b>: ויצא כט, לב. שיר השירים ב, ו."],["1711","9","<b>כי ראה ה' בעניי</b>: התחלת הכתוב דכי עתה יאהבני."],["1712","10","<b>תשוב ה' תתאה</b>: ראה זהר (רעיא מהימנא) נשא קכב, א. מאמרי אדה\"א דברים ח\"ד ע' א'קסד. וש\"נ."],["1713","11","<b>המל' הנק' ה\"א</b>: ראה פרדס שער (כז) האותיות פ\"ח."],["1714","12","<b>חולת אהבה. . רשפי'. . דמוקדי' לי'</b>: נסמן לעיל בהמאמר."]]],[2100490348,"<b>וכ\"ז</b> בחי' ראובן למעלה באצי', אבל בחי' שמעון שבעלמא דדכורא הוא מ\"ש כי<sup data-n=\"1715\">13</sup> שמע הוי' כו', ושמיעה זו למעלה מרחוק ע\"ד השמיעה למטה באדם התחתון שאנו רואים בחוש שישמע האדם יותר מרחוק משיעור שיכול לראות מרחוק שהרי הראי'<sup data-n=\"1716\">14</sup> לא תתפשט יותר מת\"ק אמה ע\"ד דוגמא והשמיעה יכול להיות גם ממקום הרחוק יותר מאלף אמה כידוע שיכולים לשמוע קול מרחוק חצי פרסה ג\"כ, ואעפ\"י שכח הראי' חזקה יותר מכח השמיעה במה שיש בה חיות יותר כידוע מהסתכלות<sup data-n=\"1717\">15</sup> בת היענה כו', אבל בענין המרחק יותר גדול כח השמיעה ששומע מרחוק יותר כו', וע\"כ בראי' הוא ענין קירוב ודיבוק למעלה ובשמיעה הוא ענין ריחוק דוקא. וזהו שאמר חבקוק שמעתי<sup data-n=\"1718\">16</sup> שמעך יראתי לפי שהשמיעה מרחוק כנ\"ל ע\"כ תפול היראה שהוא בחי' שוב, כענין וירא העם וינועו ויעמדו מרחוק כו' כי יראו לגשת כו' כנ\"ל באריכות. וענין זה הריחוק למטה הוא בשבט שמעון דבעלמא דנוק', והיינו מה שאמרה כי<sup data-n=\"1719\">17</sup> שנואה אנכי שהוא בחי' שמאל דוחה הנ\"ל ומזה נולד אתעדל\"ע בבחי' שבט שמעון שבאצי' ג\"כ בבחי' שמיעה מרחוק. והיינו כי שמע ה' כי שנואה אנכי, פי' כי שמיעה ששומע הוי' הרי הוא מלמעלמ\"ט דהיינו ששומע בחי' קול התחתון והוא השמיעה ממרחק גדול מאד והיינו מפני ששנואה אנכי והשפילה א\"ע בתכלית למטה כו', אך מפני שהשמיעה למעלה יכול להיות גם ממרחק גדול ע\"כ אמרה כי שמע ה' כי שנואה אנכי כו' וגם אמרה כמו טעם שמפני ששמע ה' כי שנואה אנכי ע\"כ מזה נתעורר בבחי' קירוב, והוא ענין שמאלו<sup data-n=\"1720\">18</sup> תחת לראשי הנ\"ל שהוא ענין קירוב שבא מפני שהמקבל משפיל א\"ע ביותר שמזה נולד בחי' התקרבות דוקא, והוא עד\"מ שאדם יקרב ויאהב לבנו ששפל בעיניו ודומה לו שמאוס ושנאוי בעיני אביו כו' שמפני שפלותו זאת יתעורר האהבה הפנימי' שהיתה מוסתר בלב אביו ותתגלה כנ\"ל וד\"ל (ומ\"ש כי שנואה אנכי אין ר\"ל שנואה ממש אלא לגבי אהבה שאהב את רחל נק' שנואה כמו ויאהב<sup data-n=\"1721\">19</sup> גם את רחל מלאה כו', ולמעלה הוא בחי' עלמדאתכ\"ס שמפני הריחוק אין האהבה מורגשת שם כו' וד\"ל).\n<b>ואחר</b> שנסתעפו בחי' ראובן ושמעון למעלה באצי' בבחי' ראי' ושמיעה הנ\"ל שהן שמאלא וימינא דז\"א דאצי' כנ\"ל אז נולד ממילא בחי' לוי שבאצי', והוא הנק' בחי' גופא דמלכא, כי הנה ידוע<sup data-n=\"1722\">20</sup> בפרד\"ס שנחלק כל העולם דאצי' בדרך כלל",[["1715","13","<b>כי שמע הוי'</b>: ויצא כט, לג."],["1716","14","<b>הראי'. . מת\"ק אמה</b>: ראה מאמרי אדה\"ז פרשיות התורה ח\"ב ע' תשא ובהנסמן במראי מקומות לשם. ספר המאמרים תרס\"ב ע' רנב."],["1717","15","<b>מהסתכלות בת היענה</b>: ראה עץ חיים שער (ח) דרושי הנקודות פ\"א. ראה גם מאמרי אדה\"ז פרשיות התורה ח\"א ריש ע' קא. ח\"ב ס\"ע תשעז. המשך תער\"ב ח\"ג ע' א'ת."],["1718","16","<b>שמעתי שמעתך יראתי. . וירא העם וינועו</b>: חבקוק ג, ב. יתרו כ, טו."],["1719","17","<b>כי שנואה אנכי</b>: המשך הכתוב כי שמע ה'."],["1720","18","<b>שמאלו תחת לראשי</b>: התחלת הכתוב וימינו תחבקני."],["1721","19","<b>ויאהב גם את רחל מלאה</b>: ויצא כט, ל."],["1722","20","<b>ידוע בפרד\"ס. . לג' קווין</b>: נסמן לעיל בהמאמר."]]],[2100490349,"לג' קוין חח\"נ מימין ובג\"ה משמאל וקו האמצעי הוא בחי' דת\"י כו' והוא הנק'<sup data-n=\"1723\">21</sup> בזוהר ור\"מ גוף וברית ונק' בכלל גופא דמלכא, וזהו בחי' לוי כמ\"ש כי<sup data-n=\"1724\">22</sup> עתה הפעם ילוה אישי אלי כו'. וביאור הדברים, כי הנה בחי' ראובן ושמעון דז\"א דאצי' הן בחי' ב' קוין הנ\"ל דהיינו קו הימין חח\"נ לראובן וקו השמאל בג\"ה לשמעון ומהם נולד ענין אתעדל\"ע הנ\"ל שיהי' שמאלו תחת לראשי וימינו תחבקני כו' וכנ\"ל, ואח\"כ נעשה גוף היחוד והוא חיבור קו האמצעי שנק' גופא דמלכא והוא בחי' דת\"י שהוא בחי' לוי כו'. וזהו באמת ויציב דוקא, והטעם הוא לפי שבאמת<sup data-n=\"1725\">23</sup> ויציב הוא בחי' היכל הרצון, כי בק\"ש<sup data-n=\"1726\">24</sup> הי' רק הכנה ליחוד כנ\"ל והוא בבחי' היכל האהבה ועיקר בפסוק ואהבת שכולל בחי' רו\"ש דהיינו כללות ענין ראובן ושמעון הנ\"ל, ואחר כך באמת ויציב שאחר ק\"ש מתחיל להיות גוף היחוד, והוא מ\"ש כי ילוה אלי אישי, פי' שהמשפיע חפצו ורצונו להתייחד כי פי' ילוה ל' להבא הוא וד\"ל, עתה ודאי יהי' רצונו ותשוקתו להתלוות אלי בבחי' יחוד ממש, והוא הנק' היכל הרצון כו' וד\"ל. וזהו בחי' ט\"ו<sup data-n=\"1727\">25</sup> ווי\"ן שהן הן ה' פעמי' ג' פרקין דנה\"י כו' ע\"ש שיסוד ז\"א שכלול מה' פרצופים וידוע שהוי\"ו<sup data-n=\"1728\">26</sup> מורה ירידת אור השפע מן המשפיע למקבל וראשו מתחיל מן הדעת דא\"א כו' וסופו מסתיים בבחי' מל' כו', וסיבת התחברות הזאת באה ממילא באמת ויציב מטעם הנ\"ל וד\"ל. וזהו שבאמת ויציב או' על הראשוני' ועל האחרוני' כו' ראשוני' או\"א אחרוני' זו\"נ כו' לפי שכולל הכל מראש לסוף כנ\"ל וד\"ל, וזהו ענין ודבריו חיים וקיימים כו' על אבותינו ועלינו ועל בנינו כו' אבותינו או\"א ועלינו זו\"נ ובנינו נ\"ה כו' והכל מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> שרש ענין יהודה אתה יודוך אחיך כו', פי' יודוך אחיך הן ראובן ושמעון ולוי שבבחי' ז\"א דאצי' שדרך כלל הן בחי' ג' קוין העליוני' הנ\"ל חח\"נ בג\"ה דת\"י שכולם משפיעים המה לבחי' יהודה<sup data-n=\"1729\">27</sup> שהוא בחי' המל' כידוע וכנ\"ל, וזהו יודוך כמ\"ש להודות לשם הוי' ומטעם שהמה בחי' השבטי' העליוני' שהוא בחי' אתעדל\"ע כנ\"ל. והנה ענין סדר ההשפעה מג' קוין הללו הוא בא ונמשך במל' ע\"י ק\"ש ואמת ויציב בבחי' ההתכללות. דבפ' ראשונה נמשך מבחי' קו הימין חח\"ן כנ\"ל, והוא בתיבת ואהבת שהאהבה הוא בחי' קו החסד כידוע ע\"פ אהבת<sup data-n=\"1730\">28</sup> עולם אהבתיך ע\"כ משכתיך חסד כו'. והנה ידוע דב'<sup data-n=\"1731\">29</sup> פרשיו' קדש והי' כי יביאך הן חו\"ב וב' פרשיו'",[["1723","21","<b>הנק' בזהר ור\"מ גוף וברית</b>: ראה זהר (רעיא מהימנא) פינחס רכג, ב. רלו, א. תצא רמט, א. רפג, א."],["1724","22","<b>כי עתה הפעם ילוה אישי אלי</b>: ויצא כט, לד [בהוספת תיבת ”כי\"]."],["1725","23","<b>שבאמת ויציב. . היכל הרצון</b>: ראה פרי עץ חיים שער (ז) הק\"ש פכ\"ז. מאמרי אדה\"א דברים ח\"ב ע' תז. וש\"נ."],["1726","24","<b>בק\"ש. . היכל האהבה</b>: ראה פרי עץ חיים שם פ\"ד. מאמרי אדה\"א שם ע' תו. וש\"נ."],["1727","25","<b>ט\"ו ווי\"ן</b>: נסמן לעיל בהמאמר."],["1728","26","<b>שהוי\"ו מורה ירידת אור השפע</b>: ראה אגרת התשובה פ\"ד."],["1729","27","<b>יהודה שהוא בחי' המל'</b>: נסמן לעיל בהמאמר."],["1730","28","<b>אהבת עולם אהבתיך</b>: נסמן לעיל בהמאמר."],["1731","29","<b>דב' פרשיו'. . חו\"ב. . חו\"ג</b>: ראה זהר (רעיא מהימנא) בא מג, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'רמא."]]],[2100490350,"דשמע וא\"ש הן בחי' חו\"ג, ובכלל הן ד' מוחין דז\"א בתפילין שבראש כו' וכמבואר במ\"א. והנה מפני שצריך כאן לבחי' יחוד משפיע במקבל כנ\"ל ע\"כ צריך שיהי' בחי' ההתכלות מקו הימין לקו השמאל ומקו השמאל לקו הימין וכמ\"ש יקוו<sup data-n=\"1732\">30</sup> המים שר\"ל שיתחברו הקוין מזה לזה ע\"י צינורות המחברים אותם כמבואר בפרד\"ס פרטי הצינורות כו'. וענין כללות ההתכללות ביניהם הוא מה שמבואר במ\"א שפ'<sup data-n=\"1733\">31</sup> ראשונה הכוונה בשם מ\"ב והוא מבחי' אור הגבו' כידוע דשם מ\"ב הוא המעלה כל ההעלאות וזהו ענין מ\"ב תיבות בפ' זו אך הכלי הוא בחי' חסד וכמ\"ש שם ביאור הדברים באריכות, ובפ' שניי' וא\"ש הוא בהיפוך שהכוונה שם בשם ע\"ב דחסד והכלי בחי' הגבו' כמ\"ש וחרה<sup data-n=\"1734\">32</sup> אף כו', ועי\"ז הוחלפו האורות ונתכללו גבו' בחסדי' וחסדי' בגבו', וה\"ז ענין לאכללא<sup data-n=\"1735\">33</sup> שמאלא בימינא וימינא בשמאלא כידוע, ועי\"ז יכול להיות נולד מזה בחי' הממוצע הכלול משניהם יחד והוא בחי' קו האמצעי דת\"י שהוא בחי' לוי באמת ויציב ששם הוא היכל הרצון כנ\"ל וד\"ל. וזהו יודוך אחיך בבחי' ההתכלות דוקא מטעם שצריך שיהי' בחי' יחוד מקו האמצעי דוקא כידוע.\n<b>והנה</b> מה שאמר יהודה אתה כו' שרצונו בזה שאחיך הנ\"ל עשאוהו להיות נק' דוקא יהודה כנ\"ל הנה שרש לזה הענין יובן בהקדים תחלה שרש בחי' יהודה מהו. דהנה ידוע דההיכל היותר עליון הוא היכל<sup data-n=\"1736\">34</sup> ק\"ק שבסמיכות גאולה לתפלה באמרו אד'<sup data-n=\"1737\">35</sup> שפתי תפתח כו' לפי ששם עיקר שלימות היחוד, והוא שהמשפיע יורד לשם והמקבל כבר עלה לשם ומתייחדים, עד\"מ העולה במעלות שפוגע את היורד במעלות מלמעלמ\"ט ומתחברים באמצע כשפוגעים זב\"ז, כך באמת ויציב המשפיע יורד במעלות עד\"מ כמ\"ש כי ילוה אלי אישי לשון להבא כו' ובסמיכות גאולה לתפלה הוא שכבר ירד בהיכל ק\"ק והמל' שהוא בחי' מקבל כבר עלתה לשם, והוא ענין גאולה לתפלה שהוא בחי' יסוד ומל' כידוע, וע\"כ היכל הזה נק' היכל ק\"ק לפי שמל' דאצי' שם בתכלית העלוי שאין עוד עלי' יותר לכך הוא למעלה מהיכל הרצון שבאמת ויציב כו' (וגם מצד המשפיע אעפ\"י שבהיכל ק\"ק ירד יותר בירידת המדריגה מ\"מ מצד היחוד הרי שם הוא ביותר עלוי כו').\n<b>והנה</b> בעלות המל' לשם אזי נק' יהוד' כמ\"ש הפעם אודה את הוי', והוא בצלותא<sup data-n=\"1738\">36</sup> שהיא בלחש ובחשאי דוקא. כי הנה בהתקרב אליה אור השפע באה לבחי'",[["1732","30","<b>יקוו המים. . כמבואר בפרד\"ס</b>: בראשית א, ט. ראה שם שער (ז) הצנורות."],["1733","31","<b>שפ' ראשונה. . אור הגבו'</b>: ראה מאמרי אדה\"ז פרשיות התורה ח\"ב ע' תשח ואילך ובהנסמן לשם."],["1734","32","<b>וחרה אף</b>: עקב יא, יז."],["1735","33","<b>לאכללא שמאלא בימינא</b>: במאמרי אדה\"א בראשית ע' דש: בזוהר פ' קרח. בלקוטי תורה מטות פו, ב מציין לזהר ר\"פ קרח. ראה לקו\"ת ואתחנן ז, ד. ובהנסמן במראי מקומות להנ\"ל. תורת חיים נח עב, א."],["1736","34","<b>היכל ק\"ק שבסמיכות גאולה לתפלה</b>: ראה בזה (ובהבא לקמן) סידור האריז\"ל במקומו. מאמרי אדה\"א ויקרא ח\"ב ע' תתז. וש\"נ. דברים ח\"ג ע' א'מ. וש\"נ."],["1737","35","<b>אד' שפתי תפתח</b>: תהלים נא, יז."],["1738","36","<b>בצלותא שהיא בלחש ובחשאי</b>: נסמן לעיל בהמאמר."]]],[2100490351,"ביטול המציאות מכל וכל ואזי היא בבחי' שתיקה לגמרי וכמ\"ש ותעמוד<sup data-n=\"1739\">37</sup> מלדת וידוע דכל עמידה הוא ענין שתיקה שמפני עוצם הביטול וכמארז\"ל אין<sup data-n=\"1740\">38</sup> עמידה אלא שתיקה כו', כך ענין העמידה בש\"ע בלחש הוא מפני עוצם בחי' הביטול שלמעלה מבחי' התפעלות אוי\"ר, כי קודם היחוד כתי' ואל<sup data-n=\"1741\">39</sup> אישך תשוקתך כו' והוא בחי' רו\"ש מלמטלמ\"ע כנ\"ל בבחי' ראובן ושמעון שבעלמא דנוק' באתעדל\"ת כו', אבל בש\"ע שכבר עלתה המל' בתכלית הקירוב להתדבק בבעלה ממש אזי למעלה היא מבחי' התפעלות לגמרי כי כל בחי' התפעלות אינה אלא מרחוק דוקא כידוע, וזהו ותעמוד מלדת פי' מלדת עוד תולדות שהן אוי\"ר וענפיהן כו', כי אהבה<sup data-n=\"1742\">40</sup> הוא בחי' יש ודבר מ\"ה כידוע ובש\"ע הוא בחי' אין בתכלית כו', וכ\"ז הוא מפני שהמל' מקבלת אז מקו האמצעי הכולל כל הקווין יחד, והג' קווין הנ\"ל הנה ידוע שעיקר מקור שרשם הוא בחי' כתר<sup data-n=\"1743\">41</sup> עליון הנק' עילת העילות שהוא למעלה מג' הקוין כידוע בצורת האילן<sup data-n=\"1744\">42</sup> כו' והג' קוין אינם אלא כמו צינורות בלבד שנמשכים מאור הכתר לכאן ולכאן לימין ולשמאל ולאמצע כו', וא\"כ כשהג' קוין כולם מתחברים ומשפיעים במל' בשעת עמידה דש\"ע אזי עיקר ההארה שמאיר במל' הוא מבחי' אור הכתר אך שנתלבש האור והשפע שלו ע\"י ג' צנורות דהיינו ג' קוין הנ\"ל, ולהיות שעיקר השפע מבחי' הכתר הוא בא לכך נק' המל' יהודה כמ\"ש הפעם אודה את הוי' בבחי' ביטול והודאה שלמעלה מהתפעלות אוי\"ר לפי שאוי\"ר מגיעים רק בג' קוין אבל באור הכתר לא יגיע רק בבחי' הביטול וההודאה בלבד מטעם שהוא למעלה מסדר ההשתל' כידוע וד\"ל. וזהו יהודה אתה מה שנק' המל' בש\"ע בבחי' יהודה היינו לפי שיודוך אחיך ע\"י ג' קוין שהמשיכו לה מאור הכתר ועי\"ז בא הכתר לידי גילוי במל'<sup data-n=\"1745\">43</sup> שנק' אתה כידוע והיינו יהודא אתה מן ההעלם לגילוי כו' וכנ\"ל וד\"ל.\n<b>אך</b> הנה עיקר פשט המקרא הזה משמע דאעפ\"י שיודוך אחיך מ\"מ אתה למעלה מהם, והיינו יהודה אתה, אתה דוקא בחי' יהודה מפני שהוא למעלה מהם ואעפ\"י שיודוך אחיך כו', וגם מפני שעיקר הכוונה הוא שיהודה למעלה וכמ\"ש בסוף דבריו ישתחוו לך בני אביך כו' לכך יש במשמעות ג\"כ בפי' יודוך אחיך שאחיך יודו אליו מלמטלמ\"ע כפשוטו של מקרא, וכן הוא בפי' ישתחוו לך בני אביך השתחוואה מלמטלמ\"ע ג\"כ כמשי\"ת בע\"ה כו'. והענין יובן בהקדים תחלה ענין המא'<sup data-n=\"1746\">44</sup> הידוע",[["1739","37","<b>ותעמוד מלדת</b>: ויצא כט, לה. ראה גם ביאורי הזהר ויגש כז, ב. שערי אורה שער החנוכה ס\"ע 40 וריש ע' כא."],["1740","38","<b>אין עמידה אלא שתיקה</b>: סוטה לט, א."],["1741","39","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1742","40","<b>אהבה הוא בחי' יש</b>: ראה לקוטי תורה מסעי צ, ב."],["1743","41","<b>כתר. . עילת העילות</b>: ראה פרדס שער (ג) אם הא\"ס הוא הכתר ספ\"א."],["1744","42","<b>כתר. . למעלה מג' הקווין כידוע בצורת האילן</b>: ראה פרדס שער (ו) סדר עמידתן פ\"א. שער (ז) הצנורות."],["1745","43","<b>במל' שנק' אתה</b>: ראה זהר (סבא) משפטים קד, א. פרדס שער (כג) ערכי הכינויים מערכת אתה. אור התורה ויחי ח\"ב ע' 726. וש\"נ."],["1746","44","<b>המא' הידוע בס\"י דנתב\"ס וסב\"ת</b>: ראה ספר יצירה פ\"א מ\"ז. מאמרי אדה\"א ויקרא ח\"ב ע' תרג. וש\"נ. במדבר ח\"ב ע' שסט. דברים ח\"ב ע' תסב."]]],[2100490352,"בס\"י דנתב\"ס וסב\"ת כו', ופי'<sup data-n=\"1747\">45</sup> המא' הזה ידוע שר\"ל על בחי' הכתר שנק' תחלתן שאינו מאיר עיקר הארתו רק בסופא דכ\"ד והוא בחי' המל' כידוע, וכמובן מתוך צורת הקוין שהמל' עומדת למטה תחת קו האמצעי דת\"י לעומתו של הכתר ממש, כי הכתר עומד על קו האמצעי כידוע וע\"כ נתב\"ס דוקא. והמשל<sup data-n=\"1748\">46</sup> בזה ידוע מבחי' הכאת אור השמש בארץ למטה דוקא ולא באמצע מפני שעיקר כלות השפע הוא בארץ להיות שאין עוד למטה הימנה ובכלות השפע שם תאיר אור ההתחלה דוקא כו'. והנמשל מזה מובן למשכיל כשההשפעה מאור הכתר כשהלכה דרך הצנורות בג' קווין הללו כנ\"ל עדיין לא הי' עיקר פנימי' השפע מאור הכתר מתגלה שם אלא הי' מלובש ומוסתר בהם, אך כשבא האור למטה ממש במל' ע\"י צנורות הנ\"ל אזי בכלות השפע שם דוקא האיר מבחי' פנימי' אור הכתר. והנה בחי' פנימי' הכתר הוא אשר אורו למעלה מן ההשתלשלו', ונק' בזוהר בשם טמירא<sup data-n=\"1749\">47</sup> דכל טמירין פי' שגם מהטמירין שהן בחי' שרשי' הנעלמים מג' קוין גם מהם הוא טמיר ונעלם כו', והוא המתגלה דוקא במל' הנק' סופן כי נתב\"ס דוקא כו'. ולזה הטעם ג\"כ נעוץ סופן בתחלתן והוא מה שאנו מוצאי' בחי' המל' שנק' בשם כתר ממש כמבואר במא' דאליהו קרקפת'<sup data-n=\"1750\">48</sup> כתר מל' וכדוגמא של כתר מל' הגשמי' שהכתר נתונה על הראש בבחי' מקיף ממש וזו היא עיקר בחי' המל' כידוע, ואעפ\"י שהמל' היא במדרגה התחתונה מ\"מ עיקר הארתה בבחי' הכתר והעטרה שעל המוחין שבראש כו', וכ\"ז מטעם שנסב\"ת דוקא.\n<b>ועתה</b> יובן זה היטב ביהודה אתה יותר בביאור ע\"ד שאנו רואי' במלכות' דארע', דהנה המלך בו\"ד אין לו כלום מצד עצמו רק שכל אנשי המדינה נותני' לו כסף גולגולת וכמה מיני מסים עד שיתעשר מנתינה שלהם עושר רב מכולם וגדול הוא בעושר וכבוד מכולם כידוע, שנמצא העושר והכבוד אינו שלו אלא מאנשי המדינה לקח ואעפ\"כ הוא מלך עליהם אח\"כ ומתנשא במלכותו עליהם, דלכאורה אם אין התנשאות זו אלא בשלהם לא היתה ענין ההתנשאות האמיתי' וא\"כ למה יקרא מלך, אך הענין הוא דבאמת אעפ\"י שבשלהם הוא סיבת התנשאותו אעפ\"כ אח\"כ נעשה התנשאות לבו ורוממות אמיתי' מצד עצמו לפי שאחר שנתנו לו נעשה באמת גדול ורם מהם ומתנשא עליהם מצד האמת, ונמצא שאעפ\"י שבשעת נתינתם נק' הם משפיעים והוא נק' מקבל אבל לאחר שמקבל מהם הוא מתעלה למעלה מהם בעלוי אמיתי ולא מצד נתינתם כו' אלא רק שנתינתם הי' סיבה להיות בא עי\"ז להתנשאות ורוממות כזאת כנ\"ל וד\"ל. וכך הנמשל למעלה בבחי' מל' דאצי' אעפ\"י שמקבלת מכל הג' קוין כמ\"ש יודוך אחיך כו', אבל לאחר שקיבלה מתנשאת עליהם להיות נקראת בבחי' כתר עליון ממש כנ\"ל מבחי' הפנימי' שלו הנק' טמירו דכל טמירין כו'",[["1747","45","<b>ופי' המא' הזה</b>: ראה פרדס שער (טו) ממטה למעלה פ\"א. מאמרי אדה\"א דברים ח\"ב ע' תסב ואילך."],["1748","46","<b>והמשל בזה ידוע</b>: ראה מאמרי אדה\"ז פרשיות התורה ח\"א ע' רצו וע' רצט. תורת חיים בשלח שיט, ב. בהערה שלפנ\"ז."],["1749","47","<b>טמירא דכל טמירין</b>: ראה זהר יתרו פט, א."],["1750","48","<b>קרקפת' כתר מל'</b>: ראה הנסמן במאמרי אדה\"א בראשית ע' כב."]]],[2100490353,"וע\"כ נק' כתר מל' מפני שבאמת נעוץ סופן בתחלתן וע\"כ מתנשא עליהם באמת, אך א\"א לה לבא לזה כ\"א ע\"י שתהי' בחי' מקבל מהם כמשל מלכות' דארע' הנ\"ל, וזהו אשת<sup data-n=\"1751\">49</sup> חיל עט\"ב שנעשית אחר הקבלה מבעלה בחי' העטרה על הראש. וזהו יהודה אתה יודוך, פי' מה שיהודה אתה מן ההעלם דפנימי' הכתר שלמעלה מן הג' קוין לגילוי אתה ונתעלית למעלה מהם כו' הוא לפי שיודוך אחיך בתחלה וקבלת מהם לפי שבזה אתה מתנשא עליהם אח\"כ כו' וד\"ל.\n<b>ידך</b> בעורך אויבך כו'. הנה זה המא' שייך למה שקדם לו באמרו יהודה אתה כו' דלכך ידך בעורף אויביך כו', ולכאורה אין להם שייכות זע\"ז כו', וגם יש להבין מ\"ש בעורף דוקא כו'. אך הענין יובן בהקדים תחלה שיש בבחי' המל' עליות וירידות תמיד ולעולם אינה עומדת במדרגה א' בלבד, כידוע בענין התפלות דבשחרית עולה המל' גם בכתר עליון כמו שאמרה הפעם אודה את ה' כנ\"ל ובמנחה עלייתה באופן אחר ובמעריב באופן אחר ובשבת ויו\"ט בדרכים אחרים כמבואר<sup data-n=\"1752\">50</sup> בפרטי' בפע\"ח, והכל מטעם שהמל' אינה אלא בחי' נקודה<sup data-n=\"1753\">51</sup> א' בלבד ולפעמי' היא עולה למעלה ע\"ג האות כמו החולם ולפעמי' היא באמצעות האות ולפעמי' תחת האות וכמו החיר\"ק וכידוע בתיקוני' ור\"מ והוא ביאור ענין נקודה<sup data-n=\"1754\">52</sup> קו שטח המבואר במ\"א באריכות, וזהו ענין הטעם בבחי' מל' מה שאינה עומדת במדרגה א' אלא עולה ויורדת תמיד, ודרך כלל הן ב' מדריגות, או בתכלית העלוי והוא כמו בחי' החולם שע\"ג האות וכמ\"ש ותחלימני<sup data-n=\"1755\">53</sup> ותחייני והוא בתפלה בלחש בשחרית שעומדת בבחי' הכתר שהוא עומד ע\"ג הקוין הנ\"ל ונק' סגול העליון כידוע ולכך ותעמוד מלדת כנ\"ל, או שהיא בתכלית הירידה והוא כמו החיר\"ק שתחת האות כו' ואז הנה היא יורדת למטה מטה בבי\"ע לברר ברורי' דרפ\"ח ניצוצי' וכמ\"ש ותקם<sup data-n=\"1756\">54</sup> בעוד לילה ותתן טרף לביתה כו' וכמ\"ש במ\"א וזהו מ\"ש ומל'<sup data-n=\"1757\">55</sup> בכל משלה כו'. והנה ענין נפילת<sup data-n=\"1758\">56</sup> אפיים שאחר ש\"ע ידוע שהוא ענין ירידה של המל' למטה מטה מאד ללקט ניצוצות מהיכלות דנוגה כו', ולכאורה אין שייכות לנפילת אפיים לש\"ע, אך הענין הוא דשניהם ענין א' והא בהא תלי' משום דלפ\"ע כח הרוממות כך הוא ערך כח ההשפלה והירידה כידוע בענין עומק<sup data-n=\"1759\">57</sup> רום עומ\"ת שנז' בס\"י, וגם כאן אחר שהי' בחי' עלי' למל' כ\"כ עד בחי' הכתר עצמו בבחי' חולם ע\"כ יכולה היא שתרד כ\"כ למטה לברר גם בעומק תחת והוא חשך ואפילה ולהיות מתהפך גם הרע לטוב כו' וד\"ל. והיינו ג\"כ ענין הסמיכות שסמך כאן לומר ידך בעורף אויביך",[["1751","49","<b>אשת חיל עט\"ב</b>: משלי יב, ד."],["1752","50","<b>כמבואר בפרטי' בפע\"ח</b>: ראה שם שער (א) התפילה פ\"ז. ועוד."],["1753","51","<b>נקודה. . ע\"ג האות. . באמצעות האות. . תחת האות</b>: ראה תקוני זהר ת\"י (כה, א). פרדס שער (כח) הנקודות פ\"ב."],["1754","52","<b>נקודה קו שטח</b>: ראה גם הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תע."],["1755","53","<b>ותחלימני ותחייני</b>: ישעי' לח, טז [ושם: והחייני — אבל כ\"ה בברכות נה, א. מאמרי אדה\"א דברים ח\"א ע' קה, וש\"נ. ח\"ד ע' א'תפ]."],["1756","54","<b>ותקם בעוד לילה</b>: משלי לא, ט. מאמרי אדה\"א במדבר ח\"א בתחלתו."],["1757","55","<b>ומל' בכל משלה</b>: תהלים קג, יט."],["1758","56","<b>נפילת אפיים שאחר ש\"ע</b>: ראה פרי עץ חיים שער (יג) נפ\"א פ\"ב."],["1759","57","<b>עומק רום עומ\"ת שנז' בס\"י</b>: פ\"א מ\"ה. ראה מאמרי אדה\"א בראשית ע' רסח. וש\"נ."]]],[2100490354,"למה שקדם יהודה אתה כו' משום דהא בהא תלי' דלפי שנעשי' המל' בחי' יהודה לכך ידך בעורף אויביך ג\"כ לברר ברורי' דרפ\"ח ניצוצי' שנפלו למטה מטה כו' וד\"ל. וזהו ענין יהודה<sup data-n=\"1760\">58</sup> בחול\"ם שהוא ענין ולשון הוה שתמיד יהודה כו' מפני שהחולם הוא ע\"ג האות כנ\"ל וע\"כ הוא למעלה מהתחלקות הקוין, ומפני שמהם נמצא מציאת בחי' מקור הזמן במל' דאצי', כידוע בפי' מ\"ע<sup data-n=\"1761\">59</sup> שהזמן גרמא נשים פטורות שהזמן בנוק' ומקבלת ממקור הזמן שבג' קוין הנ\"ל, ע\"כ נאמר יהודה בקמ\"ץ תחת הדלי\"ת ובמלאופ\"ם תחת הוי\"ו שזהו ענין עבר שכבר הודה, ולא ענין עבר בלבד אלא ענין נפעל דהיינו שכבר נעשה ונפעל שבחו ע\"י אחרים והוא שע\"י אחרים ששבחוהו והודו אותו נעשה משובח ומפואר למעלה ולכך נק' יהוד' בקמץ ומלאפום דהיינו שכבר הודו אותו ונשבח (בל\"א ער איז פאר לובט גיוו רן או „גילובטער כו'). וכך יובן למעלה שמפני שג' קוין הנ\"ל המשיכו בו אור הכתר בתחלה ע\"כ נק' יהודה בקמ\"ץ שכבר הודו אותו אחיך הנ\"ל וכמ\"ש יודוך אחיך, ולפי שמאור הכתר שהוא למעלה מהקוין כנ\"ל המשיכו בו ע\"כ נאמר יודוך בחולם על היוד ומלאופום לדל\"ת שבו לפי שכבר קיבל ההארה כו', אבל בעלותו למעלה מהם אח\"כ כנ\"ל והוא בבחי' הכתר עצמו שמשם נמשך בחי' היד<sup data-n=\"1762\">60</sup> הגדולה הנ\"ל שהוא יו\"ד דידך כו' אז נק' יהוד\"ה בחולם לפי ששם הוא למעלה גם מבחי' מקור מציאות הזמן שבקוין הנ\"ל וד\"ל.\n<b>ועתה</b> יש להבין שרש ענין מ\"ש בעורף דוקא כו'. הנה ענין זה יובן בהקדי' ענין המבואר במ\"א ע\"פ ויברך<sup data-n=\"1763\">61</sup> יעקב את פרעה בביאור מא' הזוהר ע\"ז דמה ההוא ס\"א קטיל ואפיק נשמתין אוף קוב\"ה עביד כה\"ג כמ\"ש ויהרוג<sup data-n=\"1764\">62</sup> ה' כל בכור כו' הה\"ד לסוסתי ברכבי פרעה דמיתיך רעייתי כו' ע\"ש. דהנה מבואר שם תוכן הענין כך, דההוא ס\"א הוא השטן<sup data-n=\"1765\">63</sup> מה שיורד ומסטין למטה באדם להביאו לידי חטא ועון בכל תחבולות שיכול ואח\"כ עולה למעלה ומקטרג לוקח נשמתו כו', שהוא מפני חפצו ליקח שפע וחיות מאותה הנשמה לפי שאין לו חיות זולת זה רק דבר קצוב בלבד כו', אך הנה עוד ענין א' יש מלבד במה דקטל ואפיק נשמתין לכונה הנ\"ל עוד יש לו כונה במיתה זו בשביל הגוף ג\"כ, דמלבד שהוציא את הנשמה להיכלות של החיצוני' עוד זאת יעשה הס\"א בדרך נקמה גם בגוף הגשמי אף שנשאר מת דמ\"מ בחי' הבל דגרמי נשאר בו כידוע בזוהר ובע\"ח ע\"פ ונפשו<sup data-n=\"1766\">64</sup> עליו תאבל כו' (וגם",[["1760","58","<b>יהודה בחול\"ם</b>: נסמן לעיל בהמאמר."],["1761","59","<b>מ\"ע שהזמן גרמא נשים פטורות</b>: קידושין כט, א (במשנה). ראה עץ חיים שער (נ) קיצור אבי\"ע פ\"ד. טעמי המצות ר\"פ בראשית. מאמרי אדה\"ז פרשיות התורה ח\"א ע' קלח ובהנסמן לשם. מאמרי אדה\"א דברים ח\"ב ס\"ע תרכב. וש\"נ."],["1762","60","<b>היד הגדולה</b>: ראה לעיל בהמאמר פיסקא ידך בעורף אויביך."],["1763","61","<b>ויברך יעקב את פרעה. . הזוהר ע\"ז</b>: ויגש מז, ז. י. זהר ס\"פ ויגש (בשינויים קלים). — ראה ביאורי הזהר קלו, ב ואילך. אור התורה כאן ע' תתשמא."],["1764","62","<b>ויהרוג ה' כל בכור. . לסוסתי ברכבי פרעה</b>: בא יג, טו. שיר השירים א, ט."],["1765","63","<b>השטן. . שיורד ומסטין. . ומקטרג לוקח נשמתו</b>: ראה בבא בתרא טז, א. ביאורי הזהר וישלח כא, ב. קלו, ב."],["1766","64","<b>ונפשו עליו תאבל</b>: איוב יד, כב. ראה זהר שלח קסט, א. קע, א. עץ חיים שער (ה) טנת\"א פ\"ה שער (יח) רפ\"ח ניצוצין פ\"א. מאמרי אדה\"ז פרשיות התורה ח\"א ע' שנב (ובהנסמ בריש המאמר שם). מאמרי אדה\"א דברים ח\"א ס\"ע קסב וריש ע' שכג."]]],[2100490355,"בדברי רז\"ל שאמרו כמחט<sup data-n=\"1767\">65</sup> בבשר החי כו') שיאחזו בגוף החומרי וידבקו בו בכל חלקיו כו' ויעשו בו כרצונו, עד\"מ הגזלן שהורג נפש שמלבד הרציחה עצמה הוא נופל על הגוף הנשאר ועושה בו פצעי' רבים וכיוצא. והנמשל מובן למעלה שגם גוף החומרי שנשאר אחרי יציאת הנשמה האלקי' הרי יש בו מ\"מ אפס [קצהו] מעט מזעיר מהארת הקדושה, הנה גם בו יאחזו החצוני' וידבקו לעשות בו כרצונם להוליכו להיכלו' שלהם לטנפו בכל טומאה שלהם, והוא ענין קבלת יניקה שלהם שמקבלי' גם מבחי' חצוני' ואחוריי' דקדושה שנשאר בגוף מלבד בחי' פנימי' היניקה שקיבלו מן יציאת הניצוץ האלקי כמ\"ש קטל ואפיק נשמתין ממש כו' וד\"ל. והנה ע\"ד דוגמא זו ממש הרי א' לסוסתי ברכבי פרעה דמיתיך רעייתי כו', דהיינו שם ב\"נ דקדושה כאשר מבררת ברורין דרפ\"ח ניצוצי' שנפלו בהיכלות דנוגה כו' הוא ג\"כ ע\"ד הנ\"ל כההוא סט\"א דקטיל כו', דמלבד שמוציאים בחי' הניצוצו' דקדושה מהם וכמ\"ש חיל<sup data-n=\"1768\">66</sup> בלע ויקיאנו כו' אלא גם מה שנשאר להם רק בחי' חיצוני' ואחוריים והוא בבחי' הגוף שלהם ששמנו ועבו מיניקת ניצוצי קדושה גם אותם יבררו ויתהפך לקדושה לגמרי, וכמו שיהי' לע\"ל דכתי' והי'<sup data-n=\"1769\">67</sup> מדי חדש בחדשו כו' יבא כל בשר להשתחוות כו' כל בשר ממש וכן וראו<sup data-n=\"1770\">68</sup> כל בשר ובאו במערות צורים כו', ועד\"ז הי' קצת ענין הכנעה של אוה\"ע לפני שלמה המלך ע\"ה בחצוני' ג\"כ, וגם לעתיד כתי' ועמדו<sup data-n=\"1771\">69</sup> זרים ורעו צאנכם כו'. אך זהו בימוהמ\"ש בלבד, אבל באלף הז' גם בחי' חצוני' כגוף לנשמה לא יהיו כי יבוררו מכל וכל עד שיהי' אין עוד מלבדו ממש וכמ\"ש בהם בלע<sup data-n=\"1772\">70</sup> המות לנצח שגם המות עצמו יבולע כו' והוא מפני שאת רוח הטומאה אעביר כו' אעביר לגמרי מכל וכל וע\"כ יהי' אז דוקא תכלית השלימות כו' וד\"ל.\n<b>ובזה</b> יובן גם כאן במ\"ש ידך בעורף אויביך בעורף דוקא, דהנה מבואר למעלה הטעם דדוקא אחר ש\"ע הוא נפ\"א מפני שלפ\"ע כח הרוממות כך ערך הכח של הירידות, והנה בש\"ע המל' עלה בבחי' הכתר עצמו כנ\"ל ע\"כ ברדתה למטה אח\"כ יוכל להיות בכחה להעלות גם מה שהוא בתחתי' שאול מפני שגם חשך לא יחשיך כו' וכנ\"ל דבחי' הרוחני' וגשמי' שוין קמי בחי' עצמו' אא\"ס וידוע דבכתר<sup data-n=\"1773\">71</sup> עליון יש בו מבחי' התחתונה שבעצמות כו'. והנה גם כשהמל' ירדה כ\"כ למטה להיותה בש\"ע בתכלית העלוי כנ\"ל ע\"כ ממילא יבטל מציאות החצוני' בהיותה מאירה עליהם אור האלקי בתכלית העלוי עד שיתבטלו ממציאותם וכמ\"ש כהמס<sup data-n=\"1774\">72</sup> דונג מפני אש יאבדו רשעי' מפני אלקי' עד שממילא נכללו באלקות והוא שם אלקי' דמל' כשירדה לברר",[["1767","65","<b>כמחט בבשר החי</b>: ברכות יח, ב."],["1768","66","<b>חיל בלא ויקיאנו</b>: איוב כ, טו. ראה סידור סדר סעודת שבת רג, ב. תורה אור תולדות כ, ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשעד. שערי אורה ע' ד וע' 172 ואילך."],["1769","67","<b>והי' מדי חדש בחדשו</b>: ישעי' סו, כג."],["1770","68","<b>וראו כל בשר ובאו במערות צורים</b>: ישעי' מ, ה. שם ב, יט."],["1771","69","<b>ועמדו זרים ורעו צאנכם</b>: ישעי' סא, ה."],["1772","70","<b>בלא המות לנצח. . שאת רוח הטומאה אעביר</b>: ע\"פ זכרי' יג, ב. ישעי' כה, ח."],["1773","71","<b>דבכתר. . יש בו מבחי' התחתונה שבעצמות</b>: ראה עץ חיים שער (מב) דרושי אבי\"ע פ\"א."],["1774","72","<b>כהמס דונג מפני אש. . מלך אלקי' על גוים</b>: תהלים סח, ג. שם מז, ב."]]],[2100490356,"למטה מטה וכמ\"ש מלך אלקי' על גוים כו'. וענין הביטול הזה יש בו ב' מדריגות, הא' בבחי' פנימי' והוא מפני שנגלה עליהם אור האלקי עד שממילא נכללו באלקות, והוא כמו ענין ביטול הנר בפני האבוקה כידוע, וכ\"ז בבחי' הפנימי' שלהם אבל בבחי' החצוני' שלהם זהו עיקר ענין הבירור, כי הפנימי' ממילא בטל וא\"צ בירור כלל אך החצוני' נשאר בגסותו והוא צריך בירור, והבירור שלו א\"א להיות מצד ההשתל' משום דלפי ההשתל' יש לו מקום יניקה להיות נשאר בגסותו ועביותו אלא צריך להיות הבירור ממקום הגבוה שלמעלה מן ההשתל' לגמרי דשם רוחני' וגשמי' שוין ממש כנ\"ל, והוא בבחי' אור הכתר שבמל' משום דנתב\"ס בש\"ע דוקא שנק' יהודה כנ\"ל, ואז נא' ידך בעורף אויביך פי' גם החצוני' ואחוריים דקליפה שנק' עורף גם הוא עולה ונכלל בקדושה האלקי', והיינו כענין שיהי' לע\"ל דכתי' בלע המות לנצח כו' עד שיהי' אין עוד מלבדו ממש כנ\"ל וד\"ל. וזהו ענין נתינת טעם למה שקדם יהודה אתה כו' לפיכך ידך בעורף אויבך דהא בהא תלי' דמאחר שיהודה אתה בבחי' הכתר ממש ע\"כ ממילא ידך בעורף אויביך. ובחי' היו\"ד דידך היינו אותו הכח העליון שמבחי' כ\"ע, והוא הנק' קוצו ש\"י כידוע המכה באחורי עורף דקליפה שעומדת בעורף<sup data-n=\"1775\">73</sup> דקדושה כידוע בענין פרעה, והיינו ע\"פ ענין המבואר<sup data-n=\"1776\">74</sup> ע\"פ ויברך יעקב את פרעה כו' שיעקב הוא שבירך בתחלה לפרעה להאיר מבחי' הכתר דקדושה כדי שאח\"כ גם בסופא דכל דרגין ג\"כ יהי' הכח הזה להפוך גם החצוני', וזהו ענין פי' ידך בעורף אויביך מבחי' יו\"ד דיהודה דהיינו כמו שעלה סוף מעשה במ\"ת כו' וכמ\"ש במ\"א וד\"ל.\n<b>ישתחוו</b> לך בני אביך. הנה פי' בני אביך הוא בחי' נו\"ה דאבא, כי פי' אביך הוא בחי' אור אבא כידוע, והטעם שנק' אביך כי הנה ידוע דמאור<sup data-n=\"1777\">75</sup> אבא נמשך מקור החסדי' ומקור הרחמי' ונק' אב הרחמן, כנראה בחוש שכל מה שיש באדם יותר רבוי החכ' תגדל אצלו התפשטות החסדי' ביותר והתינוק להיותו מצומצם בשכלו הוא מלא דינין ורוגזא תמיד כו', וגם הנה אנו רואי' שהחכ'<sup data-n=\"1778\">76</sup> דוקא תחי' בעלי' כו' וכמ\"ש במ\"א באריכות כו'. והנה ידוע דאוריי'<sup data-n=\"1779\">77</sup> מח\"ע נפקת וכידוע מארז\"ל דנובלות<sup data-n=\"1780\">78</sup> חש\"מ תורה כו' ופי' חשמ\"ע הוא בחי' ח\"ס דא\"א ובחי' הנובלות ממנה הוא בחי' התו' שבאצי' שהוא מתחיל בקו הימין חכ' חסד כו', והיינו בדרך כלל בחי' אור<sup data-n=\"1781\">79</sup> אבא שיונק ממזל הח' ונוצר שהוא כמו צינור שע\"י יפול בחי' נובלות בלבד מח\"ס דא\"א עד\"מ השערה<sup data-n=\"1782\">80</sup> שבראש שאין בה אלא מותרות מוחין כו'",[["1775","73","<b>בעורף. . פרעה</b>: ראה סידור סדר הגדה רצג, ג. הנסמן במאמרי אדה\"ז פרשיות התורה ח\"ב לע' תקיג."],["1776","74","<b>המבואר ע\"פ ויברך יעקב את פרעה</b>: ראה ביאורי הזהר ויגש שם קלז, ב."],["1777","75","<b>דמאור אבא. . אב הרחמן</b>: נסמן לעיל בהמאמר."],["1778","76","<b>שהחכ'. . תחי' בעלי'</b>: קהלת ז, יב."],["1779","77","<b>דאוריי' מח\"ע נפקת</b>: נסמן לעיל בהמאמר."],["1780","78","<b>דנובלות חש\"מ תורה</b>: בראשית רבא פי\"ז, ה. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'ריט."],["1781","79","<b>אור אבא שיונק ממזל הח' ונוצר. . צינור</b>: ראה אגרות קודש מכ\"ק אדמו\"ר זי\"ע ח\"ב ע' קיט ואילך. מאמרי אדה\"א דברים ח\"ג ע' תשפח. וש\"נ."],["1782","80","<b>השערה. . מותרות מוחין</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תקלא. וש\"נ. ח\"ג ע' תתקמד. וש\"נ."]]],[2100490357,"וכמ\"ש במ\"א. אך הנה הארה הזאת מסתעפת והולכת מקו הימין לקו האמצעי הוא בחי' דת\"י וכמ\"ש מימינו<sup data-n=\"1783\">81</sup> אש דת למו שדת התו' נתנה מימין ונתפשט בקו הממוצע להיות כלול מחו\"ג ג\"כ והיינו ענין אש<sup data-n=\"1784\">82</sup> שחורה ע\"ג לבנה כו' אבל עיקרה בימין כו', וחיבור זה מקו הימין לקו האמצעי הוא ע\"י הצינורות שהולכים ומחברים קו הימין עם קו האמצעי כמ\"ש בפרד\"ס<sup data-n=\"1785\">83</sup>, וזה החיבור אינו אלא בב' קוין ימין ואמצע ולא יש לקו השמאלי בג\"ה חיבור עמהם לענין זה מפני שהוא המשכת אור החסדים בעיקר השפע אך שנתלבשה להיות בבחי' קו הממוצע, אבל קו השמאל שאינו אלא בחי' גבו' אינו מתחבר עמהם כ\"כ כו' רק בדרך שלילה בלבד הוא שמתחבר, והיינו ענין שס\"ה ל\"ת כו' וכמ\"ש במ\"א וד\"ל. וזהו ישתחוו לך בני אביך בחי' נו\"ה דאבא ומפני שמסתעפים גם לקו האמצעי שהוא בחי' לוי כנ\"ל ע\"כ נק' בני אביך שהם שניים בלבד והם ראובן ולוי ואין שמעון בכללם לפי שהוא בחי' קו השמאל כנ\"ל וד\"ל.\n<b>וביאור</b> הדברים, הנה מה שא' למעלה יודוך אחיך דר\"ל כל השלשה אחים דוקא והן ג' הקוין ביחד זהו בש\"ע<sup data-n=\"1786\">84</sup> דוקא כנ\"ל שהיא רק חיי שעה כידוע, אבל ישתחוו לך בני אביך ר\"ל במצות ת\"ת<sup data-n=\"1787\">85</sup> בדבור בפה אחר התפלה<sup data-n=\"1788\">86</sup> שנק' חיי עולם והוא למעלה ממדרגת יודוך אחיך הנ\"ל ע\"כ אין בזה רק השניים בלבד והן ראובן ולוי כו', והטעם הוא לפי שאא\"ס<sup data-n=\"1789\">87</sup> שמלובש באור אבא דאורייתא נפקא מיני' הוא מבחי' מקור כל החסדי' שבבחי' הכתר עצמו ונק' מ\"ע, וכמ\"ש יהי<sup data-n=\"1790\">88</sup> רקיע בתוך המים ויהי מבדיל בין מים כו' דהיינו בין בחי' מים עליוני' שבכתר שהוא שרש התורה כנ\"ל וכמ\"ש ותמלא<sup data-n=\"1791\">89</sup> כד\"ה כו' כ\"ד ספרים דאוריית' שנשאבו ממ\"ע שבח\"ס כו' לבחי' מ\"ת שמתחת לרקיע, והוא אור השפע שנמשך בג' הקוין וכמ\"ש יקוו<sup data-n=\"1792\">90</sup> המים כו' והרקיע המבדיל הוא בחי' הפרסא שבא\"א כו', וע\"כ גם כשירד אור זה למטה בקוין למטה לא נתלבש רק בקו הימין שבבחי' החסד ונסתעף גם לקו האמצעי, ובכלם הוא ענין תורה וגמ\"ח תורה בקו האמצעי וגמ\"ח בקו הימין כו', והוא הנק' חיי עולם שמהם נמשך מוחין לז\"א שנק' עולם, וע\"כ הוא למעלה הרבה מבחי' יודוך אחיך הנ\"ל שאינו אלא בבחי' אור הכתר שנמשך מלמעלה ע\"י צמצום הפרס' והוא הרקיע המבדיל כו' (וזהו",[["1783","81","<b>מימינו אש דת למו. . כלול מחו\"ג</b>: ברכה לג, ב. ראה שער היחוד והאמונה פ\"ה. מאמרי אדה\"א דברים ח\"ד ס\"ע א'תמח ואילך."],["1784","82","<b>אש שחורה ע\"ג לבנה</b>: ראה רש\"י שיר השירים ה, טז (ד\"ה שחורות). זהר נשא קלב, א. רש\"י ברכה שם. ירושלמי שקלים פ\"ו סה\"א. תנחומא ר\"פ בראשית."],["1785","83","<b>כמ\"ש בפרד\"ס</b>: ראה שם שער (ז) הצינורות."],["1786","84","<b>בש\"ע. . חיי שעה. . חיי עולם</b>: שבת י, א. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תב."],["1787","85","<b>ת\"ת בדבור</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב הי\"ב. מאמרי אדה\"א דברים ח\"א ע' רמ. ח\"ד ע' א'רג. וש\"נ."],["1788","86","<b>אחר התפלה</b>: ראה לקוטי תורה ואתחנן ד, א. ברכה צו, ב."],["1789","87","<b>שאא\"ס שמלובש באור אבא</b>: נסמן לעיל בהמאמר."],["1790","88","<b>יהי רקיע בתוך המים</b>: בראשית א, ו."],["1791","89","<b>ותמלא כד\"ה. . כ\"ד ספרים דאוריית'</b>: חיי שרה כד, טז. ראה תקוני זהר תכ\"א (מו, ב). מאמרי אדה\"א דברים ח\"א ע' כו. וש\"נ. ח\"ד ע' א'קצט. וש\"נ."],["1792","90","<b>יקוו המים</b>: בראשית א, ט."]]],[2100490358,"שנאמר במשה<sup data-n=\"1793\">91</sup> כי מן המים משיתיהו פי' מבחי' מ\"ע הנ\"ל וד\"ל). ולהיות כי אבא<sup data-n=\"1794\">92</sup> יסד ברתא דוקא משום דאיש<sup data-n=\"1795\">93</sup> מזריע תחלה יולדת בת כו' ע\"כ א' ישתחוו לך בני אביך שבשביל המל'<sup data-n=\"1796\">94</sup> שנק' יהודא כנ\"ל הוא שיוצאי' ונמשכים בני אביך הנ\"ל שהן ראובן ולוי בב' קוין הנ\"ל, וזהו בראשית<sup data-n=\"1797\">95</sup> בשביל ישראל שנק' ראשית כי ישראל<sup data-n=\"1798\">96</sup> עלה במח\"ס דא\"א הנ\"ל כמו התורה כידוע דתלת קשרין הן כו' וכמ\"ש במ\"א וד\"ל.\n<b>וגם</b> הנה פי' השתחוואה זו היא מלמטלמ\"ע יתפרש ע\"ד הנ\"ל בפי' יודוך אחיך שאח\"כ הוא למעלה מהם כו' משום דנעוץ סופן כו' כך גם כאן משום דסומ\"ע<sup data-n=\"1799\">97</sup> עבמח\"ת וכענין במי<sup data-n=\"1800\">98</sup> נמלך בנש\"צ כו' א\"כ כנ\"י גבוה וכמ\"ש<sup data-n=\"1801\">99</sup> עט\"ב שהתו'<sup data-n=\"1802\">100</sup> נק' חתן תחלה כו' ואח\"כ נעשית כנ\"י עטרת לבעלה כו' כנ\"ל. ושרש ענין ההפרש שבין לוי ליהודה הנ\"ל בתוס' ביאור, הנה יובן בהקדים תחלה להבין ההפרש בין תורה לתפלה. דהנה כתיב לאהבה<sup data-n=\"1803\">101</sup> את הוי' אלקיכם ולעבדו כו', ויש להבין ההפרש הזה בין לאהבה ובין לעבדו כו'. אך הנה לשון<sup data-n=\"1804\">102</sup> עבודה לא שייך אלא כשמתקן איזה דבר כנודע, וענין התיקון היינו להוציא הפסולת ולברר הטוב עד שיהי' הדבר נקי מכל סיג וברור בתכלית זהו הנק' תיקון, והוא הנק' עבודה, ע\"ד עבודת העבד לאדוניו שמתקן לו צרכי ביתו שיש בזה ב' עניני' כלולים הא' לפנות הבית מכל דבר רע והב' להכשירו ולייפותו בכל מיני תיקון ויופי המצטרך כידוע, והדוגמ' מזה יובן ג\"כ בעבודה לה' שאין הענין בעבודה מצד איזה הכנעה וכי להכנעת הנברא הוא צריך מאחר דכולא<sup data-n=\"1805\">103</sup> קמי' כלא חשיבי ואין לך דבר חוץ ממנו כו', אך הענין הוא שיתקן איזו דבר זהו הנק' עבודה לפני ה', והתיקון הוא בב' אופני' הנ\"ל הא' בסומ\"ר והב' בוע\"ט שהן כללות ענין [המצוות] רמ\"ח מ\"ע ושס\"ה ל\"ת, וזהו העבודה האמיתי' במ\"ש ולעבדו כו'.\n<b>אך</b> הנה זה יתכן בבחי' המעשה שיהי' [ס]ו\"ר בפ\"מ וע\"ט בפ\"מ אבל כשאין מעשה מצוה לפניו האיך יקיים מצות ולעבדו כו', הנה ידוע דע\"ז ארז\"ל דמצות<sup data-n=\"1806\">104</sup> ת\"ת כנגד כולן דהיינו לפני שבת\"ת הוא פועל כל הפעולה הכללי' שבכל המצו' בכלל",[["1793","91","<b>במשה כי מן המים משיתיהו</b>: שמות ב, י. מאמרי אדה\"א דברים ח\"ד ע' א'קצט. וש\"נ."],["1794","92","<b>אבא יסד ברתא</b>: נסמן לעיל בהמאמר."],["1795","93","<b>דאיש מזריע תחלה יולדת בת</b>: ראה ברכות ס, א. נדה לא, סע\"א."],["1796","94","<b>המל' שנק' יהודה</b>: נסמן לעיל בהמאמר."],["1797","95","<b>בראשית בשביל ישראל שנק' ראשית</b>: בראשית א, א וברש\"י שם. הנסמן בלקוטי שיחות מקץ כרך ג' ע' 820."],["1798","96","<b>ישראל עלה במח\"ס. . דתלת קשרין הן</b>: ראה בראשית רבא פ\"א, ד."],["1799","97","<b>דסומ\"ע עבמח\"ת</b>: פיוט לכה דודי. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרד. במדבר ח\"ב ע' שסט. ח\"ג ע' א'קס."],["1800","98","<b>במי נמלך בנש\"צ</b>: ראה בראשית רבא פ\"ח, ז. רות רבא פ\"ב, ג. מאמרי אדה\"א דברים ח\"ג ע' תשסג. וש\"נ. ח\"ד ע' א'שפד וע' א'תיז."],["1801","99","<b>וכמ\"ש עט\"ב</b>: משלי יב, ד."],["1802","100","<b>שהתו' נק' חתן</b>: ראה לקוטי תורה ברכה צד, סע\"ד ואילך."],["1803","101","<b>לאהבה את הוי' אלקיכם ולעבדו</b>: עקב יא, יג."],["1804","102","<b>לשון עבודה. . כשמתקן</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ס\"ע קפו וריש ע' קפז. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תתלז ואילך ובהנסמן שם."],["1805","103","<b>דכולא קמי' כלא חשיבי</b>: ראה זהר בהקדמה יא, ב."],["1806","104","<b>דמצות ת\"ת כנגד כולן</b>: פאה רפ\"א."]]],[2100490359,"ברמ\"ח מ\"ע ושס\"ה ל\"ת כו', ולכאורה אינו מובן איך שיהי' ענין העבודה לברר הפסולת [במצוות ת\"ל, דלכאורה מצוות ת\"ת אינה אלא כשאר מ\"ע שהוא רק בבחי' וע\"ט כו'. אך הענין לפי שיש ג\"כ בעסק התורה ענין העבודה לברר בירורים להוציא הפסולת] כו', והוא כשלמוד בעיון דוקא שאז מפלפל בהלכה ומקשה קושיו' רבות והקושיו' הללו הרי מסתירי' אור האמת של הדין וההלכה [ו]א\"כ ה\"ז כמו בחי' הפסולת של הפרי המסתיר על הפרי, וכשמתרץ כל הקושיו' ועומד על אמיתי' הדין של ההלכה ה\"ז כמו שהסיר הפסולת והציא הברור והנקי ונק' אז ההלכה ברורה מפני שתבררה מכל סיג ופסולת המסתיר [להן] והן כל קושי' ובלבול, כמו ע\"ד דוגמא כשמקשה איזה סתירה מן דין משנה זו למשנה אחרת הרי א' מהן אינו אמת והרי נסתר אור האמת, וכשמתרץ לא קשי' הוא מנ\"י כו' וכל א' על מקומו יבא בדין אמת ה\"ז כמברר דבר אוכל מתוך פסולת, וע\"ז א' ג\"כ סלסלה<sup data-n=\"1807\">105</sup> ותרוממך כו' כמו שהסלסלול בשערות הדבוקי' יחד מפרידין זמ\"ז כך התירוצי' שהן הסברות המיישבי' הקושי' מפריד דבר הלכה זו מזולתה שלא יתבלבלו יחד כו' ולכך נק' התירוצי' פרוקי' כו'. ודרך כלל הנה הענין בהלכה עד שמביא הדבר לאורו נק' עבודת הברורי' אם כמו בירור של פסולת מן הפרי או התבואה או כמו בירור של הדיבוק של השערות עד\"מ משום שבהלכות<sup data-n=\"1808\">106</sup> שבתושבע\"פ נק' נימין דמט[רוניתא] כו' כמ\"ש בזוהר וד\"ל. וז\"ש<sup data-n=\"1809\">107</sup> בר\"מ על עבודת בנ\"י במצרים בחומר ובלבני' בחומר<sup data-n=\"1810\">108</sup> זו קושי' ובלבנים זו ליבון הלכתא ובכל עבודה בשדה הן ברייתו' כו', כי הנה כתי' ששים<sup data-n=\"1811\">109</sup> המה מלכות הן ס' מסכתות ושמונים פלגשי' הן ברייתות כו' וכולם צריכים בירור מכל סיג ופסולת עד שיבאו בתכלית הבירור, וה\"ז ממש כמו העבודה הגשמי' בשדה שיש בה מלאכות רבות בברורי' רבי' דהיינו בחרישה וזריעה וכל המלאכות עד שיוציאו הבירור האמיתי והוא גרעין הצומח וגם הוא צריך בירור עד שיעשה ממנו פת למאכל כו', וז\"ש הראשוני'<sup data-n=\"1812\">110</sup> חרשו וזרעו כו' וכידוע וד\"ל. וזהו עיקר הטעם שנק' בשם תורה וענין הוראה כי עיקרה הוא רק להבדיל בין פנימי' לחצוני' וכמ\"ש להבדיל<sup data-n=\"1813\">111</sup> בין הטמא לטהור כו' והוא להפריד הרע מן הטוב כו'. וא\"כ הרי יש במצות ת\"ת<sup data-n=\"1814\">112</sup> ענין העבודה לברר ברורי', וזהו ע\"ד ענין העלאת מ\"נ בתפלה שגם הוא עולה מלמטלמ\"ע כדבר שעולה מן המים נקי כו', וכמ\"ש שינייך<sup data-n=\"1815\">113</sup> כעדר הרחלי' שעלו מן הרחצה, ופי' שיניים הן ל\"ב נ\"ח שבתושבע\"פ שמבררת וטוחנת ההלכה ונק'",[["1807","105","<b>סלסלה ותרוממך</b>: משלי ד, ח."],["1808","106","<b>שבהלכות שבתושבע\"פ נק' נימין</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' נג. וש\"נ. דברים ח\"ב ס\"ע תקלד. במדבר ח\"ד ע' א'תעו."],["1809","107","<b>וז\"ש בר\"מ. . בחומר ובלבני'</b>: ראה זוהר (רעיא מהימנא) בהעלותך קנג, א. פינחס רכט, ב. בראשית כז, א. מאמרי אדה\"א ויקרא ח\"א ע' א."],["1810","108","<b>בחומר זו קושי'</b>: ועד\"ז הובא במאמרי אדה\"א במדבר ח\"ב ע' תריג: בחומר דא ק\"ו וקושי'. ובזהר שם: בעבודה קשה זו קושיא, בחומר דא קל וחומר."],["1811","109","<b>ששים המה מלכות הן ס' מסכתות. . ברייתות</b>: נסמן לעיל בהמאמר."],["1812","110","<b>הראשוני' חרשו וזרעו</b>: שקלים רפ\"ה."],["1813","111","<b>להבדיל בין הטמא לטהור</b>: שמיני יא, מז [ושם: ובין הטהור — אבל כ\"ה גם במאמרי אדה\"א במדבר ח\"ב ע' שנד. דברים ח\"א ע' רמה וע' רמח]."],["1814","112","<b>ת\"ת. . לברר ברורי'</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תסז."],["1815","113","<b>שינייך כעדר הרחלי'</b>: שיר השירים ו, ו."]]],[2100490360,"לכך בשם גירס' וע\"י העיון שאחר הגרס' הוברר, וזהו ענין הגרס' והעיון שהן מצות<sup data-n=\"1816\">114</sup> קריאה ומצות עיון שהן ב' מצות כמ\"ש והגית<sup data-n=\"1817\">115</sup> בו יומם ולילה שהוא מצות עיון וכתי' לא ימוש ספר התו' הזה מפיך כו' שהוא מצות קריאה וכאמרו בכמה דוכתי הקורא<sup data-n=\"1818\">116</sup> בתו', ודרך כלל עיקר מצות הקריאה הוא במקרא וגם במשנה אבל בתלמוד<sup data-n=\"1819\">117</sup> הוא רק מצות העיון כו', ובכללם הן בדוגמת רו\"ש שבתפלה כו' וד\"ל.\n<b>והנה</b> מאחר שעיקר עבודת לימוד התו' הוא בחי' העלא' ובירור כנ\"ל א\"כ אין זה תכלית הענין במה שלמד תורה בעיון בלא בחי' המשכת מ\"ד מלמעלה, וז\"ש רז\"ל האומר<sup data-n=\"1820\">118</sup> אין לי אלא תורה אפי' תו' אין לו כו', וה\"ז כמשל הפת שנאפה ואינו נאכל שלא נעשה ממנו שום חיות באדם אלא שנשאר בגשמיותו, כך הנה התו' נמשלה ללחם כמ\"ש לכו<sup data-n=\"1821\">119</sup> לחמו בלחמי, וכנ\"ל במשל הברורי' שתכליתם הוא אמיתי' הדין המתברר כו' אמנם הגם שהוא דין אמיתי מ\"מ מלובש הוא למטה בענין גשמי וצריך שיעלה למעלה ויוכלל באלקות כמשל הלחם לאדם התחתון כו', וזהו בענין הדינין וההלכות שהקב\"ה<sup data-n=\"1822\">120</sup> יושב ושונה כנגדו כמו בעובד'<sup data-n=\"1823\">121</sup> דרב\"נ שא' שם הקב\"ה במתיבת' דרקיע' א' טהור כו' לפי שכל ענין הדינין וההלכות כמו בענין הלכות נגעי' יש גם למעלה בעולמות עליוני' אלא שהן שם יותר בענין רוחני ושם הן מתכללי ממש באלקות כמו עד\"מ הנ\"ל בברורי' המאכלי' כו'.\n<b>והנה</b> עיקר ההתכללות שלהם הוא בזמן ק\"ש בשעה שמייחד האדם יח\"ע בפ' ראשו[נה] דק\"ש שאז כל מה שבירר ולמד ביום של אתמול נכלל ועולה באותו יחוד העליון, כי בבחי' אחד שאו' למטה נמשך אח\"ד העליון שהוא בחי' אדם שעל הכסא כו' א\"ח<sup data-n=\"1824\">122</sup> דלי\"ת והוא הנק' הקדב\"ה<sup data-n=\"1825\">123</sup> שהוא בחי' ז\"א דאצי' כידוע וד\"ל. וזשארז\"ל העוסק<sup data-n=\"1826\">124</sup> בת\"ת פטור מן התפלה, [מן התפלה] דוקא ולא מק\"ש, כי אפילו מי<sup data-n=\"1827\">125</sup> שתורתו אומנתו מפסיק לק\"ש בפסוק ראשון כידוע לפי שבק\"ש עולה כל מה",[["1816","114","<b>מצות קריאה ומצות עיון</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב הי\"ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' מה-מו. ח\"ב ע' תשס. ענינים ס\"ע רכד ואילך. שערי תשובה ח\"א לט, ב. פירוש המלות ה, ב (ספ\"ח). מאמרי אדה\"א ויקרא ח\"ב ע' תקצג וע' תשעד. דברים ח\"ד ע' א'שמא ואילך. לקוטי ביאורים לאגרות התשובה ע' מג ובהערה 8 שם."],["1817","115","<b>והגית בו. . לא ימוש</b>: יהושע א, ח."],["1818","116","<b>הקורא בתו'</b>: ברכות י, ב. מגילה כב, א. לב, א. תענית כז, ב."],["1819","117","<b>בתלמוד הוא רק מצות העיון</b>: ראה גם שערי תשובה שבהערה דלעיל ד\"ה מצות."],["1820","118","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["1821","119","<b>לכו לחמו בלחמי</b>: משלי ט, ה."],["1822","120","<b>שהקב\"ה יושב ושונה כנגדו</b>: ראה תנא דבי אליהו רבא רפי\"ח. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שעד."],["1823","121","<b>בעובד' דרב\"נ</b>: בבא מציעא פו, א. וראה ד\"ה זה במאמרי אדה\"א ויקרא ח\"ב ע' תמג וע' תנו."],["1824","122","<b>א\"ח דלי\"ת</b>: ראה פרי עץ חיים שער (ח) הק\"ש פי\"ב."],["1825","123","<b>הקדב\"ה. . ז\"א</b>: ראה סידור שער התפילין ז, ג. אמרי בינה שם קיד (א) ב. סידור שער המילה קמח, ג. תורה אור לך יב, ג."],["1826","124","<b>העוסק בת\"ת פטור מן התפלה</b>: ראה שבת יא, א."],["1827","125","<b>מי שתורתו אומנתו מפסיק לק\"ש בפסוק ראשון</b>: ראה שלחן ערוך אדה\"ז או\"ח הל' תפלה סק\"ו ס\"ד."]]],[2100490361,"שלמד ונכלל ביחוד עליון ואם לאו הרי נשאר למטה כל מה שלמד, והיינו מה שאמרו אשרי<sup data-n=\"1828\">126</sup> מי שבא לכאן ותלמודו בידו שלא נשאר למטה כו' וד\"ל. ואמנם הנה מה שאמרו שפטור מן התפלה דוקא משמעות הענין הוא שהתפלה ג\"כ מאותה המדריגה ולכך כבר נפטר [מ]תפלה ע\"י מצות ת\"ת, ולכאורה אין להם שייכות זע\"ז כלל שהרי התפלה<sup data-n=\"1829\">127</sup> נק' חיי שעה והתו' נק' חיי עולם כידוע. אך הענין יובן בהקדים שיש ב'<sup data-n=\"1830\">128</sup> מדריגות בתפלה עצמה הא' בחי' ג' ראשונו' וג' אחרונות והב' י\"ב ברכות האמצעות כמ\"ש בפע\"ח, ועל י\"ב האמצעי' הוא שאמרו שהתפלה נק' חיי שעה אבל לא על ג' ראשונו' וג' אחרונו' לפי שי\"ב האמצעי' הם בקשות ושאלות צרכיו כמו רפאנו ברך עלינו משא\"כ בג\"ר וג' אחרונו' כידוע וכשארז\"ל בעוסק בת\"ת שפטור מן התפלה כוונתם הוא לתפלה שנק' חיי שעה והן י\"ב אמצעי' כו'. והענין הוא לפי שהתפלה ג\"כ מאות מדרגה שיש בתורה, והוא ענין העבודה שהוא להמשיך אוב\"כ כמו בתורה בבחי' עבודה הנ\"ל, אך שבתפלה ההמשכות הן בבחי' מל' דאצי' שתאיר אוב\"כ דבי\"ע כמו במאלכים ונשמות עד עולם העשי' השפל שלנו ובכל עולם לפי ערכו מגיע אור השפע די\"ב האמצעי', וע\"כ נק' חיי שעה לפי שהתהוות העולמות כולם ממל' דאצי' נק' שעה א' בערץ האצי' וחיי שעה היינו המשכות מוחין וחיות השפע לכולם לכאו\"א כפי הראוי כו', ובתורה ההמשכות הן בעולם האצי' עצמו שיהא שם המשכות אוב\"כ שבבחי' האצי' והוא הנק' חיי עולם, דז\"א דאצי' נק' עולם והמוחין העליוני' מאורות דאו\"א שנמשכו בו נק' חיי עולם כידוע, וא\"כ מי שתו' אומנתו פטור מן התפלה בהמשכות חיי שעה לפי שיש<sup data-n=\"1831\">129</sup> בכלל מאתיים מנה וכבר נכללו אותן ההמשכות שבש\"ע בעסקו בתו' בהמשכות חיי עולם, והיינו<sup data-n=\"1832\">130</sup> שתמה מניחין חיי עולם ועוסקין בחיי שעה משום דכל ההמשכות שבי\"ב האמצעי' נכללי' למעלה בחיי עולם ובטלים שם כביטול נר בפני האבוקה ולכך פטור מן התפלה דוקא לפי שממילא הן באים משום דהטפל בטל לגבי העיקר והולך ונגרר אחריו ממילא כו' וד\"ל.\n<b>ואמנם</b> אעפ\"י שפטור מן התפלה אינו פטור מק\"ש מטעם הנ\"ל לפי שצריך שיוכל ביחוד עליון תחלה ואם לאו אינו מתקן וממשיך כלום כו'. וכ\"ז בבחי' י\"ב אמצעי' שבתפלה אבל בחי' ג\"ר וג\"א לא נק' תפלה לענין זה אחר שאינן שאלות ובקשות כלל אלא הן רק בחי' הודאה ושבח בעלמ' וענינם הוא למעלה הרבה מבחי' עבודה הנ\"ל בתורה ובתפלה. כי הנה בהודאה זו הוא רק בחי' ביטול במציאות ואינו מבקש לתקן דבר למלך כי בחי' העבודה שהוא שירות ושימוש לפנות בית המלך וכיוצא זהו רק באנשי' הבלתי מקורבים כ\"כ למלך אבל באותם המקורבים מאד לא יתכן עליהם בחי' העבודה אלא נקראי' רואי פני המלך והן שריו הנכבדי' שהן עומדי' תמיד לפניו ואינם עושים שום שירות ותיקון דבר מה, וכענין שא' מלכ' שבא לשלמה אשרי<sup data-n=\"1833\">131</sup> אנשי'",[["1828","126","<b>אשרי מי שבא לכאן</b>: פסחים נ, א."],["1829","127","<b>התפלה נק' חיי שעה והתו' נק' חיי עולם</b>: נסמן לעיל בהמאמר."],["1830","128","<b>ב' מדריגות בתפלה. . כמ\"ש בפע\"ח</b>: ראה שם שער (ט) העמידה פ\"ה."],["1831","129","<b>שיש בכלל מאתיים מנה</b>: בבא קמא עד, א."],["1832","130","<b>והיינו שתמה מניחין חיי שעה</b>: שבת י, א."],["1833","131","<b>אשרי אנשי' העומדי' לפניך</b>: מלכים-א ח (בדילוג)."]]],[2100490362,"העומדי' לפניך כו', והוא במדרגה היותר עליונה עד שנחשבי' כבן ולא עכבד וכמו שא' ר\"ג<sup data-n=\"1834\">132</sup> על רחב\"ד שהוא כעבד ע\"כ פועל בקשתו מיד, והוא כמו שר שלמעלה הוא ממדרגת פעולה זו כו'. והדוגמ' מזו למעלה בדרך כלל שזהו ההפרש בין י\"ב אמצעי' לג\"ר וג\"א לפי שבג\"ר וג\"א הוא רק בחי' ביטול במציאו' ע'י הודאה וברכה לא לבקשת דבר מה כו' א\"כ בהכרח לומר שלמעלה הוא מבחי' תיקון ועבודה הנ\"ל. והנה העבודה הנ\"ל הרי הוא בא בהכרח ע\"י יחוד מ\"ן ומ\"ד כנ\"ל בפי' לעבדו בתורה שהוא בחי' ברורי' בהעלאת מ\"נ ואח\"כ נכלל במ\"ד ביחוד דק\"ש וכה\"ג בי\"ב אמצעי' שבש\"ע כי הכל ענין א' הם, אבל בג\"ר וג\"א הוא למעלה מעלה מבחי' מ\"נ ומ\"ד וע\"כ אין שם ענין עבודה כלל כו' וד\"ל.\n<b>וזהו</b> ההפרש שבין לוי ליהודה דבט\"ו ווי\"ן דאמת ויציב היינו המשכות המשפיע וכמ\"ש כי ילוה אישי אלי, והוא ענין המשכות חיי עולם בתורה וממילא נמשך המשכות בנוק' בי\"ב אמצעי' הנק' חיי שעה כנ\"ל, והרי עכ\"פ יש כאן בחי' משפיע עם בחי' מקבל מאחר שא' ילוה אישי אלי הרי יש מי שנק' אישי והוא המשפיע ויש בחי' מקבל שהוא מל' דאצי' וזהו שאמרה אלי והוא ע\"ד יחוד מ\"נ ומ\"ד שהי' בק\"ש בפסוק ראשון כנ\"ל, אבל בג\"ר וג\"א נאמר הפעם אודה את הוי' בבחי' הודאה וביטול במציאות בלתי שום ענין המשכה ממשפיע למקבל לפי ששם המל' עומדת למעלה מבחי' משפיע ומקבל והיינו בבחי' פנימי' הכתר כנ\"ל שזהו פי' עט\"ב כו' לפי שנסב\"ת ונק' אז כתר מל' כו' וע\"כ הוא למעלה אז גם מחיי עולם וחיי שעה הנ\"ל שהרי הן רק יחוד דזו\"נ דאצי' וד\"ל. וזהו ג\"כ ההפרש בין לאהבה ובין לעבדו כו', דהנה האהבה של בן לאביו אינה פועלת שום ענין רק האהבה היא טבעי' בתמידו' גם שאינו מבקש כלום משא\"כ בעבד שאין אהבתו ניכרת רק בשעה שמבקש דבר כו' וד\"ל.\n<b>והנה</b> כמו שנעוץ סופן בתחלתן בבחי' יהודה בג\"ר וג\"א כנ\"ל כך גם בצות מעשי' ג\"כ נסב\"ת עד שמעשה המצוה גדולה מגוף המצוה המפורשת בתורה. דהנה עד\"ד מצות סוכה נתפרש בתו' ואעפ\"י שנתפרשה כבר אינה נק' מצוה ממש עד שתבא לידי עשי' בפ\"מ והוא שיעשה האדם סוכה וישב בה אז נק' מצוה, וכידוע שהמצוה היא ב[בחי'] מל' שהוא בחי' עשי' וכמ\"ש כי<sup data-n=\"1835\">133</sup> נר מצוה ותו' אור כו', וא\"כ כשנסב\"ת הרי המעשה של המצוה גדולה מגוף אור המצוה שכתובה בתו' כענין הנ\"ל ביהודה כו'. וזהו שרש ענין ישתחוו לך בני אביך כו' דקאי בב' עניני' בג\"ר שבתפלה ובמעשה המצות ומטעם א' לשניהם כנ\"ל, ובני אביך הן תושב\"כ שנק' מוסר אביך כנ\"ל וד\"ל. והיינו שא' שכר<sup data-n=\"1836\">134</sup> מצוה מצוה כי המצוה עצמ' גדול מאור המצו' כמו שהיא בתו' מטעם הנ\"ל להיותה בבחי' כת\"ר מל' וד\"ל.",[["1834","132","<b>ר\"ג על רחב\"ד שהוא כעבד</b>: ראה ברכות לד, ב [ושם: ר' יוחנן בן זכאי] — אבל כ\"ה בכ\"מ, ומהם: ביאורי הזהר קרח צד, א (ושם: (ר\"ג) ריב\"ז). ויצא קלד, סע\"ג. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשטו ואילך. תקס\"ה ח\"ב ע' תשפד. תקס\"ח ח\"א ע' תשג (עיי\"ש). הנחות הר\"פ ע' קעט. הגהת הצ\"צ בסה\"מ תקס\"ב ח\"ב ע' תרטו]."],["1835","133","<b>כי נר מצוה ותו' אור</b>: משלי ו, כג."],["1836","134","<b>שכר מצוה מצוה</b>: אבות פ\"ד מ\"ב."]]],[2100490363,"<h3>נוסח שני: יהודה אתה יודוך אחיך</h3>\n<b></b><b>בעזה\"י וית' שבת קודש פ' ויחי</b>\n<b>יהודה</b><sup data-n=\"1837\">1</sup> אתה יודוך אחיך<sup data-n=\"1838\">2</sup> ידך בעורף אויבך, ישתחוו לך בני אביך וגו'. הנה יהודה הוא לשון הודי\"ה כמ\"ש הפעם<sup data-n=\"1839\">3</sup> אודה את ה' ע\"כ קראה שמו יהודה שהיו\"ד מורה על התמדת הפעולה תמידית כמו ככה<sup data-n=\"1840\">4</sup> יעשה איוב כל הימים (כדפירש\"י שם וכמ\"ש בלק\"א<sup data-n=\"1841\">5</sup> ח\"ב) והיינו כדכתיב אלקים<sup data-n=\"1842\">6</sup> אל דמי לך אל תחרש ואל תשקוט אל וגו' למען<sup data-n=\"1843\">7</sup> יזמרך כבוד ולא ידום וגו' שלמעלה הוא בחי' ההודאה תמידיו' בלי הפסק כלל אך למטה בלבד נאמר הפעם אודה את ה' הפעם דוקא שהוא תחת הזמן כנודע וזהו יהוד\"ה אתה יודוך אחיך כו' שבחי' ההודאה שבבחי' יהודא נמצא מאחיו המפורשי' בתורה קודם לכן שהם ראובן שמעון ולוי שהם יודו\"ך להמשיך בו בחי' ההודאה כו'.\n<b>וביאור</b> הענין דהנה ארבעה<sup data-n=\"1844\">8</sup> אחין אלו הם בחי' ד' תיקונין דתפלה והיינו כי ראובן הוא בחי' ארי\"ה שבמרכבה דכתיב ופני<sup data-n=\"1845\">9</sup> ארי\"ה אל הימין לארבעתם וכן דגל<sup data-n=\"1846\">10</sup> מחנה ראובן תימנה וארי\"ה<sup data-n=\"1847\">11</sup> הוא אותיות ראי\"ה והיינו בחי' ומדרגת ראובן<sup data-n=\"1848\">12</sup> שהוא בחי' ראי\"ה והתקרבות דהיינו בחי' האהבה רבה שנתעוררה בתפלה מגודל עוצם עומק ההתבוננות בגדולת אין סוף ב\"ה איך שאמר במאמר א' והי' העולם כו' ולזה אומר' ברוך<sup data-n=\"1849\">13</sup> הוא לשון המשכה וגילוי שיתברך ויתגלה זה בלבבינו איך שאמר והי' העולם ברוך<sup data-n=\"1850\">14</sup> אומר ועושה כי בטובו<sup data-n=\"1851\">15</sup> מחדש בכל יום מע\"ב וכן בפסוקי דזמרה כשיתבונן המשכיל איך שהללוהו<sup data-n=\"1852\">16</sup> מן השמים הללוהו כל מלאכיו כו' אשר לגדודיו<sup data-n=\"1853\">17</sup> אין מספר אלף אלפים וריבוא רבבן אין קץ וכולם<sup data-n=\"1854\">18</sup> עונים באימה ואומרים ביראה",[["1837","1","<b>יהודה אתה יודוך אחיך</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 2140 ריח, א.\nהנחת כ\"ק אדמו\"ר האמצעי ממאמר זה נדפס לעיל ע' רמח. נו\"א נדפס בתו\"א ר\"פ ויחי (מה, א). ועל אחד מהכת\"י של נוסח התו\"א נמצא כותרת: פרשה ויחי שנת תקס\"ו לפ\"ק בלאדי.\nהגהות על מאמר זה [נוסח תו\"א] מאדמו\"ר הצ\"צ נדפס באור התורה ויחי כרך ה' ע' תתקצז ואילך. ע' תתרה ואילך. כרך ו ע' 2276 ואילך [השוה כרך ה שם ע' 1994 בתוס' הגהות]."],["1838","2","<b>יהודה אתה יודוך אחיך</b>: ויחי מט, ח."],["1839","3","<b>הפעם אודה את ה'</b>: ויצא כט, לה."],["1840","4","<b>ככה יעשה איוב כל הימים</b>: איוב א, ה."],["1841","5","<b>בלק\"א ח\"ב</b>: ראה שער היחוד והאמונה פ\"ד (עט, רע\"א). וראה מאמרי אדה\"א דברים ח\"ג ע' תשצ."],["1842","6","<b>אלקים אל דמי לך</b>: תהלים פג, ב."],["1843","7","<b>למען יזמרך כבוד ולא ידום</b>: תהלים ל, יג."],["1844","8","<b>ארבעה אחין. . ד' תיקונין דתפלה</b>: ראה זהר בהיכלות דפ' פקודי. שער האמונה ס\"פ נד. תורת חיים חיי שרה קכט, ג. וראה זהר במדבר קיח, ב."],["1845","9","<b>ופני ארי' אל הימין</b>: יחזקאל א, י."],["1846","10","<b>דגל מחנה ראובן תימנה</b>: במדבר ב, י."],["1847","11","<b>ואריה הוא אותיות ראיה</b>: מגלה עמוקות אופן קג וביאורי הזהר שם. ראה תקוני זהר קכב, א."],["1848","12","<b>ראובן. . האהבה רבה</b>: ראה זהר חדש יתרו לא, ב."],["1849","13","<b>ברוך הוא לשון המשכה</b>: ראה לקו\"ת בחוקותי מח, ב. ראה כט, א."],["1850","14","<b>ברוך אומר ועושה</b>: ברכת ברוך שאמר."],["1851","15","<b>בטובו מחדש בכל יום מע\"ב</b>: ע\"פ ברכת יוצר אור."],["1852","16","<b>שהללוהו מן השמים. . כל מלאכיו</b>: תהלים קמח, א-ב."],["1853","17","<b>לגדודיו אין מספר</b>: חגיגה יג, ב. הובא בתניא פמ\"ו (סה, ב)."],["1854","18","<b>וכולם עונים. . צבאות</b>: ברכת יוצר."]]],[2100490364,"קדו\"ש ג\"פ הוי' צבאות כו' פי' שהוא בעצמו ית' קדוש ומובדל מהם המתנשא מימות עולם דלית<sup data-n=\"1855\">19</sup> מחשבה תפיסא ביה כלל רק החיות של הנפעלים הרוחניים והגשמיים הוא מבחי' ש' כבוד מלכותו ית' המחיה את כולם ומתלבשת בבחי' הצבאות וזהו הוי' צבאות מכה\"כ כבודו דוקא כנודע, אי לזאת כאשר יתבונן המשכיל בכל הדברים האלה בעומק הדעת תתעוררה בלבבו בחי' אהבה רבה ברשפי אש ושלהבת עזה לאסתכלא<sup data-n=\"1856\">20</sup> ביקריה דמלכא ולחזות<sup data-n=\"1857\">21</sup> בנועם ה' ב\"ה כי ראיה והסתכלות הוא בחי' התקרבות כי אין הראיה יתכן זולתי מקרוב ממש וזהו בחי' ראובן<sup data-n=\"1858\">22</sup> רא\"ו ב\"ן להיות האהבה והתשוקה להתקרב אליו ב\"ה לאסתכלא ממש ביקרי' דמלכא ולחזות בנועם ה' ממש הגם שהכל יודעין איך שהקב\"ה ממכ\"ע וסכ\"ע ומחדש את כל הנפעלים מאין לי\"ש וישראל מאמינים<sup data-n=\"1859\">23</sup> בני מאמינים אך לזה נאמר [מי] לא יראך<sup data-n=\"1860\">24</sup> מלך הגוים שאף הגוים ואו\"ה קרו<sup data-n=\"1861\">25</sup> ליה אלהא דאלהא רק הוא למעלה מן השכל והדעת בבחי' העלם מאד שאעפ\"כ יכול לעשות מה שלבו חפץ כמארז\"ל גנבא<sup data-n=\"1862\">26</sup> אפום מחתרתא רחמנא קריה שאף שהולך לגנוב במחתרת שם מזכיר שם אלהים שיעזרוהו בהגניבה ואם הי' נקבע זה בדעתו לא הי' גונב כי כתיב לא<sup data-n=\"1863\">27</sup> תגנוב ויראת<sup data-n=\"1864\">28</sup> מאלקיך כתיב אלא שזהו למעלה מן הדעת בבחי' אמונה בלבד שמאמין בה' ולכך רחמנא קרי' אף במחתרת ואין זה סותר לו למונעו מהעבירה שהוא דבר בפ\"ע ועושה מה שלבו חפץ ועד\"ז מי לא יראך מלך הגוים וד\"ל.\n<b>אבל</b> כשיוקבע בדעתו היטב בעומק ההתבוננות בתפלה גדולתו ית' איך שאלף<sup data-n=\"1865\">29</sup> אלפים ורבוא רבבן קדמוהי אשר לגדולתו<sup data-n=\"1866\">30</sup> אין חקר וכולם מקבלים עליהם עול מ\"ש באימה ויראה מפני שעיקר חיותם הוא ממדת מלכותו ית' בלבד אבל מהותו ועצמותו מרומם לבדו אי לזאת תתפעל לבבו באהבה והתלהבות אליו ית' לאסתכלא ביקריה דמלכא וזהו בחי' ומדרגת ראובן<sup data-n=\"1867\">31</sup> רא\"ו ב\"ן שהוא בחי' פרשה ראשונה דק\"ש דכתיב ואהבת את הוי' אלקיך בכל לבבך<sup data-n=\"1868\">32</sup> ודרשו רז\"ל בשני יצריך ביצ\"ט וביצ\"ה כו' כענין מארז\"ל במקום<sup data-n=\"1869\">33</sup> שבע\"ת עומדין צדיקים גמורים אין יכולים",[["1855","19","<b>דלית מחשבה תפיסא ביה</b>: ראה תקו\"ז בהקדמה (יז, א)."],["1856","20","<b>לאסתכלא ביקריה דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["1857","21","<b>ולחזות בנועם ה'</b>: תהלים כז, ד."],["1858","22","<b>ראובן רא\"ו ב\"ן</b>: ראה בראשית רבא פע\"א, ג."],["1859","23","<b>מאמינים בני מאמינים</b>: שבת צז, א. שמו\"ר פכ\"ג, ה."],["1860","24","<b>מי לא יראך מלך הגוים</b>: ירמי' י, ז."],["1861","25","<b>קרו ליה אלהא דאלהא</b>: מנחות בסופה."],["1862","26","<b>גנבא אפום מחתרתא</b>: גי' העין יעקב — ברכות סג, א."],["1863","27","<b>לא תגנוב</b>: יתרו כ, יג. וראה סנהדרין פו, א. הובא ברש\"י יתרו שם."],["1864","28","<b>ויראת מאלקיך</b>: קדושים יט, יד. ועוד."],["1865","29","<b>שאלף אלפים ורבוא רבבן קדמוהי</b>: דניאל ז, י."],["1866","30","<b>לגדולתו אין חקר</b>: תהלים קמה, ג."],["1867","31","<b>ראובן. . פרשה ראשונה דק\"ש</b>: ראה אוה\"ת כי תשא ע' א'תתפו. דברים ע' ב'נג."],["1868","32","<b>בכל לבבך. . ודרשו רז\"ל בשני יצריך</b>: ואתחנן ו, ה. ובספרי שם. ברכות נד, א (במשנה)."],["1869","33","<b>במקום שבע\"ת עומדין</b>: ברכות לד, ב. וראה הערת כ\"ק אדמו\"ר זי\"ע בספר המאמרים תש\"ט ע' 183."]]],[2100490365,"לעמוד ומפ' הזהר הטעם מצד שבע\"ת הם ששבי' בתשובתן הנפלאה בכל נפשם ומאדם מן ההיפוך לאהפכא<sup data-n=\"1870\">34</sup> מחשיכא לנהורא אזי תגדל הצמאון וההשתוקקות הנפלאה שלהם בהתלהבות גדולה בחילא דתיאובתא יתיר להיותם צועקים בצר להם דוקא לכך משכי<sup data-n=\"1871\">35</sup> לי' בחילא יתיר וכדכתיב ויצעקו<sup data-n=\"1872\">36</sup> אל ה' בצר להם דייקא, ולאו דוקא בע\"ת גמורים ששבים מהעבירות שבידם אלא אפילו<sup data-n=\"1873\">37</sup> מי שלא עבר עבירה קלה של ד\"ס מימיו אעפ\"כ נק' בחי' בע\"ת והיינו שכל הנשמות ישראל שירדו ממקור חוצבן שהיו צרורים בצרור החיים ב\"ה להתלבש בגופים החומריי' דעה\"ז נקראו בחי' בע\"ת ויצעקו אל ה' בצר להם דהיינו כמ\"ש אני<sup data-n=\"1874\">38</sup> ה' אלקיכם אשר הוצאתי אתכם מארץ מצרים וגו' פי' מצרים<sup data-n=\"1875\">39</sup> הוא לשון מיצר וגבול שהמה כל העולמות הנפרדים שהם בבחי' מצרי\"ם וגבולים כמארז\"ל מהארץ<sup data-n=\"1876\">40</sup> לרקיע ת\"ק שנה וכן מרקיע לרקיע כו' רגלי החיות כנגד כולן שוקי החיות כנגד כולן כו' שיש להם גבול ומיצר בחי' ת\"ק שנה כו' וגם יש גבול להשגתן שמשיגים באור<sup data-n=\"1877\">41</sup> פני מלך חיים ב\"ה ולזאת יצעקו בצעקה גדולה ומרה מנקודת לבבו בצר להם בבחי' תשובה לשוב עד ה' אלקיך בכל לבבם ונפשם ומאדם, וע\"י אתערותא דלתתא של בחי' בע\"ת דמשכי לי' בחילא יתיר בצר להם שזהו בחי' ראובן לאסתכלא ביקרי' כו' שהוא בחי' פרשה ראשונה דק\"ש דכתיב בה ואהבת כו' בכל לבבך בשני יצריך כנ\"ל ובכל נפשיך הוא בחי' התקשרות מדו\"מ שלו במדו\"מ של הקב\"ה בחכמתו ורצונו בתו\"מ מעוררים אתערותא דלעילא שיתגלה בחי' אהבה רבה וחסד עליון של הקב\"ה לכנ\"י כמ\"ש וימינו<sup data-n=\"1878\">42</sup> תחבקני וד\"ל.\n<b>וזהו</b> שכתוב ותהר<sup data-n=\"1879\">43</sup> לאה ותלד בן ותקרא שמו ראוב\"ן כי אמרה כי ראה הוי' בעניי כי עתה יאהבני אישי, פי' שע\"י בחי' אתערותא דלתתא דבחי' ומדרגת ראובן שהוא בחי' אהבה רבה לאסתכלא ביקרי' דמלכא שנסתעפה מבחי' העוני והמיצר בקראתו אליו בצר לו דוקא כנ\"ל מעוררי' אתעדל\"ע בחי' אה\"ר וחסד עליון בראי' והסתכלות מלמעלה למטה להיות וימינו תחבקני וזהו כי ראה ה' בבחי' ראיה מלמעלה למטה בעניי בבחי' העוני והמיצר שלי אשר קראתי בצר לי כנ\"ל כי אתה יאהבני אישי פי' אישי<sup data-n=\"1880\">44</sup> נק' הקב\"ה כדכתיב ביום<sup data-n=\"1881\">45</sup> ההוא תקראי לי אישי ולא תקראי לי עוד בעלי וגו' והיינו שהוא בחי' אש שלי שאין לו חפץ ורצון אחר ברשפי אש זולתי אליו ית' רשפיה<sup data-n=\"1882\">46</sup> רשפי אש שלהבת י\"ה וזהו אישי שהוא בחי' האש דכנ\"י",[["1870","34","<b>לאהפכא מחשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["1871","35","<b>משכי לי' בחילא יתיר</b>: ראה זהר חיי שרה קכט, ב. אגרת התשובה פ\"ח."],["1872","36","<b>ויצעקו אל ה' בצר להם</b>: תהלים קז, ו. כח."],["1873","37","<b>אפילו מי שלא עבר עבירה. . בחי' בע\"ת</b>: ראה גם לקו\"ת בלק עה, ב. שבת שובה סו, ג."],["1874","38","<b>אני ה' אלקיכם</b>: בהר כה, לח. בחוקותי כו, יג. שלח טו, מא."],["1875","39","<b>מצרים הוא לשון מיצר</b>: ראה בראשית רבה פט\"ז, ה."],["1876","40","<b>מהארץ לרקיע ת\"ק שנה</b>: חגיגה יג, א."],["1877","41","<b>באור פני מלך חיים</b>: משלי טז, טו."],["1878","42","<b>וימינו תחבקני</b>: שה\"ש ב, ו."],["1879","43","<b>ותהר לאה. . יאהבני אישי</b>: ויצא כט, לב."],["1880","44","<b>אישי נק' הקב\"ה</b>: ראה במדבר רבא פ\"ט, מד."],["1881","45","<b>ביום ההוא תקראי לי אישי</b>: הושע ב, יח."],["1882","46","<b>רשפיה רשפי אש</b>: שה\"ש ח, ו."]]],[2100490366,"וזהו כי עתה יאהבני אישי שיומשך בחי' אהבה וחסד עליון להיות ימינו תחבקני וכ\"ז מצד בחי' אתערותא דלתתא של בחי' ראוב\"ן כי ראה ה' בעניי שעי\"ז יאהבני אישי וכנ\"ל וד\"ל.\n<b>ותהר</b> <sup data-n=\"1883\">47</sup>עוד ותלד בן ותאמר כי שמע ה' כי שנואה אנכי ויתן לי גם את זה ותקרא שמו שמעון וגו'. הנה תחלה נולד ראובן שהוא בחי' הרצוא בהתלהבות באהבה רבה אליו ית' לאסתכלא ביקרי' דמלכא שזהו פר' ראשונה דק\"ש דכתיב ואהבת את ה' אלקיך בכל לבבך בשני יצריך ודגל מחנה ראובן תימנה וכן פני ארי' אל הימין וכנ\"ל ועתה אח\"כ הוא בחי' ההולדה דשמעון שהוא בחי' פרשה שני' דק\"ש דכתיב והיה<sup data-n=\"1884\">48</sup> אם שמוע תשמעו וגו' שהוא בחי' שמיעה וכדכתיב כי שמע ה' כי שנואה אנכי וגו' פי' ראי\"ה הוא מקרוב עד\"מ כשעומד לפני המלך מקרוב והוא מקורב אליו מרוא\"י פני המלך שאהוב ונחמד לו מקרבו בראי' פניו ממש אבל שמיעה הוא מרחוק ששומע מארץ מרחק שמעו של המלך ההולך בכל המדינות אבל אינו רואהו מקרוב ממש כך ממש עד\"מ למעלה ראיה הוא מקרוב ממש שהוא בחי' פני ארי' אותיות ראי\"ה אל הימין וכמ\"כ למטה הי' דגל מחנה ראובן תימנה שהוא בחי' הרצוא באהבה וחסד אליו ית' לאסתכלא ממש ביקרי' דמלכא שזהו בחי' ואהבת שבפ' ראשונה דק\"ש כנ\"ל, אבל שמיעה הוא מרחוק והיינו בחי' שמעון שהוא בחי' פרשה שני' דק\"ש דכתיב והיה אם שמוע תשמעו וגו', והוא בחי' השוב שלאחר הרצוא להשפיל א\"ע בבחי' שמאל דוחה למטה מטה בבחי' יראה ופחד עליו תפול לומר אמת כי חפץ אני ומשתוקק באהבה רבה לאסתכלא ביקרי' דמלכא כי קרבת אלקים לי טוב אך מי אנכי כי באתי עד הלום אשר ערב לבי לגשת אליו מצד פחיתות עצמו לזאת ישפיל א\"ע בבחי' שמאל דוחה למטה והיינו מ\"ש כי שמע ה' כי שנוא\"ה אנכי שמשפיל א\"ע בבחי' שמאל<sup data-n=\"1885\">49</sup> דוחה להמשיך יראה עליו לומר כי שנואה אנכי לו כו' ואינו ראוי לכך וזהו מ\"ש בפ' שניה דק\"ש השמרו<sup data-n=\"1886\">50</sup> לכם פן יפתה לבבכם וסרתם ועבדתם אלקים אחרים, ולאו דוקא קאמר על המומר הנושא צלם על צוארו ועע\"ז אלא אפי' כשהוא עובד ה' רק שיש בו גסות הרוח ששקולה כעע\"ז וכן כל<sup data-n=\"1887\">51</sup> הכועס כאלו עע\"ז וזהו וסרתם כו' והיינו שפר' שני' דק\"ש שהיא בחי' שמיעה מרחוק בחי' שמאל דוחה להמשיך בחי' יראה ופחד עליו מרחוק כדכתיב וירא<sup data-n=\"1888\">52</sup> העם וינועו ויעמדו מרחוק לכך נאמר בה בחי' גבורה וקצף באזהרת השמרו לכם כו' וחרה אף ה' בכם וגו' וכדכתיב ה'<sup data-n=\"1889\">53</sup> שמעתי שמעך יראתי שמן בחי' השמיעה שמרחוק יסתעף בחי' היראה לעמוד מרחוק שזהו בחי' השוב להשפיל א\"ע בשמאל דוחה בבחי' ריחוק למטה וזהו כי שמע ה' כי שנואה אנכי וגו' ותקרא שמו שמעון כנ\"ל וד\"ל.",[["1883","47","<b>ותהר עוד ותלד בן. . שמו שמעון</b>: ויצא כט, לג."],["1884","48","<b>והיה אם שמוע</b>: עקב יא, יג."],["1885","49","<b>שמאל דוחה</b>: ראה סוטה מז, א."],["1886","50","<b>השמרו לכם</b>: עקב יא, טז."],["1887","51","<b>כל הכועס כאלו עע\"ז</b>: כ\"ה בתניא אגה\"ת פ\"ז. אגה\"ק רסכ\"ה. וראה לקו\"ש חי\"ז ע' 20 הערה 33. וש\"נ."],["1888","52","<b>וירא העם וינועו</b>: יתרו כ, טו."],["1889","53","<b>ה' שמעתי שמעך</b>: חבקוק י, ב."]]],[2100490367,"<b>ותהר</b> עוד ותלד בן ותאמר עתה הפעם ילוה אישי אלי ותקרא שמו לוי וגו', פי' לוי הוא בחי' אמת ויציב שלאחר ק\"ש שהוא בחי' קבלת עול התורה והמצות עלינו ועל כל דורותינו ועל כל דורות זרע ישראל כו', בהיות ראובן<sup data-n=\"1890\">54</sup> ושמעון הם בחי' ימינא ושמאלא שהם שני הפכים ממש שראוב\"ן הוא בחי' הרצוא דואהבת שבפ' ראשונה דק\"ש<sup data-n=\"1891\">55</sup> ושמעון הוא בחי' השוב שבפ' שניה דק\"ש להשפיל א\"ע בשמאל דוחה למטה לומר כי שנואה אנכי ואינו ראוי לכך שעי\"ז מעוררי' למעלה ג\"כ בחי' שמאלו תחת לראשי וימינו תחבקני, ולוי הוא הממוצע ביניהם המחברן יחד והיינו שהוא בחי' גופא עמודא דאמצעיתא המחברן יחד שהוא בחי' התורה שנמשכת מקו האמצעי שכוללת שניהם יחד דהיינו למטה בעבודת<sup data-n=\"1892\">56</sup> ה' זו תפלה הוא בחי' אמת ויציב שלאחר ק\"ש שכולל ב' פרשיות דק\"ש בזה שמקבל עליו עול תורה ומצות באומרו אמת שאני מצד עצמי איני ראוי לכך כי שנואה אנכי אך דבריו חיים וקיימים הוא אשר שם בפי המדבר בד\"ת דכתיב ודברי<sup data-n=\"1893\">57</sup> אשר שמתי בפיך וגם שבזה נכללו הב' קוין דימינא ושמאלא דבחי' רו\"ש ביחד, וזהו (שכ' בפזמון<sup data-n=\"1894\">58</sup> של שבת של האריז\"ל) ימינא ושמאלא ובינייהו כלה פי' ימינא ושמאלא הם ב' אחים ראובן ושמעון ובינייהו כלה זהו לוי הממוצע ביניהם הכוללם יחד שהוא בחי' התקשרות לקשר מחשבתו במחשבתו של הקב\"ה בחכמתו ורצונו ודבורו בדבורו ומעשיו במעשה הצדקה להחיות<sup data-n=\"1895\">59</sup> רוח שפלים, שע\"י עסק התורה וג\"ח ימשיך מלמעלה בחי' התחברות והתקשרות של הקב\"ה עמו להיות נשפע ממנו גילוי אור א\"ס למטה כי התורה<sup data-n=\"1896\">60</sup> משולה למים הנגרים במורד מלמעלה למטה ממקום גבוה למקום נמוך וגם חסד נמשל למים נדמה כמ\"ש באאע\"ה זכור<sup data-n=\"1897\">61</sup> אב נמשך אחריך כמים מפני שע\"י תורה וג\"ח ימשיכו בחי' השפעת גילוי אור א\"ס ב\"ה שיומשך מלמעלה למטה וזהו עתה הפעם ילוה אישי אלי שע\"י תורה וג\"ח ילוה ויתקשר בחי' אישי הוא הקב\"ה שנאמר ביום ההוא תקראי לי אישי וגו' אלי ממש וזהו כמארז\"ל ע\"פ<sup data-n=\"1898\">62</sup> ולדבקה בו וכי אפשר להדבק בשכינה אלא הדבק במדותיו מה הוא רחום אף אתה רחום מה הוא חנון כו' שזהו בחי' ומדרגת לוי שילוה אישי אלי והוא בחי' אמת ויציב שבתפלה כנ\"ל וד\"ל.\n<b>ותהר</b><sup data-n=\"1899\">63</sup> עוד ותלד בן ותאמר הפעם אודה את הוי' ע\"כ קראה שמו יהודה ותעמוד מלדת. הנה זהו בחי' תפלה<sup data-n=\"1900\">64</sup> די\"ח ברכות שהיא בלחש וחשאי שהוא",[["1890","54","<b>ראובן ושמעון הם בחי' ימינא ושמאלא</b>: ראה כ\"ז באריכות תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] כא, ד. וארא פד, ג ואילך."],["1891","55","<b>דק\"ש. . אמת ויציב. . דימינא ושמאלא</b>: ראה פרי עץ חיים שער (ז) הק\"ש פכ\"ז וראה שם פ\"ד."],["1892","56","<b>בעבודת ה' זו תפלה</b>: ראה תענית ב, א."],["1893","57","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["1894","58","<b>בפזמון של שבת של האריז\"ל</b>: פיוט אזמר בשבחין (זמירות ליל שבת)."],["1895","59","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["1896","60","<b>התורה משולה למים. . למקום נמוך</b>: ראה תענית ז, א."],["1897","61","<b>זכור אב נמשך אחריך כמים</b>: פיוט גשם."],["1898","62","<b>ע\"פ ולדבקה בו וכי אפשר. . חנון</b>: עקב יא, כב. ספרי עקב עה\"פ. וראה רמב\"ם הל' דעות פ\"א ה\"ה. סהמ\"צ להרמב\"ם מ\"ע ח. שו\"ע אדה\"ז או\"ח סקנ\"ו, ס\"ג. וראה ג\"כ מכילתא בשלח טו, ב. שבת קלג, ב."],["1899","63","<b>ותהר עוד. . שמו יהודה</b>: ויצא כט, לה."],["1900","64","<b>תפלה די\"ח ברכות. . בלחש</b>: ראה תיקונים בזהר חדש קא, ג. זהר ויקהל רב, א. שו\"ע אדה\"ז הל' תפלה סק\"א, ס\"ב-ד. ניצוצי זהר לזהר ויגש רי, א."]]],[2100490368,"תכלית הביטול האמיתי בכריעות והשתחואות והודיה בהיות כל בחי' ומדרגת ג' אחין הנ\"ל הוא בחי' ג' קוין ימין ושמאל ואמצע שהם בחי' אהוי\"ר רצוא ושוב ובחי' עסק התורה ומצות הממוצע כנ\"ל שבבחי' אהוי\"ר לא ימצא עדיין בחי' תכלית הביטול האמיתי שהרי יש<sup data-n=\"1901\">65</sup> מי שאוהב והם ב' דברים האוהב והאהוב כו', וכן היראה כו', אבל יהודה הוא בחי' <sup data-n=\"1902\">66</sup>תכלית הביטול האמיתי בכריעה והשתחואה במודים אנחנו לך כו' שמתבטל לגמרי מכל וכל בהודיה זו עד שיעמוד בקול<sup data-n=\"1903\">67</sup> דממה דקה ותשוקה ממש דתמן<sup data-n=\"1904\">68</sup> קאתי מלכא בבחי' גילוי מלמעלה למטה ולכך התפלה היא בלחש וד\"ל. וזהו יהודה אתה יודוך אחיך פי' אתה<sup data-n=\"1905\">69</sup> הוא בחי' גילוי לנוכח כמאמר בתפלה ברוך אתה הוי' כו' שכאשר יומשך בחי' ההודיה דיהודה בבחי' אתה בגילוי בנפשו האלקית ממש א\"א בלתי שיודוך אחיך דהיינו שג' אחיו ראובן ושמעון ולוי הם ממשיכים ביהודה בחי' ההודיה זו שיהי' בו בבחי' גילוי בבחי' אתה והיינו למטה שא\"א להתחיל התפלה מש\"ע שימצא בו בחי' ההודיה וההשתחואה דש\"ע עד שיסדר התפלה דפסד\"ז וברכות יוצר ופ' ראשונה ושני' דק\"ש קודם לכן שזהו בחי' הכנה לעורר לבבו תחלה ברצוא ואח\"כ בשוב ואח\"כ לקבל עליו עול תורה וג\"ח באמת ויציב ואח\"כ יסתעף מזה אח\"כ בחי' ההודיה בכריעה והשתחואה בתכלית הביטול האמיתי שעולה על כולנה שבתפלה בלחש שהוא בחי' יהודה אתה שיודוך אחיך דוקא כנ\"ל וד\"ל.\n<b>ידך</b><sup data-n=\"1906\">70</sup> בעורף אויביך הנה כתיב כי<sup data-n=\"1907\">71</sup> פנה אלי עורף ולא פנים וגו' מפני שמצטרך להיות בהיפוך שיפנה אליו ית' בבחי' פנים ממש להתענג על ה' ית' בעבודת ה' זו תפלה ובעסק התו\"מ ואליו יהי' נושא את נפשו בבחי' פנים ממש ולעה\"ז לכל חפצו יהי' בבחי' עורף ואחוריים דהיינו שיעקור הרצון והתענוג מכל חפצי עה\"ז ויעשה אותם בהכרחי כאלו כפאו שד בלי הרגשת טוב טעם ונחת כלל, אך אף בחי' העורף עצמו אשר שם בענייני עה\"ז הכוונה בזה בכדי לברר בירורין שע\"י שיאכל מאכל ההוא כדומה יתחזק כחו בעבודת ה' בתפלה אח\"כ ויאריך באחד יותר שיוכלל המאכל ההוא באחד, וזהו ידך בעורף<sup data-n=\"1908\">72</sup> אויבך א\"ת יד\"ך אלא יודך שבחי' הי' דיהודה שהוא בחי' חכמה עילאה הוא מקיף אף את בחי' העורף של אויבך הם החצוני' והקליפות כל תאוות עה\"ז לאהפכא מחשוכא לנהורא להעלותן לקדושה ליכלל באחד כי בחכמה אתברירו דייקא, וגם פירושו כמשמעו ידך בעורף כו' דהיינו כמ\"ש",[["1901","65","<b>יש מי שאוהב</b>: ראה תניא פל\"ה (מד, סע\"א). פל\"ז (מח, סע\"א). תו\"א ויקהל (בהוספות) קיד, ד. ביאוה\"ז לאדמו\"ר האמצעי פא, א-ב. ועוד."],["1902","66","<b>יהודה. . ביטול</b>: ראה תו\"א ויגש מד, א. ושם ר\"פ ויחי. ובכ\"מ."],["1903","67","<b>בקול דממה דקה</b>: מלכים-א יט, יב."],["1904","68","<b>דתמן קאתי מלכא</b>: ראה זהר (רע\"א) פנחס רכז, ב. ת\"ז בהקדמה (ג, ב)."],["1905","69","<b>אתה הוא בחי' גילוי</b>: תו\"א בראשית א, ד. ויחי מה, ג. ואילך."],["1906","70","<b>ידך בעורף אויבך</b>: ויחי מט, ח."],["1907","71","<b>כי פנה אלי עורף</b>: ירמי' לב, לג."],["1908","72","<b>בעורף. . א\"ת ידך אלא יודך</b>: תהלים קלט, ח. וראה תקוני זהר בהקדמה ז, ב."]]],[2100490369,"וימינך<sup data-n=\"1909\">73</sup> פשוטה לקבל שבים וכתיב וירא<sup data-n=\"1910\">74</sup> ישראל את היד הגדולה אשר עשה ה' במצרים שנשפל ומתפשט היד עליון באורך והתפשטות מאד במורד למטה לברר ברורין בעורף אויבך וגם משמע ידך בעורף אויבך לגרש החצוני' להיות עי\"ז סר מרע בתכלית כדכתיב יפול<sup data-n=\"1911\">75</sup> מצדך אלף וגו' וד\"ל.\n<b>וישתחוו</b><sup data-n=\"1912\">76</sup> לך בני אביך, הנה נאמר אבינו אב הרחמן שהח\"ע נקראת בחי' אב הרחמן כרחם אב על בנים שהיא מקור החסדים ובני אביך זוהי התולדות של האב הרחמן והם בחי' תורה וגמ\"ח כמ\"ש שמע בני מוסר אביך זו<sup data-n=\"1913\">77</sup><sup data-n=\"1914\">78</sup> תשב\"כ ואל תטוש תורת אמך זו תשבע\"פ כמשל האב שמזריע טפה א' וממנו הולד נוצר בהרחבת אבריו בבטן האם כך התשב\"כ היא בקיצור מופלג שעל תיבה א' שבה נשנית מס' א' בתשבע\"פ כמו הל' שבת שנאמר מס' שבת ודומיהן וכמ\"כ ס'<sup data-n=\"1915\">79</sup> המה מלכות ושמונים פלגשים כנ\"ל וזהו וישתחוו לך בני אביך שהשתחואה הוא המשכה מלמעלה למטה כצורת הו' הנמשך באורך למטה שבחי' ההודיה דיהודה נסתעף מההשת[חואה] הוא ההמשכה דבני אביך הם תורה וג\"ח שנמשלו למים נדמו שהם בני אביך כנ\"ל וד\"ל.",[["1909","73","<b>וימינך פשוטה לקבל שבים</b>: תפלת נעילה."],["1910","74","<b>וירא ישראל את היד הגדולה</b>: בשלח יד, לא."],["1911","75","<b>יפול מצדך אלף</b>: תהלים צא, ז."],["1912","76","<b>וישתחוו לך בני אביך</b>: ויחי מט, ח."],["1913","77","<b>שמע בני מוסר אביך. . תורת אמך</b>: משלי א, ח."],["1914","78","<b>זו תשב\"כ. . זו תושבע\"פ</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תנ בשם הזהר. וש\"נ."],["1915","79","<b>ס' המה מלכות ושמונים פלגשים</b>: שה\"ש ו, ח. וראה זהר פנחס רטז, א."]]],[2100490370,"<h3>להבין שרשן של הדברים הנ\"ל</h3>\n<b></b><b>בעזה\"י וי\"ת יום א' פ' שמות באור על התורה הנ\"ל</b>\n<b>להבין</b><sup data-n=\"1916\">1</sup> שרשן של הדברים הנ\"ל, הנה כתיב ששם<sup data-n=\"1917\">2</sup> עלו שבטים שבטי י\"ה עדות לישראל להודות לשם הוי' וגו'. ונז' ע\"ז בזוהר שיש ב' בחי' שבטים, שבטים סתם הם מרכבתא תתאה בחי' י\"ב בקר שהים של שלמה מכסה עליהם מלמעלה שהם בחי' הנוק' דז\"א דאצי' שהיא מקור שנמשכי' ממנה י\"ב שבטים לראש הבריאה (כי שבט<sup data-n=\"1918\">3</sup> הוא לשון המשכה כמו כוכבא דשביט כו' כמ\"ש במ\"א)",[["1916","1","<b>להבין שרשן של הדברים הנ\"ל</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 2140 רכ, ב.\nהנחת כ\"ק אדמו\"ר האמצעי נדפס לעיל ע' רסא.\nהנחת המהרי\"ל נדפס לקמן ע' רפו."],["1917","2","<b>ששם עלו שבטים</b>: תהלים קכב, ד. ראה זהר פקודי רכט, ב. רל, א. ביאורי הזהר במדבר פה, ריש ע\"ד."],["1918","3","<b>שבט. . כוכבא דשביט</b>: ברכות נח, ב. ראה תו\"א ויצא כד, א. לקו\"ת במדבר ג, סע\"א ואילך. מאמרי אדה\"ז: תקס\"ב ס\"ע רלז ואילך (ועם הגהות — אוה\"ת מטות ע' א'רצד ואילך)־ תקס\"ג ח\"א ע' שט (ועם הגהות — אוה\"ת בשלח ע' שפט)־ תקס\"ד ע' יד. מאמרי אדמו\"ר האמצעי במדבר ח\"א ע' סז ואילך. ביאוה\"ז לאדמו\"ר האמצעי פה, א ולהצ\"צ חלק א' ע' תנא. אוה\"ת תצוה ע' א'תרסד. סה\"מ תער\"ב-תרע\"ו ע' קלא ואילך."]]],[2100490371,"וזהו שכתוב ששם עלו שבטים שהם בחי' העלא' מ\"ן שבו\"ק דאצי' שעולה מלמטה למעלה לז\"א דאצי', שבטי י\"ה הם שרש השבטים אלו שבמל' דאצי' ששר שרשם הוא בז\"א דאצי' שיש בחי' י\"ב שטים י\"ב מיני המשכות מז\"א דאצי' (שנק' י\"ב גבולי אלכסון בז\"א כמ\"ש בפרד\"ס<sup data-n=\"1919\">4</sup> ע\"ש) עלו כנגד דאלו שהי\"ב שבטים שלמטה בכו\"ק מעוררים בהעלא' מ\"ן שלהם מלמטה למעלה בחי' מ\"ד כיוצא בהן משרשן השבטי י\"ס שבז\"א דאצי' והיינו כמו שבט ראובן שבמרכבה שבמל' דאצי' שהוא פני<sup data-n=\"1920\">5</sup> ארי' אל הימין כמ\"ש דגל<sup data-n=\"1921\">6</sup> מחנה ראובן תימנה וגם שנמשך בקו ימין חח\"ן דאצי' בחי' חסד שבמל' דאצי' שמעלה מ\"ן בבחי' רצוא ואהבת חסד מלמטה למעלה אליו ב\"ה לאסתכלא<sup data-n=\"1922\">7</sup> ביקר דמלכא שהוא בחי' ארי\"ה<sup data-n=\"1923\">8</sup> אותיות ראי\"ה שהראיה היא מקרוב דוקא שהוא בחי' אהבה והתקרבות שמתקרב אליו ב\"ה באהבה וחסד להיות נמשך אחריו כמים לאסתכלא ביקרי' דמלכא בבחי' ראיה וקרבת אלקים אליו ממש כמ\"כ ע\"י ההעלאת מ\"ן והרצוא של שבט ראובן מלמטה במרכבה תתאה מעורר בחי' מ\"ד כיוצא בו ממש משרשו בחי' שבט ראובן שבשבטי י\"ה דז\"א דאצי' להיות נמשך אליו ע\"ד ממדת החסד דז\"א דאצי' באהבה והתקרבות של אלקים אליו בבחי' ראיה מקרוב ממש וז\"ש ותהר לאה ותלד בן ותקרא שמו רא\"ו ב\"ן כי אמרה כי ראה ה' בעניי כי עתה יאהבני אישי וגם פי' שבראובן שלמטה שהוא בחי' ראי' והתקרבות באהבה וחסד אליו ב\"ה לאסתכלא ביקרי' כו' ממשיך מ\"ד משרשו מבחי' ראובן שבשבטי י\"ה דז\"א אליו וזהו כי ראה ה' בעניי כי עתה יאהבני אישי הוא בחי' הע\"ד דז\"א הנק' אישי כדכתיב ביום<sup data-n=\"1924\">9</sup> ההוא תקראי לי אישי וגם שהוא בעלה דו\"ק דאצי' שנמשך ממנו בחי' הראיה וההתקרבות באהבה וחסד עליון היורד מלמעלה למטה וכמ\"ש כבכורה<sup data-n=\"1925\">10</sup> בתאנה בראשיתה ראיתי אבותיכם וגו' שהוא ההארה וההתקשרות דאיש העליון מלמעלה למטה משרשו של ראובן שבשבטי י\"ה שיורד אל ראובן שלמטה בנוק' דז\"א וזהו כי עתה יאהבני אישי וד\"ל. וכמשנת\"ל (בתורה) שראובן הוא בחי' פרשה ראשונה דק\"ש שנאמר ואהבת את ה' אלקיך וגו' וע\"י אתערותא דלתתא מעורר אתערותא דלעילא הע\"ד דראובן שבשבטי י\"ה בחי' הראי' וההתקרבות באהבה מלמעלה למטה וזהו כי ראה ה' בעניי וגם וכתיב וראיתי אבותיכם וזהו כי עתה יאהבני אישי וד\"ל שהוא בחי' וימינו תחבקני וד\"ל.\n[",[["1919","4","<b>כמ\"ש בפרד\"ס</b>: שער (כא) פרטי השמות פ\"ו-ח."],["1920","5","<b>פני ארי' אל הימין</b>: יחזקאל א, י."],["1921","6","<b>דגל מחנה ראובן</b>: במדבר ב, י."],["1922","7","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א."],["1923","8","<b>אריה אותיות ראיה</b>: מגלה עמוקות אופן קג וביאורי הזהר שם. ראה תקו\"ז קכב, א."],["1924","9","<b>ביום ההוא תקראי לי אישי</b>: הושע ב, יח."],["1925","10","<b>כבכורה בתאנה</b>: הושע ט, י."]]],[2100490372,"<h3>נוסח שלישי: ביאור יהודה אתה</h3>\n<b></b><b>ביאור על הנ\"ל<sup data-n=\"1926\">1</sup> </b>\n[ביאור יהודה אתה]\nהנה שבטים<sup data-n=\"1927\">2</sup> הם שבטי י\"ה ב' בחי' ממטה למעלה ומלמעלה למטה עלמא דנוק' ועלמא דדכורא ובאתערות' דלתת' אתערות' דלעילא ע\"י ראובן ראיי' פני ארי' ראיתי את אבותיכם התקרבות ממשיך מלמעלה ראה ה' בעניי כי<sup data-n=\"1928\">3</sup> עתה יאהבני אישי וימינו תחבקני ושמיעה אם<sup data-n=\"1929\">4</sup> שמע תשמעו מעורר מלמעלה כך כי ה' וענין ראי' מקרוב ושמיעה מרחוק ה'<sup data-n=\"1930\">5</sup> שמעתי שמעך יראתי בבחי' אודנין כי חבקוק היה בבחי' ריחוק בבחי' שוב מחמת כי ירא לגשת כענין וירא<sup data-n=\"1931\">6</sup> העם וינועו ויעמדו מרחוק כנ\"ל וזהו כי שמע ה' כי שנואה אנכי ויתן לי בן שמזה נולד בחי' התקרבות למעלה בחי' שוב שלמטה (ושנואה היינו שאינה אהובה כ\"כ שהרי כתיב ויאהב גם כו' שעושה עצמו שנואה שמאל<sup data-n=\"1932\">7</sup> דוחה ושמאל זה גורם תחת לראשי כו' ונולד מזה בחי' לוי בחי' אוי\"צ ודבריו חיים וקיימים על אבותינו ועלינו כו' והם ג' קוין חח\"ן בג\"ה וקו האמצעי לוי דת\"י שעי\"ז יודוך אחיך להיות בחי' הודאה כתר מל' שבמל' הוא מקבל דלית לה מגרמה כלום וצריכה המשכה להיות הם ממשיכים לה ואעפ\"כ היא בחי' מל' כמשל מלך ב\"ו שהוא מקבל ואעפ\"כ הוא מלך על הנותנים כו' כך כתר עליון הוא כתר מל' נעוץ<sup data-n=\"1933\">8</sup> תחילתן בסופן וסופן בתחילתן ואעפ\"כ צריכה המשכה מכתר עליון דאיהו<sup data-n=\"1934\">9</sup> טמירו דכל טמירין להיות בגלוי אתה ולכן יודוך אחיך מכתר דמל' דהיינו ע\"י ג' קוין הנ\"ל ראובן פ' ראשונה דק\"ש שם מ\"ב ושמעון פ' שניי' שם ע\"ב ולוי אמת ויציב בחי' הממוצע ובהיכלות הוא היכל הרצון (שהיכל ק\"ק הוא אדני שפתי תפתח סמיכות<sup data-n=\"1935\">10</sup> גאולה לתפלה) שהוא למעלה מהיכל אהבה שקודם ק\"ש כו' ויודוך אחיך להיות בחי' ההודאה בבחי' כתר הוא ביטול ותעמוד מלדת אין עמיד' כו' כי אהב' הוא יש בחי' ידיך<sup data-n=\"1936\">11</sup> בעורף אויבך עורף דווקא שהפנימי' צ\"ל סו\"מ כו' וכך הנה המל' יש לה עליות וירידות הפעם אודה כו' שבשחרית כך ובמנחה כך ובשבת ומוסף כו' ובלילה ותתן<sup data-n=\"1937\">12</sup> טרף לביתה לברר בירורין ומלכותו בכל משלה ואין בירור אלא בבחי' אחוריים כי הפנימי' ממילא נכלל כנר בפני אבוקה וכנודע מויברך<sup data-n=\"1938\">*12</sup> יעקב את פרעה דא ההוא סטרא קטיל ואפיק נשמתא כו' שיורד ומסטין",[["1926","1","<b>ביאור על הנ\"ל (יהודה)</b>: הנחת המהרי\"ל. נעתק מכת\"י 1824 יא, ב. 1805 קעג, ב. ונעתק בשינויים בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ 1116 פז, א.\nנדפס בתוס' הגהות באוה\"ת בראשית ע' תתשמ בהשמטת קטע האחרון. ובשינויים קלים בתו\"א ויחי מה, ד.\nנאמר ביום א' פ' שמות תקס\"ו.\nוראה לעיל ע' רסא, וע' רפד."],["1927","2","<b>שבטים הם שבטי י\"ה</b>: ראה תהלים קכב, ד."],["1928","3","<b>כי עתה יאהבני אישי</b>: ויצא כט, לב."],["1929","4","<b>אם שמע תשמעו</b>: עקב כח, א."],["1930","5","<b>ה' שמעתי שמעך</b>: חבקוק ג, ב."],["1931","6","<b>וירא העם וינועו</b>: יתרו כ, טו."],["1932","7","<b>שמאל דוחה</b>: ראה סוטה מז, א."],["1933","8","<b>נעוץ תחלתן בסופן</b>: ס\"י פ\"א מ\"ז."],["1934","9","<b>דאיהו טמירו דכל טמירין</b>: ראה זהר יתרו פט, א."],["1935","10","<b>סמיכות גאולה לתפלה</b>: ראה ברכות ח, א."],["1936","11","<b>ידיך בעורף אויבך</b>: ויחי מט, ח."],["1937","12","<b>ותתן טרף לביתה</b>: משלי לא, טו."],["1938","*12","<b>ויברך</b>: ראה לעיל ע' רמה ואילך."]]],[2100490373,"ועולה ומקטרג שלא די במה שלוקח נשמתו אלא גם הגוף וכמו גזלן שנוטל הנשמה והורג הגוף ג\"כ כו' ולא די בהעלאת הנשמה בלידת הרבה ישראל אלא גם את רוח<sup data-n=\"1939\">13</sup> הטומאה אעביר כו' ובלע<sup data-n=\"1940\">14</sup> המות לנצח וכדי שיהי' כח לזאת הוצרך להיות ויברך יעקב כו' ישתחוו לך בני אביך המשכת אבא כי אבא<sup data-n=\"1941\">15</sup> יסד ברת' ויודוך אחיך היינו המשכת הכתר ע\"י ג' קוין משא\"כ המשכת החכמה הוא ע\"י ב' קוין בלבד כנודע מציור והצינורות כו' והם ראובן ולוי אב הרחמן המשכת חח\"ן קו ימין ע\"י גמ\"ח והמשכת קו הממוצע ע\"י תורה נובלות<sup data-n=\"1942\">16</sup> חכמה שלמעלה תורה.\n<b>וביאור</b> הענין כי ראה ה' בעניי כי הנה ענין בע\"ת הוא ענין הבירור כי הבירורים הם לברר ולהעלות מפני שהיתה תחילה במקם גבוה וירדה ואח\"כ הוצרכה לעלות למקומה וכן הנשמה שירדה בגוף וצריך להעלות' נק' ג\"כ תשובה כי בירור ותשובה הכל ענין אחד, והנה התקרבות שמחמת עניי הוא יותר גדול כיתרון<sup data-n=\"1943\">17</sup> אור הבא מן החשך שלכן הם הברורים שבטי יה או\"א עדות לישראל מלמעלה למטה להודות לשם הוי\"ה פי' לעשות בחי' הודאה בשם ה' כנ\"ל.",[["1939","13","<b>את רוח הטומאה אעביר</b>: זכרי' יג, ה."],["1940","14","<b>ובלע המות לנצח</b>: ישעי' כה, ח."],["1941","15","<b>אבא יסד ברתא</b>: זח\"ג רמח, ב. רנו, ב. ועוד."],["1942","16","<b>נובלות חכמה שלמעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["1943","17","<b>כיתרון אור הבא מן החושך</b>: ע\"פ קהלת ב, יג."]]],[2100490374,"<h3>הטוב שמך ולך נאה להודות</h3>\n<b></b><b>בעזרה\"י ליל ש\"ק פ' בשלח (תקסוואוו)</b>\nליל ש\"ק פ' בשלח\n<b>הטוב</b><sup data-n=\"1944\">1</sup> שמך ולך נאה להודות<sup data-n=\"1945\">2</sup>, פי' טו\"ב<sup data-n=\"1946\">3</sup> הוא בחי' יסוד בכ\"מ שהוא בחי' צדיק העליון דכתיב אמרו<sup data-n=\"1947\">4</sup> צדיק כי טוב וגו' שמ\"ך היא מדת מלכותו ית' המחי' את כל עולמים והיא מקבלת השפע מיסוד ז\"א שנק' בחי' טוב שהוא הטוב והמטיב להשפיע השפע עליונה לתוכה והיא מתלבשת בתוך כל עלמין בבחי' התלבשו' ממש להוותם כדכתיב מלכותך<sup data-n=\"1948\">5</sup> מלכות כל עולמים וגו', שהוא בחי' הודו<sup data-n=\"1949\">6</sup> על ארץ ושמים שממלא כ\"ע להחיותם והוא בחי' שמו ית' בלבד כמשל השם של האדם שאינו רק",[["1944","1","<b>הטוב שמך ולך נאה להודות</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (רלז, א).\nהנחת כ\"ק אדמו\"ר האמצעי נמצא בכת\"י 1001. בהתחלה ”אין קדוש כהוי'\", נדפס בסה\"מ תקס\"ה ע' שג."],["1945","2","<b>הטוב שמך ולך נאה להודות</b>: תפלת העמידה."],["1946","3","<b>טוב הוא בחי' יסוד</b>: ראה זהר נח ס, א. בראשית ל, ב. תרומה קכח, ב. ובהגהות מהרח\"ו שם. ויקרא כא, ב. בהעלותך קנ, א ובהגהות מהרח\"ו שם. וראה שערי אורה שער החנוכה ד, ב. שער הפורים פו, א. מאמרי אדה\"א קונטרסים ע' רכד."],["1947","4","<b>אמרו צדיק כי טוב</b>: ישעי' ג, י."],["1948","5","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["1949","6","<b>הודו על ארץ ושמים</b>: תהלים קמח, יג."]]],[2100490375,"הארה בעלמא כו' וזהו הטוב שמך שמבחי' טוב העליון דצדיק עליון נשפע בבחי' שמ\"ך ושמ\"ך הוא הממכ\"ע להחיותם להתהוות עולמו' הנפרדים נבראים רבים פרטיים מינים ממינים שונים אשר לגדולתו אין מספר ואבל מהותו ועצמותו מרומם לבדו ומתנשא מימות עולם עד שאין לו ערוך אליו כלל ולכך ול\"ך נאה להודות פי' ול\"ך אל בחי' מהותו ועצמותו ית' נאה להודו\"ת להיות בבחי' הביטול תמיד אליו ולא למידותיו בבחי' הודאה בלבד כי<sup data-n=\"1950\">7</sup> לית מחשבה תפיסא בי' וכו' מצד ההתבוננו' אשר החיות של כל עולמים הוא רק מבחי' שמך הטוב בלבד כנ\"ל וד\"ל וזהו הכל<sup data-n=\"1951\">8</sup> יודו\"ך והכל ישבחוך וכו' כנ\"ל וד\"ל.\n<b>והכל</b> יאמרו אין קדוש כהוי\"ה וגו', פי' כי ישראל נק' קדושי' דכתיב קדושים<sup data-n=\"1952\">9</sup> תהיו ואר\"ז יכול כמוני ת\"ל כי קדוש אני הוי' קדושתי למעלה מקדושתכם כו'. והענין דהנה יש כמה בחי' ומדרגו' בבחי' קודש העליון כדכתיב ואתא<sup data-n=\"1953\">10</sup> מרבבות קדש כו' וכמ\"ש<sup data-n=\"1954\">11</sup> בזהר ע\"פ אין קדוש כהוי' כמה קדישין אינון לעילא ישראל אקרון קדישין כו' ובכלהון אין קדוש כהוי' כו' ע\"ש. והכונה בזה בהיות ידוע שקדו\"ש<sup data-n=\"1955\">12</sup> הוא לשון מובדל שהוא בחי' התנשאות והבדלה מערך ההתלבשו' בהכלים שאינו נתפס ומלובש בתוך הכלים להיותו ממולא בתוכם ממש כ\"א הוא סובב ומקיף עליהם מלמעלה כו' (וזהו הכלל בכ\"מ שנז' תיבת קדוש שהוא לשון הפרשה והבדלה כמו בנזיר נאמ' קדוש<sup data-n=\"1956\">13</sup> יהי' כו' וכן בישראל קדושי' תהיו מובדלי' תהיו כו') ולזאת כל המקיפי' עליוני' נק' בשם קדוש, ולז\"א הכתוב אין<sup data-n=\"1957\">14</sup> קדוש כהוי' פי' ש' הוי' הוא מקור החיים של כל סדרי ההשתלשלות שע\"ז מורי' ד' אותיו' דשם הוי\"ה י'<sup data-n=\"1958\">15</sup> הוא צמצום השפע ה' התפשטות וי\"ו המשכה כו' שמורה על המשכת השפע והחיים בכל סדרי ההשתלשלות מריש כל דרגין עד סוף כל דרגין כו' וזהו הפלאתו אשר אף שהוא בחי' הויה המהוה את הכל ומחי' את כולם והי' מצטרך להיות מלובש בתוכם, אעפ\"כ הוא קדוש ומובדל מהם להיותו סכ\"ע בבחי' מקיף ואעפ\"י שהוא קדוש ומובדל מהם אעפ\"כ הוא מהוה ומחיה את כולם ואעפ\"י שזה ב' הפכיי' ומנגדים זל\"ז אין סותרי' זא\"ז שיתקיימו שניהם שהוא קדו\"ש והוא הוי\"ה וזהו אין קדוש כהוי\"ה שבחי' קדוש כזה לא נמצא בכל סדרי ההשתלשלות בכמה בחי' קדישין אית לעילא ישראל אקרון קדישין ומלאכים אקרון קדישין כו' ובכולהון אין קדוש כהוי\"ה מפני שבכל סדרי ההשתלשלות מציא' בחי' הקדו\"ש כמו המלאכים וישראל שלמטה כיון",[["1950","7","<b>כי לית מחשבה תפיסא בי'</b>: ראה ת\"ז בהקדמה (יז, א)."],["1951","8","<b>הכל יודוך והכל ישבחוך</b>: תפלת שחרית לשבת."],["1952","9","<b>קדושים תהיו וארז\"ל יכול כמוני ת\"ל כי קדוש אני הוי'</b>: ויקרא יט, ב. ויקרא רבא פכ\"ד, ט. ראה מאמרי אדה\"א בראשית ע' רכו. וש\"נ. שמות ח\"ב ע' תקצד."],["1953","10","<b>ואתא מרבבות קדש</b>: ברכה לג, ב."],["1954","11","<b>וכמ\"ש בזהר ע\"פ אין קדוש כהוי' כמה קדישין אינון לעילא</b>: ראה זהר ויקהל מד, א."],["1955","12","<b>שקדוש הוא לשון מובדל</b>: ראה רש\"י ותו\"כ ר\"פ קדושים. תניא כמצוין במפתח ענינים בערך קדושה."],["1956","13","<b>קדוש יהי'</b>: במדבר ו, ה."],["1957","14","<b>אין קדוש כהוי'</b>: שמואל-א ב, ב."],["1958","15","<b>י' הוא צמצום</b>: ראה אגרת התשובה פרק ד."]]],[2100490376,"שהם קדושי' ומובדלים לא ימצא בהם בבחי' זו ההפכי בחי' ההתפשטות והאחדות בדבר זה שהם קדושים ומובדלים ממנה (כמו ישראל<sup data-n=\"1959\">16</sup> קדושים הם ומובדלי' מאומות להיות לו לעם סגולה שלא יתכן בהם ההיפך להתערב בגוים מאחר שהם מובדלי' מהם וכן הנזיר קדו\"ש ומובדל ומופרש הוא מן היין אינו מתחבר עם היין כו' וכיוצא בזה) משא\"כ למעלה בעצמו' אור א\"ס ב\"ה הסכ\"ע המתנשא מימות עולם שהוא קדוש ומובדל מסדרי ההשתלשלות שאין ערוך אליו ולית מחשבה תפיסא ביה כלל ואעפי\"כ איהו תפיס בכלהו עלמין ומהוה אותם ומחי' את כולם ולית מאן דתפיס בי' שנסבלו ב' הפכיי' אלו כא' להיותו קדוש והוי' ואין סותרים זא\"ז וכמ\"ש בע\"ח שעיקר החיות הוא מבחי' המקיף דוקא שמצחצח הכלי מבחוץ כו' ולזאת אין קדו\"ש כהוי' כנ\"ל וד\"ל.\n<b>וביאור</b> הענין דהנה נז' בלק\"א ח\"א (פ' מ\"ח ד' ס\"ח וד' ס\"ט ע\"ב) עמ\"ש<sup data-n=\"1960\">17</sup> הרמב\"ם ז\"ל הוא היודע והוא הידוע והוא המדע כי בידיעת עצמו יודע כל הנבראי' כו' כמו האדם שמצייר בדעתו איזה דבר שראה או שרואה הנה אף שגוף העצם הדבר ההוא כו' מצוייר בדעתו ומחשבתו כו' נק' דעתו מקפת הדבר ההוא כו' עד הרי ידיעה זו מאחר שהיא בבחי' א\"ס אינה נק' בשם מתלבשת כו' אלא מקפת וסובבת אף שידיעה זו כוללת כל עוביו ותוכו בפ\"מ ומהוה אותו עי\"ז מאין ליש כו' ע\"ש.\n<b>והענין</b> דהנה מבשרי<sup data-n=\"1961\">18</sup> אחזה אלו\"ה דכמו עד\"מ בנפש האדם נראה בעליל לארץ שבבחי' הדעת של האדם מתהוה מאין ליש דהיינו כמארז\"ל אין<sup data-n=\"1962\">19</sup> קשוי אלא לדעת כו' שכאשר יסיח דעת לא יומשך הטפה וע\"י הדעת נמשכת הטפה מן המוח הרוחניי להתגשם בבחי' הגשמה מאין ליש ממש ולהיות נוצר מזה הולד המחודש מאין ליש ממש ויש בהידיעה זו בחי' כח אין סוף ממש שמוליד בנים והבנים מולידי' בני בנים עד סוף כל הדורות מכ\"ש וק\"ו ואעכו\"כ בידיעתו של המאציל ב\"ה שבידיעת עצמו ית' שיודע כל הנבראים וסובב כ\"ע ומקיף אותם שבידיעה זאת עצמה הוא מחי' את כולם ומהוה אותם מאין ליש ואדרבה עיקר החיות של כ\"ע הוא מבחי' הסובב והמקיף דוקא, ואעפי\"כ הוא סובב ומקיף שאינו מלובש תוך כ\"ע כ\"א מקיף אותם כו' דאיהו תפיס בכולהו עלמין ולית מאן דתפיס בי\"ה כלל כנ\"ל, וזהו אין קדו\"ש כהוי\"ה שהוא קדו\"ש בבחי' סובב ומקיף ובזה עצמו ממש הוא עיקר ההוי\"ה המהוה כ\"ע ומחי' אותם תמיד מה שלא נמצא כזאת זולתי בו ית', וזהו קדושים תהיו יכול כמוני ת\"ל כי קדוש אני הוי\"ה קדושתי למעלה מקדושתכם כו' וכנ\"ל וד\"ל.",[["1959","16","<b>ישראל קדושים הם</b>: ראה נדה יז, א. חולין ז, ב."],["1960","17","<b>עמ\"ש הרמב\"ם הוא היודע</b>: הל' יסודי התורה פ\"ב ה\"י."],["1961","18","<b>מבשרי אחזה אלו\"ה</b>: לשון הפסוק איוב יט, כו."],["1962","19","<b>אין קשוי אלא לדעת</b>: יבמות נג, סע\"ב."]]],[2100490377,"<h3>[אדון הנפלאות] אשירה לה' כי גאה גאה</h3>\n<b></b><b>ביאור<sup data-n=\"1963\">1</sup> מאדומ\"ו על תורה שע\"פ אשירה לה' כי גאה גאה, בשלח תקס\"ו</b>\nבשלח\n<b>אדון</b><sup data-n=\"1964\">2</sup> הנפלאות הוא בחי' סוכ\"ע פלא התחלת האצי' כתר חכמה ואדון הנפלאות היינו מל' דא\"ס והמחדש בטובו היינו בחי' ממכ\"ע כי השגת הנשמה היא רק בבחי' ממכ\"ע וע\"י תורה ומצות נעשה גילוי סוכ\"ע שלמעלה מבחי' ההשתלשלות היינו ע\"י סוס<sup data-n=\"1965\">3</sup> ורוכבו רמה בים הפך<sup data-n=\"1966\">4</sup> ים ליבשה שינוי סדר כו' סוס הם האותיות שמושכים את הרוכב כו' והרוכב הם המדות של האורות זו היא בחי' צדקה המשכת אורות בכלים והיינו בחי' המתקת גבורות בחסדי' וצדיק ממשיך ה\"ח לצדק<sup data-n=\"1967\">5</sup> מלכותא<sup data-n=\"1968\">6</sup> קדישא דלית לה מגרמה כלום לך<sup data-n=\"1969\">7</sup> הוי' הגדולה כו' בבחי' ביטול וה\"ח אלו כמשל חיות הנשמה באברים שהחיות הוא חסד כו' וכ\"ז הוא כי סוס ורוכבו רמה בים בעתיקא<sup data-n=\"1970\">8</sup> תליא מילתא מה תצעק אלי אלא תחרישון למעלה מאותיות ואין שם תפילה אלא שתיקה ואלא הצדקה היא דרך הוי' מי\"ג מדות הרחמים שהם מקור האצי' שהם מבחי' שלמעלה מן האצי' להיות הוי' אצי' כו' יו\"ד חכמה כו' ובאמת אנת<sup data-n=\"1971\">9</sup> חכים ולא בחכמה ידיעא כו' אנת הוא מבין כו' ומחמת רחמנות יותר מזבוב כו' וכמאמר והמתנשא<sup data-n=\"1972\">10</sup> מימות עולם ברחמיך הרבים ומשפט מזיגות חסד ודין כי יש דין ע\"ע במותרות ועי\"ז ממשיך משפט כי לפי שהוא שוה ומשוה הי' יניקה כו' עבדי'<sup data-n=\"1973\">11</sup> היינו לפרעה מותרות צפרניים כו' וצריך להיות המשכת משפט בוצינא דקרדינותא ע\"י אתדל\"ת.\nב) <b>ועי\"ז</b> אשירה<sup data-n=\"1974\">12</sup> להוי' להיות התפשטות החיות וגילוי הוי' כי עד<sup data-n=\"1975\">13</sup> שלא נברא העולם הי' הוא ושמו לבד בבחי' העלם ועתה אשירה שיהי' גילוי ע\"י סוס ורוכבו רמה בים רמה ב' פי' רוממות והשלכה שלפי שהוא סוכ\"ע מעלה ומטה שוים",[["1963","1","<b>ביאור. . תקס\"ו</b>: תיבות אלו הם בכי\"ק אדמו\"ר הצ\"צ."],["1964","2","<b>אדון הנפלאות</b>: ברכת יוצר — הנחת כ\"ק אדמו\"ר האמצעי.\nהנחת המהרי\"ל נדפס בתו\"א בשלח סב, ד (ד\"ה ”אשירה לה' כי גאה גאה\"). הגהות על המאמר נדפס באוה\"ת בשלח ע' קתט-תקכב.\nהמאמר באריכות מכ\"ק אדמו\"ר האמצעי נדפס בתו\"ח בשלח [הוצאת קה\"ת — תשס\"ג] קסד, א. ובמאמרי אדמו\"ר האמצעי בשלח ע' קח-קלג.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז על פרשיות התורה ע' תתקיא.\nהגהות על הביאור נדפס באוה\"ת בשלח כרך ח ע' ב'תתקסא."],["1965","3","<b>סוס ורוכבו רמה בים</b>: בשלח טו, א."],["1966","4","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["1967","5","<b>לצדק מלכותא קדישא</b>: הקדמת תקוני זהר יז, ב."],["1968","6","<b>מלכותא. . דלית לה מגרמא כלום</b>: ע\"ח שער (ו) העקודים פ\"ו. שער (ח) דרושי הנקודות ספ\"ד. שער (לו) מיעוט הירח רפ\"א. שער (מב) דרושי (כללות) אבי\"ע ספי\"ג. וראה אור החמה לזוהר ויחי רמט, ב. מאמרי אדה\"ז הקצרים ע' תקא."],["1969","7","<b>לך ה' הגדולה</b>: דברי הימים א כט, יא."],["1970","8","<b>בעתיקא. . מה תצעק אלי. . תחרישון</b>: ראה בשלח יד, טו. יד. זהר בשלח מח, א."],["1971","9","<b>אנת חכים. . מבין</b>: ראה תקוני זהר בהקדמה יז, ב."],["1972","10","<b>והמתנשא. . ברחמיך הרבים</b>: ברכת יוצר."],["1973","11","<b>עבדי' היינו לפרעה</b>: נוסח ההגדה."],["1974","12","<b>אשירה לה'</b>: בשלח טו, א קודם התיבות (כי גאה גאה) סוס ורוכבו."],["1975","13","<b>עד שלא נברא העולם</b>: ראה הנסמן במאמרי אדה\"ז על פרשיות התורה לע' תקעב."]]],[2100490378,"יצדק בו מעלה ומטה גם רמה רוממות העלאה ורמה השלכה היא המשכה מלמעלה למטה ועי\"ז עזי<sup data-n=\"1976\">14</sup> וזמרת יה שיהי' בחי' אותיות הוי' זמרת מלשון זמיר<sup data-n=\"1977\">15</sup> עריצים שהוא ענין קצירה להיות נקשר בחי' אותיות מא\"ס והיינו עזי בחי' גבו' כו' ואח\"כ זה<sup data-n=\"1978\">16</sup> אלי זה<sup data-n=\"1979\">17</sup> קוינו לו קוין יו\"ד קוצא לעילא וקוצא לתתא ויהי<sup data-n=\"1980\">18</sup> לי לישועה גאולה מי\"ג מדות רחמים שזהו דוקא באתערותא דלתתא לעורר רחמים שלפיכך ירדה הנשמה ששם הי' לה דו\"ר כו' אך בחי' רחמנות הוא דוקא בהתלבשותה בגוף שעי\"ז עזי וזמרת יה שע\"ז מזל נוצר ונקה אבא<sup data-n=\"1981\">19</sup> יונק כו' ואמא כו' וצ\"ל סוס ורוכבו שגם הסוס צ\"ל רמה בים שגם הסוס אינו יכול לילך לשם שהוא למעלה מבחי' אותיות אך דוקא סוס דקדושה משא\"כ סוס<sup data-n=\"1982\">20</sup> פרעה טובעו<sup data-n=\"1983\">21</sup> בים סוף וישב<sup data-n=\"1984\">22</sup> ה' עליהם את מי הים אלא סוס ורוכבו דקדושה כו' וד\"ל.",[["1976","14","<b>עזי וזמרת יה</b>: בשלח טו. ב."],["1977","15","<b>זמיר עריצים</b>: ישעי' כה, ה."],["1978","16","<b>זה אלי</b>: המשך הכתוב עזי וזמרת."],["1979","17","<b>זה קוינו לו</b>: ישעי' כה, ט."],["1980","18","<b>ויהי לי לישועה</b>: המשך הכתוב עזי וזמרת (קודם זה אלי)."],["1981","19","<b>אבא יונק</b>: ראה ע\"ח שער (יג) א\"א ספ\"ט. שער (יד) או\"א ספ\"ח. שער (טו) הזיווגים ספ\"ב. שער (טז) הולדת או\"א וזו\"נ פ\"ו. שער (כח) העיבורים פ\"ב. שער (כט) הנסירה ספ\"ג."],["1982","20","<b>סוס פרעה</b>: בשלח יד, כג."],["1983","21","<b>טובעו ביום סוף</b>: בשלח טו, ד."],["1984","22","<b>וישב ה' עליהם</b>: בשלח טו, יט."]]],[2100490379,"<h3>יונתי בחגוי הסלע</h3>\n<b></b><b>(בעז\"ה שבת פ' משפטים תקס\"ו לפ\"ק)</b>\nשבת פ' משפטים\n<b>יונתי</b><sup data-n=\"1985\">1</sup> בחגוי הסלע<sup data-n=\"1986\">2</sup> בסתר המדריגה, הנה פסוק<sup data-n=\"1987\">3</sup> זה נא' על הגלות דכשכנ\"י היא בגלות אזי הוא בחגוי הסלע כו' כי הנה בזמן יציאת מצרים אמר תחלה כי<sup data-n=\"1988\">4</sup> הנה הסתי\"ו עבר הגשם חלף כו' ולכך קומי<sup data-n=\"1989\">5</sup> לך רעייתי יפתי כו', והנה פי' רעייתי<sup data-n=\"1990\">6</sup> מלשון רועה שזן ומפרנס כידוע היינו בחי' לחמה של תורה כמ\"ש לכו<sup data-n=\"1991\">7</sup> לחמו בלחמי",[["1985","1","<b>יונתי</b>: מאמר זה נסמן במפתח גוכתי\"ק אדהצ\"צ 1025: יונתי בחגוי הסלע דף א. אבל התחלת המאמר מדף א חסר שם בגוכתי\"ק והכת\"י מתחיל מדף ב'. המאמר נעתק כאן (בשלימות) מכת\"י: 420 פה, ב בכותרת: בעז\"ה שבת פ' משפטים, תקס\"ו לפ\"ק. [הסיום נמצא ג\"כ בגוכתי\"ק אדמו\"ר האמצעי 1025 ב, א].\nהנחת המהרי\"ל נדפס בלקו\"ת שה\"ש טז, ג בתוס' הגהות (וראה שם ברשימת הכתבי יד). ראה ג\"כ מאמרי אדה\"ז כתובים ח\"ב ע' קטז. קיצורים לנוסח הלקו\"ת נדפס באוה\"ת שה\"ש ע' שנג.\nבכת\"י 2045 צא, א נמצא נוסח הלקו\"ת (בלי הגהות), אבל הביאורים שם הם כמו הנחת כ\"ק אדה\"א (ראה לקמן בהביאורים).\nבכמה כת\"י רשום על נוסח הלקו\"ת: ”בשקלאב הבירה\"."],["1986","2","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד."],["1987","3","<b>פסוק זה. . היא בגלות</b>: בלקו\"ת שם יש הג\"ה מכ\"ק אדמו\"ר הצ\"צ [כן הוא ברבות שיר השירים בשם ר' יוסי הגלילי וע' עוד מענין יונתי ברבות בסדר לך לך פמ\"ה בשלח פכ\"א]."],["1988","4","<b>כי הנה הסתיו עבר</b>: שה\"ש ב, יא."],["1989","5","<b>קומי לך רעייתי יפתי</b>: שה\"ש ב, יג."],["1990","6","<b>רעייתי מלשון. . ומפרנס</b>: ראה שהש\"ר ע\"פ לסוסתי ובזח\"ג לג, ב."],["1991","7","<b>לכו לחמו בלחמי</b>: משלי ט, ה."]]],[2100490380,"כו' והוא בחי' מזון<sup data-n=\"1992\">8</sup> לנפש האלקי' והמצות בפ\"מ הן בחי' לבושין לנפש האלקי' כמבואר בספרי הקבלה. ולהבין ענין המזון דתורה וענין הלבושים שבמצות ואיך נעשו מזון ולבוש לנפש בג\"ע.\n<b>הנה</b> יש להקדים תחלה ענין הידוע דמה שהנשמה ירדה בגוף בעוה\"ז ירידה<sup data-n=\"1993\">9</sup> זו צורך עלי' היא כו'. והענין הוא להיות ידוע שהנשמה<sup data-n=\"1994\">10</sup> האלקי' אין כולה מתלבשת בגוף אלא<sup data-n=\"1995\">11</sup> רק קצת חלק קטן והארה בעלמא ממנה הוא שמתלבש' שהרי הנשמה גבוה מן המלאך כידוע והמלאך עומד בשליש העולם כידוע וא\"כ האיך יתצמצם הארת הנשמה כולה בגוף כו' אלא רק קצת הארה מאיר מאורה בגוף וכל עיקרה הוא למע' מן הגוף והוא הנק' מזלא כמארז\"ל דאע\"ג<sup data-n=\"1996\">12</sup> דאיהו לא חזי מזלי' חזי כו' והוא האר' בחי' המקיף מה שהנשמה מקפת על הגוף וכמ\"ש אך<sup data-n=\"1997\">13</sup> בצלם יתהלך איש כו' ומה שנק' בשם מזל ידוע שהוא מפני שעושה את ההמשכה וההזלה כענין מאכל משקה כו' כי פי' ניזל היינו מה שכבר נמשך והוזל בגוף מהארת הנשמה ופי' מזל הוא הארת המקיף שממשיך את ההארה שיאיר קצתה בגוף החומרי והיינו מזל לשון מפעיל מפני שמזלת לחבר ולקשר ההארה מלמע' בגוף למטה כו' וד\"ל וזהו שאנו או' אלקי<sup data-n=\"1998\">14</sup> נשמה כו' טהורה היא אתה בראת כו' ולכאורה אינו מובן דעל מה הוא או' טהורה היא קודם שא' אתה בראת אחר שעדיין לא נברא כו' אלא הענין הוא דטהורה היא קאי על חלק העליון שבנשמה שאינה מתלבשת כלל בגוף שהיא דבוקה למע' ועלי' ארז\"ל ישראל<sup data-n=\"1999\">15</sup> עלה במחשבה פי' עלה במחשבה למע' מעלה בבחי' עצמו' אא\"ס ב\"ה.\n<b>וביאור</b> הדבר הנה ארז\"ל בראשית<sup data-n=\"2000\">16</sup> בשביל ישראל שנק' ראשית כו' וכן כתי' ויקם עדות ביעקב ותורה שם בישראל פי' בשביל ישראל שנק' ראשית הוא ששם התו' כו' דמשמע ששרש ישראל למע' מן התורה, ולכאורה אינו מובן שהרי אמרו בזהר<sup data-n=\"2001\">17</sup> דג' קשרין הן ישראל מתקשראן באורייתא ואורייתא בקוב\"ה כו' משמע מזה דשרש ישראל למטה מן התורה כו', אך הענין דיש ב' מדריגות בישראל הא' הנק'",[["1992","8","<b>מזון לנפש. . והמצות. . בחי' לבושין. . בספרי הקבלה</b>: זח\"א רכד, א. וראה גם תניא פל\"ז. תו\"א כ, ד. וראה לקמן הערה 54."],["1993","9","<b>ירידה זו צורך עלי'</b>: ראה ספר המפתחות לספרי אדמו\"ר הזקן בערכו."],["1994","10","<b>שהנשמה האלקי' אין כולה מתלבשת בגוף</b>: קטע זה מובא באוה\"ת פ' ראה ע' תשסב."],["1995","11","<b>אלא רק קצת חלק קטן והארה בעלמא</b>: בהמשך תער\"ב ח\"א ע' קמב מבאר שזה בחי' נר\"ן לבד והוא העבודה שבסדר והדרגה במוח ולב כו' ע\"ש. וראה שם כרך ב' ע' תתל, ובכ\"מ."],["1996","12","<b>דאע\"ג דאיהו לא חזי</b>: מגילה ג, א."],["1997","13","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז."],["1998","14","<b>אלקי נשמה</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["1999","15","<b>ישראל עלה במחשבה</b>: ב\"ר רפ\"א. זח\"ב (קיט, סע\"א). ובזח\"א (א, ב. כד, א). ובכ\"מ."],["2000","16","<b>בראשית בשביל ישראל שנק' ראשית</b>: רש\"י ורמב\"ן ר\"פ בראשית. וראה ב\"ר פ\"א, ד. ויק\"ר פל\"ו, ד."],["2001","17","<b>בזהר דג' קשרין הן</b>: צ\"ע דבזח\"ג עג, א לא נאמר ג' קשרין כ\"א ג' דרגין כו', אמנם בודאי נמצא באיזה מקום בזהר או בתי' בל' ג' קשרין. וכפי הנראה אדה\"ז אמר בכל פעם בל' ג' קשרין שכן נזכר הל' בכל הדרושים (ד\"ה ובכן יתקדש תרנ\"ז בהחלק שלא הועתק)."]]],[2100490381,"ישראל דלעילא שהוא למע' מן התורה והוא שא' ישראל עלו במח', דהיינו כמו שהי'<sup data-n=\"2002\">18</sup> הוא ושמו בלבד לפני ההשתלשלות כל העולמות דאבי\"ע כו'. דהנה פי' עלה במחשבה היינו כאשר עלה<sup data-n=\"2003\">19</sup> ברצונו הפשוט כמו שהוא לבדו עדיין דקמי' כולא כלא חשיב<sup data-n=\"2004\">20</sup> כו' דכתי' בי' אני<sup data-n=\"2005\">21</sup> הוי' לא שניתי כו' פי' אין שינוי כלל בין קודם ההשתלשלות לאחר ההשתלשלות לפי שיש ב' מדרגות ברצון הא' אשר מתפשט באורות וכלים כמו שידוע דהאברים כולם נשמעים לרצון המוח שבראש עד הרגל לפי שהרצון שבמוח מתפשט בהם ומניע אותם בפרט בכל אבר ואבר וגם בכלל כוללם יחד כו'. אך בחינת הרצון הפשוט הוא אשר עדיין איננו מתפשט כלל באברי' אלא הוא נשאר בבחי' מקיף וסובב עליהם בהעלם מכל צד כו' והוא הנק' מזלא או צלם באדם התחתון למטה כנ\"ל, ומזה יובן הדוגמא למע' שזהו הנק' בכלל בחי' סוכ\"ע דהיינו מה שצופה<sup data-n=\"2006\">22</sup> ומביט במח' א' עד סוף כל הדורות בסקירה א' והיינו עלה במח' פי' במח' זו דרצה\"פ שהוא בחי' המקיף הכללי לכללו' כל ההשתלשלות בכל שית<sup data-n=\"2007\">23</sup> אלפי שני דהוי עלמא עד סוף כל הדורות בסוף אלף הז' כו' וד\"ל. וע\"ז ארז\"ל ישראל עלה במח' דהיינו במחשבה דעצמו' אור א\"ס הפשוט כו' דכתי' בי' אני ה' לא שניתי כנ\"ל, וזהו שאו' אנחנו על חלק הנשמה האלקי' שאיננה מתלבשת בגוף ששרשה היינו במח' עליונה שבעצמו' אא\"ס אלקי נשמה שנתת בי טהורה היא אתה בראת פי' אתה ברא\"ת בבחי' הבריאה יש מאין היינו חלק הנשמה בגוף שנק' ישראל דלתתא אבל חלק הנשמה שבבחינת מקיף, ששרשה דבוקה במח' שבעצמו' אא\"ס טהור\"ה היא פי' למע' היא מבחי' התהוות נברא יש מאין אלא הוא בבחי' א\"ס כמו קודם השתלשלות שאינו בגדר ההשתלשלות להתחלק לחלקים כלל כנ\"ל אלא שאח\"כ אתה בראת יצרת נפחת כו' שהן ג'<sup data-n=\"2008\">24</sup> חלקים בריאה יצי' עשי' שהוא כללות ענין סדרי ההשתלשלות בכל עולם לפי ערכו כמ\"ש לכבודי<sup data-n=\"2009\">25</sup> בראתיו יצרתי\"ו אף עשיתי\"ו וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> שארז\"ל בראשית בשביל ישראל שנק' ראשית, פי' לא על חלק הנשמה המתלבשת בגוף אמרו אלא [על] חלק העליון שאינו מתלבש בגוף כלל והיינו בחי' ישראל דלעילא שעלי' אמרו ישראל עלה במחשבה דהיינו במח' הקדומה שבעצמו' אא\"ס כנ\"ל שבשביל ישראל זה ניתנה התורה כמ\"ש ויקם<sup data-n=\"2010\">26</sup> עדות ביעקב ותורה שם בישראל פי' בישראל בשביל ישראל זה דלעילא לעילא שעלה במח' דעצמו' אא\"ס על היותו למע' הרבה מכל ההשתלשלו' כנ\"ל, וכענין",[["2002","18","<b>שהי' הוא ושמו בלבד</b>: פדר\"א פ\"ג. וראה דיוק גי' זו בהקדמת השל\"ה בתחלתה."],["2003","19","<b>עלה ברצונו הפשוט</b>: ראה אוצרות חיים שער העיגולים דרוש א\"ק בתחלתו. ע\"ח שער (א) דרוש עגולים ויושר ענף ב'. מבוא שערים ח\"א פ\"א."],["2004","20","<b>דקמי' כולא כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה (שער היראה) ש\"א, פ\"א (ז, רע\"א)."],["2005","21","<b>אני הוי' לא שניתי</b>: ישעי' מב, ח."],["2006","22","<b>שצופה ומביט. . עד סוף כל הדורות</b>: זח\"ב כ, ג. וראה הנסמן בהמ\"מ ללקו\"ת עקב טז, ד."],["2007","23","<b>שית אלפי שני דהוי עלמא</b>: ר\"ה לא, א."],["2008","24","<b>ג' חלקים בריאה. . עשי'</b>: ראה פע\"ח שער (ב) הברכות רפ\"ז. מאמרי אדה\"א הנחות תקע\"ז ע' רב. וש\"נ."],["2009","25","<b>לכבודי בראתיו יצרתיו</b>: ישעי' מג, ז."],["2010","26","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."]]],[2100490382,"מארז\"ל במי<sup data-n=\"2011\">27</sup> נמלך בנשמתן של צדיקים שעלו במח' הקדומה בבחי' העלא' מ\"נ וכמ\"ש במ\"א וד\"ל. וזהו שגם כל התורה נאמרה רק לישראל בלבד וכמו שמפורש בכל פרשה שבתו' דבר<sup data-n=\"2012\">28</sup> אל בנ\"י דוקא והיינו לפי שבשביל ישראל דלעילא הנ\"ל נמשך אור התו' למטה ומה שאמרו בזוהר דתלת קשרין הן ישראל מתקשראן באורייתא כו' היינו בישראל דלתתא שהוא חלק הנשמה המלובשת בגוף שהן מקבלי' האור מן התורה אבל ישראל דלעילא הנ\"ל הוא למעלה ממדרגת התורה הרבה עד שהתורה נמשכת ונעשית רק מישראל זה שעלה במח' כמ\"ש ותורה<sup data-n=\"2013\">29</sup> שם בישראל שמישראל נעשית תורה למטה כו' וד\"ל. ובזה יובן מה שאמרו בראשית בשביל ישראל כו' ולכאורה מאחר דעיקר הם ישראל הל\"ל בהדיא בשביל ישראל ולמה אמר בראשי\"ת אלא משום דב' מיני ישראל יש כנ\"ל דקדק לומר בראשית פי' בשביל אותו ישראל שנק' ראשי\"ת היינו ישראל שעלה במח' ולא ישראל שלמטה וד\"ל.\n<b>אך</b> הנה לפ\"ז יש ריחוק גדול בין ישראל דלעילא לישראל דלתתא שעליי' ישראל דלעילא היינו בתכלית הרוממו' כנ\"ל שעלה במח' דעצמו' אא\"ס ב\"ה וישראל דלתתא הם הנשמו' שמלובשים בגופים למטה בעולם הנפרד יש מאין כו' וכמאמר אתה בראת כו' והתורה היא בחי' ממוצע ביניהם כי עפ\"י הנ\"ל בפי' ותורה שם בישראל דלעילא וענין ישראל מתקשראן באורייתא כו' ישראל דלתתא הרי התורה הממוצע בין ישראל דלעילא בישראל דלתתא כו'. ויש להבין מהיכן יש כח ההתחברות הזאת שיתחבר ישראל דלעילא בישראל דלתתא שרחוקי' זמ\"ז בתכלית ע\"י התורה שהיא בחי' ממוצע והרי גם התו' צריכה לבא בהמשכה והשתלשלות מישראל דלעילא וכמ\"ש ותורה שם בישראל מהו הגורם המשכ' התורה להיות בחי' ממוצע ולהיות ישראל דלתתא מתקשראן באורייתא ויתחברו ישראל דלעילא וישראל דלתתא כו'. הענין הוא שכח המחבר הזה הוא בתפלה דוקא לפי שהתפלה<sup data-n=\"2014\">30</sup> נק' סולם כידוע וכמ\"ש סולם<sup data-n=\"2015\">31</sup> מוצב ארצה וראשו מגיע השמימה כו' עד\"מ הסולם שרגליו נעוצי' למטה בארץ וראשו מגיע השמימה כך התפלה מתחלת למט' והיינו בהעלא' ניצוץ האלקי המלובש בגוף ע\"י רעותא דלבא בכל<sup data-n=\"2016\">32</sup> לבבך ובכל נפשך כו' וראשו מגיע השמימה היינו בהתקשרות הנפש בעצמות אא\"ס ב\"ה שעלה שם במח' כנ\"ל והיינו חיבור וקישור ישראל דלתתא בישראל דלעילא שנק' מזלא והוא מה שאו' טהור\"ה היא שלמע' מבחי' בריאה כנ\"ל. וגם סדר<sup data-n=\"2017\">33</sup> התפלה הוסדה כדוגמת הסולם שעולה במעלות זו אחר זו כו' כך בתחלה פסד\"ז דהיינו מה שהנפש המלובש בגוף תתפשט מבחי' החומרי' שלה ע\"י התבוננות בשירות ותשבחות כו' ואח\"כ",[["2011","27","<b>במי נמלך בנשמתן של צדיקים</b>: רות רבא פ\"ב, ג (בשינוי לשון קצת)."],["2012","28","<b>דבר אל בנ\"י</b>: בשלח יד, ב ובכ\"מ."],["2013","29","<b>ותורה שם בישראל</b>: תהלים עח, ה."],["2014","30","<b>שהתפלה נק' סולם</b>: זח\"א בהשמטות רסו, ב. ח\"ג (תוספת) שו, ב. תקו\"ז תמ\"ה (פג, א)."],["2015","31","<b>סולם מוצב ארצה</b>: ויצא כח, יב."],["2016","32","<b>בכל לבבך ובכל נפשך</b>: ואתחנן ו, ה. וראה לקו\"ת האזינו עא, ד."],["2017","33","<b>סדר התפלה</b>: ראה ג\"כ תו\"א ל, א. לקו\"ת ראה יט, ד."]]],[2100490383,"ביוצר אור מזכירים שירות ותשבחות של המלאכים והן בזה יותר גבוהים מה שאין להם חומר גופני כ\"כ והיינו שאו' והאופנים ברעש גדול כו' ואח\"כ בק\"ש שאומרים שמע<sup data-n=\"2018\">34</sup> ישראל הכוונה על בחי' ישראל דלעילא הנ\"ל שעלה במח' והוא בחי' מזלא המקיף על האדם למטה בו דוקא נעשה יח\"ע ויח\"ת למהוי אחד באחד כו' לפי שישראל זה עלה במח' למע' מכל ההשתלשלו' דיח\"ע ותתאה כו' וזהו שמ\"ע ישרא\"ל הוי' אלקינו הוי', פי' ישראל דוקא מטעם שבכחו דוקא ליחד יחודים הללו מטעם הנ\"ל שהי' כלול במח' תחלה להיות בבחי' א\"ס ממש כמו שהוא לבדו כו' וד\"ל. אך ע\"י מה יגיע בחי' ישראל דלתתא לישראל דלעילא זה הוא מה שאמר ואהבת את ה' כו' פי' אה'<sup data-n=\"2019\">35</sup> ידוע שהוא ל' רצון שע\"י דוקא חיבור וקישור להוי' שהוא בחי' סוכ\"ע באלקיך הוא חלק התחתון שמאיר בגוף כו' ע\"ד שיתחברו שניהם יחדיו כו', ובכל נפשך היינו למסור<sup data-n=\"2020\">36</sup> נפשו בא' כמ\"ש אליך<sup data-n=\"2021\">37</sup> ה' נפשי אשא וזהו בש\"ע שישראל זה עלה במח' ממש וה\"ז כדמיון הסולם ממש שראשו מגיע השמימה והוא בש\"ע והתחלתה נעוץ בארץ דהיינו בפסד\"ז כנ\"ל וד\"ל, ונמצא ע\"י התפלה להיותה ממוצעת לקשר ולחבר הסוף עם התחלה להיות נעוץ<sup data-n=\"2022\">38</sup> סופן בתחלתן כו' לכך גם התו' נמשכת מישראל דלעילא ע\"י אמצעות התפלה להיות בחי' ממוצע מישראל דלעילא לישראל דלתתא להיות ותורה שם בישראל וזהו שארז\"ל האומר<sup data-n=\"2023\">39</sup> אין לי אלא תו' אפי' תו' אין לו דבלא סולם דתפילה אין התו' נמשכת כלל מלמעלה כו' וד\"ל.\n<b>וזהו</b> קומי<sup data-n=\"2024\">40</sup> לך רעייתי פי' המשך הפסוקים כך הוא כי<sup data-n=\"2025\">41</sup> הנה הסתיו עבר הגשם חלף כו' הנצנים<sup data-n=\"2026\">42</sup> נראו בארץ כו' התאנה<sup data-n=\"2027\">43</sup> חנטה כו' קומי לך רעייתי יפתי ולכי לך יונתי בחגוי הסלע כו', והנה הקרי<sup data-n=\"2028\">44</sup> קומי לך והכתי' קומי לכי רעייתי כו' ולכי לך, והטעם יובן בהקדים תחלה מהו ענין הקר\"י קומי ל\"ך כו'. הנה מבואר למע' דב' מדרגו' בישראל הא' ישראל דלעילא והב' ישראל דלתתא כו' וזהו ענין שאומר על בחי' ישראל דלתתא קומי ל\"ך כלומר קומי והתעלי לעצמ\"ך ושרשך במחשבה הנק' ישראל דלעילא והוא בחי' מזלא למט' כו' וע\"י מ\"ה תקום ותעלה להיות נעוץ סב\"ת חלק התחתון בחלק העליון כנ\"ל, היינו ע\"י התפלה שנק' סולם מטעם הנ\"ל באריכות, וזהו שהכתי' לכי והוא אותיו' כ\"ף יו\"ד פי' כף הוא כמו כף יד כף בחי' סוכ\"ע הנ\"ל משום דכתי' בי' ומתחת<sup data-n=\"2029\">45</sup> זרועות עולם, מפני שהוא המקיף",[["2018","34","<b>שמע. . יח\"ע</b>: ואתחנן ו, ד. זהר בראשית יח, ב. פסחים נו, א."],["2019","35","<b>אה'. . לשון רצון</b>: ראה שרש ישע שרש אבה הובא בס' החקירה להצ\"צ מערכת אהב (צב, רע\"א). תו\"א מקץ לב, ג. לקו\"ת נשא כו, ב."],["2020","36","<b>למסור נפשו באחד</b>: ראה זהר (רע\"מ) משפטים קיט, א. צו לג, א."],["2021","37","<b>אליך ה' נפשי</b>: תהלים כה, א."],["2022","38","<b>נעוץ סופן בתחלתן</b>: ס\"י פ\"א, מ\"ז."],["2023","39","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["2024","40","<b>קומי לך רעייתי</b>: שה\"ש ב, י."],["2025","41","<b>כי הנה הסתיו</b>: שה\"ש ב, יא."],["2026","42","<b>הנצנים נראו בארץ</b>: שה\"ש ב, יב."],["2027","43","<b>התאנה חנטה</b>: שם יג,"],["2028","44","<b>הקרי קומי. . שרש הנשמה</b>: ראה ג\"כ לקו\"ת שה\"ש יז, א. יח, ד."],["2029","45","<b>ומתחת זרועות עולם</b>: דברים לג, כז."]]],[2100490384,"וסובב את הכל בסקירה א' כנ\"ל, והיו\"ד<sup data-n=\"2030\">46</sup> הוא החכ' כידוע והיינו התו' דאורייתא<sup data-n=\"2031\">47</sup> מחכ' נפקת מאחר דבשביל ישראל זה העליון נמשך אור התו' וכמ\"ש ותורה שם בישראל כנ\"ל, וזהו לכי כ\"ף ויו\"ד מפני ששם שרש הנשמה כמו שעלתה במח' כנ\"ל, לכך הכתי' כ\"ף ויו\"ד והקרי ל\"ך כלומר לעצמותך ממש וד\"ל. וזהו קומי לך רעייתי, פי' אחר שקומי לך לעצמותך אז דוקא נק' רעייתי, דהנה פי' רעייתי ידוע שהוא מל' רועה הזן ומפרנס כו' כך ישראל<sup data-n=\"2032\">48</sup> מפרנסי' לאביהם שבשמים כו'.\n<b>וביאור</b> הדברים הנה בתו' נא' לכו לחמו בלחמי כו' פי' עד\"מ הלחם אשר הוא מחזק השכל והחיות להתפשט בכלי הגוף להיות הנפש מפרנס וזן את כל כלי הגוף כי בתענית מסתלק השכל והחיו' והכלי הגוף אין להם מזון וחיו' מחיו' הנפש וכשאוכל הלחם תשוב רוחו עליו להתפשט בכל האברים בתוס' ההתפשטות לאורך ורוחב כו' כך הנמשל יובן למשכיל למע' דאא\"ס הרי הוא מובדל בערך מכל ההשתלשלו' דאבי\"ע, וכדי שיקרא חכים או מבין חסד<sup data-n=\"2033\">49</sup> דרועא ימינא כו' צריך שימשיכו אותו להתפשט בבחי' אורות וכלים והן בחי' י\"ס חכים ומבין כו', אבל מצד עצמותו הרי א' לאו דאית לך צדק ידיעא כו' ולאו מכל אינון מדות כלל כי הוא<sup data-n=\"2034\">50</sup> המדע כו' והחכ' איננה נמשכת רק בבחי' עשי' וכמ\"ש כולם<sup data-n=\"2035\">51</sup> בחכ' עשית כידוע וע\"י מה ימשיכו אור א\"ס באורות וכלים דאצי' היינו ע\"י התורה<sup data-n=\"2036\">52</sup> שהיא נמשל[ה] ללחם כמ\"ש לכו לחמו בלחמי וכנ\"ל שהלחם משיב את הנפש בתוך הגוף כך יושב אור א\"ס להיות מתפשט בחכ' ובינה כו' וד\"ל. ומה שנא' לעשות<sup data-n=\"2037\">53</sup> את כל דברי התו' הזאת כו' פי' לעשות התורה ולהמשיכה מלמעלה למטה היינו ע\"י הדיבור בד\"ת וכמ\"ש ודברת<sup data-n=\"2038\">54</sup> בם דידוע שהוא ענין הנהגה והמלאכה כמו ידבר<sup data-n=\"2039\">55</sup> עמים כו', והענין הוא לפי שע\"י הדיבור נמשך אור א\"ס בחכ' שבתורה והיינו לעשות את התו' שעושין את התורה וזהו ענין עוסק בתו' לשמ\"ה פי' לשם התו' עצמה לעשותה שתומשך מלמעלה כו' וזהו א\"ת<sup data-n=\"2040\">56</sup> בנייך אלא בוניך דעוסקים בבנינו של עולם פי' לבנות עולם הנאצל להיות נק' חסיד ומבין וחסד כו', והוא ע\"י הדיבור בד\"ת דוקא כי רוח<sup data-n=\"2041\">57</sup> אייתי רוח כו', והקב\"ה<sup data-n=\"2042\">58</sup> יושב ושונה כנגדו כמ\"ש<sup data-n=\"2043\">59</sup> במ\"א ע\"פ ודברי אשר שמתי בפיך כו' וד\"ל. ואין כח זה להמשיך אור א\"ס בחכ' שבתו' להיות עושה את התו' כנ\"ל אלא בישראל",[["2030","46","<b>והיו\"ד הוא החכ'</b>: ראה זהר ויקרא יז, א."],["2031","47","<b>דאורייתא מחכ' נפקת</b>: זח\"ב קכא, א. וראה שם פה, א."],["2032","48","<b>ישראל מפרנסי' לאביהם שבשמים</b>: זח\"ג ז, ב. שהש\"ר א, ע\"פ לסוסתי. יל\"ש פקודי רמז תיח."],["2033","49","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה (פתח אלי')."],["2034","50","<b>כי הוא המדע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"י. שמונה פרקים להרמב\"ם בסופו."],["2035","51","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["2036","52","<b>התורה שהיא נמשלה ללחם</b>: ראה שבת קכ, א. לקו\"ש כרך ד' ע' 1038 הערה 26."],["2037","53","<b>לעשות את כל דברי התו' הזאת</b>: האזינו לב, מו. וראה לקו\"ת שה\"ש ב, א."],["2038","54","<b>ודברת בם</b>: ואתחנן ו, ז."],["2039","55","<b>ידבר עמים</b>: תהלים מט, ד."],["2040","56","<b>א\"ת בנייך אלא בונייך</b>: ברכות סד, א. וש\"נ."],["2041","57","<b>רוח אייתי רוח</b>: זח\"ב קסב, ב."],["2042","58","<b>והקב\"ה יושב ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. יל\"ש איכה רמז תתרלד."],["2043","59","<b>כמ\"ש במ\"א ע\"פ ודברי אשר שמתי בפיך</b>: ישעי' נט, כא. וראה לקו\"ת ראה כ, ב."]]],[2100490385,"דוקא וכמ\"ש ותורה שם בישראל כו' וזהו שציוה לישראל דוקא ודברת בם ולא לזולתו לפי שישראל עלה במח' עילא' שבעצמו' אור א\"ס שלפניו כל ההשתלשלו' כנ\"ל ומשם נמשך אור א\"ס בחכ' (וכמשל הלחם שיחזק המוח כו') וכמ\"ש והחכ'<sup data-n=\"2044\">60</sup> מאין תמצא ע\"כ כשישראל דוקא עוסק בתו' בדיבור שהוא שממשיך את התו' משרשה ומקורה במחשבה דהיינו בחי' מזל העליון שהוא מקיף וסובב את הכל כנ\"ל בענין בראשית בשביל ישראל שנק' ראשית כו' שהוא בחי' ישראל דלעילא כו' וד\"ל.\n<b>וזהו</b> קומי לך רעייתי, פי' אחר שעלה ישראל במחשבה עליונה וחזרה לעצמותה ושרשה במקור חוצבה בתחלה הרי משם גם שרש התורה נמשכת מאי\"ן ליש וכמ\"ש והחכ' מאין תמצא ע\"כ אז דוקא נקראת רעיית\"י כלומר פרנסתי שמפרנסין לאביהם שבשמים דהיינו מפני שממשיכים ע\"י הדיבור בד\"ת אור א\"ס בחכ' הרועה הזן ומפרנס כו' אבל אם לא מטעם שעלה במח' שמשם שרש התו' נמשך כנ\"ל לא הית' נק' רעייתי אלא אחר שקומ\"י ל\"ך אז נק' רעיית\"י וד\"ל.\n<b>וביאור</b><sup data-n=\"2045\">61</sup> ענין יפתי אלו המצות מעשיות בפ\"מ, והטעם שהתורה נק' רעית\"י והמצות יפת\"י מבואר למעלה משום דהתורה הוא מזון לנפש האלקי' בג\"ע והמצות הן בחי' לבושי' לנפש האלקי' בג\"ע וכמו שהלבושים מייפים האדם כך המצות מייפים הנפש בג\"ע כו'. ולהבין הטעם למה נק' המצות בשם לבושים יובן בהקדים תחלה שמדת<sup data-n=\"2046\">62</sup> המלכות נק' בשם לבוש כמ\"ש יביאו<sup data-n=\"2047\">63</sup> לבוש מלכות וכתיב ה'<sup data-n=\"2048\">64</sup> מלך גיאות לבש כו'. וביאור הדברים יובן בהיות ידוע בפי' מדת מלכות שהוא ע\"י בחי' לבוש המסתיר ומעלים את העצמות כמשל הלבוש המסתיר ומעלים את האדם כו' כי הנה מה שנראה העולם לעין בבחי' יש ודבר נפרד כמו השמים וארץ הגשמיי' ואפי' עולמות העליונים הרוחניים הן בבחי' יש נפרד הכל הוא מפני שצמצם אור אלקי א\"ע והסתיר והעלים את עצמותו כי אם לא הי' מעלים ומסתיר א\"ע הרי בהגלות נגלות זיו ואור אלקי לא הי' דבר חוץ ממנו בבחי' יש נפרד לעצמו כלל כי הי' הכל כלולי' בבחי' אלקות ואין עוד מלבדו כלל כו' והמופת לזה שבהתחדשות הבריאה יש מאין הי' ע\"י צמצום והעלם כו' שלעתיד שיחזור האור למקורו ויהי' חידוש הבריאה מחדש כתיב כי<sup data-n=\"2049\">65</sup> השמים כעשן נמלחו והארץ כבגד תבלה כי לא יהיו שמים וארץ הנראין עתה בבחי' יש נפרד אלא יהיו שמים חדשים וארץ חדשה אשר אני עושה אני דוקא מחדש הבריאה מפני שהבריאה שעבר תבטל בהגלות נגלות האור וכמ\"ש ונגלה<sup data-n=\"2050\">66</sup> כבוד ה' כו' וא\"כ מוכרח שעכשיו מפני ההעלם וההסתר הן נראין ליש כו' והוא לפי שאין מלך בלא עם פי' מפני שצריך להתפשט מדת מלכות על בחי' נפרד דוקא כי אין<sup data-n=\"2051\">67</sup> מלך בלא עם וא\"כ צריך שיצמצם ויעלים",[["2044","60","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["2045","61","<b>וביאור ענין יפתי</b>: מכאן נמצא בגוכתי\"ק 1025 ב, א."],["2046","62","<b>שמדת המלכות נק' בשם לבוש</b>: ראה לקו\"ת דרושים לר\"ה נג, ד. אוה\"ת שלח ע' תריט."],["2047","63","<b>יביאו לבוש מלכות</b>: אסתר ו, ח."],["2048","64","<b>ה' מלך גיאות לבש</b>: תהלים צג, ג."],["2049","65","<b>כי השמים כעשן נמלחו</b>: ישעי' נא, ו."],["2050","66","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["2051","67","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל."]]]]});
